window.SUBJECTS.push({"id":"pol","n":"Polity","tab":"Polity","w":"The Constitution, rights, Parliament, courts, states and constitutional bodies.","topics":[{"id":"constitution","n":"Making and Features of the Constitution","qs":[{"id":"q0023","q":"Which of the following languages was NOT included in the Eighth Schedule to the Constitution by the 71st Amendment Act of 1992?","o":["Konkani","Nepali","Manipuri","Maithili"],"a":3,"x":"The 71st Amendment (1992) added Konkani, Manipuri and Nepali to the Eighth Schedule. Maithili came later, with Bodo, Dogri and Santhali, by the 92nd Amendment (2003).","e":"The Eighth Schedule now lists 22 languages.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0024","q":"Which of the following is NOT a feature of the Indian Constitution?","o":["Written constitution","Judicial review","Sovereignty of parliament","Single citizenship"],"a":2,"x":"India follows a blend of parliamentary sovereignty and judicial supremacy: Parliament's laws can be struck down by courts, so 'sovereignty of Parliament' (a British feature) is not a feature of the Indian Constitution.","e":"Written constitution, judicial review and single citizenship are Indian features.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0027","q":"After independence, Part C states and Part D territories were constituted as union territories under the ______ Constitutional Amendment Act.","o":["9th","6th","7th","8th"],"a":2,"x":"The 7th Amendment (1956) carried out the States Reorganisation Act: it ended the Part A/B/C/D classes, creating 14 states and 6 union territories.","e":"The same amendment allowed one High Court to serve two or more states.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0030","q":"Which of the following Articles of the Indian Constitution states the duty of the Union to promote and develop the Hindi language?","o":["Article 328","Article 343","Article 351","Article 327"],"a":2,"x":"Article 351 directs the Union to promote the spread of Hindi and develop it as a medium of expression for India's composite culture.","e":"Article 343: Hindi in Devanagari script is the official language of the Union.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0117","q":"Which of the following languages was added to the Eighth Schedule in 2004?","o":["Tamil","Konkani","Maithili","Manipuri"],"a":2,"x":"Maithili, with Bodo, Dogri and Santhali, was added to the Eighth Schedule by the 92nd Amendment Act of 2003, which came into force in January 2004.","e":"Konkani, Manipuri and Nepali had been added earlier, in 1992.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0151","q":"What was the key reason for the Union Government's centralisation of power during the framing of the Indian Constitution?","o":["To prevent regional parties from gaining power","To ensure that state governments were independent","To protect the unity and integrity of the federal nation","To limit the powers of state governments"],"a":2,"x":"The framers gave the Union strong powers mainly to protect India's unity and integrity after Partition and the integration of the princely states.","e":"That is why India is called a 'Union of States' with a strong centre.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0188","q":"The National Festival of India, Republic Day, commemorates the adoption of which document?","o":["The Indian Independence Act","The Quit India Resolution","The Poona Pact","The Constitution of India"],"a":3,"x":"Republic Day (26 January) marks the day the Constitution came into force in 1950. It had been adopted on 26 November 1949.","e":"26 January was chosen because the Congress declared Purna Swaraj on that day in 1930.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0358","q":"Which Article of the Constitution states that the official language of the Union shall be Hindi in the Devanagari script, with the international form of Indian numerals for official purposes?","o":["Article 340(1)","Article 341(1)","Article 343(1)","Article 342(1)"],"a":2,"x":"Article 343(1): the official language of the Union shall be Hindi in the Devanagari script, with the international form of Indian numerals.","e":"14 September (1949) is celebrated as Hindi Diwas.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0382","q":"Where in the Constitution of India are the provisions regarding the Eighth Schedule, which lists various languages for official purposes, found?","o":["Article 344(1) and Article 351","Article 344(2) and Article 350","Article 10 and Article 344","Article 51A and Article 352"],"a":0,"x":"The Eighth Schedule is linked to Article 344(1) (Official Language Commission) and Article 351 (development of Hindi).","e":"22 languages are now listed.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0395","q":"The Indian President impeachment process has been taken from the Constitution of ________.","o":["The US","The UK","Canada","South Africa"],"a":0,"x":"The procedure for impeaching the President (Article 61) is borrowed from the Constitution of the USA.","e":"Also from the USA: Fundamental Rights, judicial review, removal of SC and HC judges.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0396","q":"The official languages of India are included in which Schedule of the Indian Constitution?","o":["10th","4th","9th","8th"],"a":3,"x":"The Eighth Schedule lists India's recognised languages (now 22).","e":"Tenth Schedule: anti-defection. Ninth Schedule: laws protected from judicial review.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0512","q":"Which among the following Constitutional Amendments is popularly known as \"Anti-Defection Law\"?","o":["52nd","40th","61st","69th"],"a":0,"x":"The 52nd Amendment (1985) is the anti-defection law; it added the Tenth Schedule.","e":"The 91st Amendment (2003) removed the 'split' exception and capped ministries at 15% of the House.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0515","q":"In which of the following years was the last meeting of the Constituent Assembly held?","o":["1940","1947","1959","1950"],"a":3,"x":"The Constituent Assembly met for the last time on 24 January 1950, when members signed the Constitution and elected Dr Rajendra Prasad the first President.","e":"It first met on 9 December 1946; the Constitution was adopted on 26 November 1949.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0553","q":"Who was the chairman of the States Committee of the Constituent Assembly?","o":["Jawaharlal Nehru","Rajendra Prasad","B.R. Ambedkar","Gopinath Bardoloi"],"a":0,"x":"Jawaharlal Nehru chaired the States Committee of the Constituent Assembly, which negotiated with princely states; he also chaired the Union Powers and Union Constitution Committees.","e":"Drafting Committee: Dr B. R. Ambedkar. Rules of Procedure and Steering Committees: Dr Rajendra Prasad.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0554","q":"Which among the following Amendment Bills is known as the ‘Women Reservation Bill’ ?","o":["102","108","105","110"],"a":1,"x":"The 108th Constitution Amendment Bill (2008) was the Women's Reservation Bill; it passed the Rajya Sabha in 2010 but lapsed.","e":"In 2023 women's reservation was finally enacted as the 106th Amendment Act (Nari Shakti Vandan Adhiniyam).","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0555","q":"Which among the following Parts of the Indian Constitution is related with the special provisions relating to certain classes?","o":["XIII","XV","XIV","XVI"],"a":3,"x":"Part XVI (Articles 330–342) has special provisions for certain classes: seats for SCs and STs, the Anglo-Indian community, and the SC, ST and OBC Commissions.","e":"Part XV: Elections. Part XIV: Services. Part XIII: Trade and commerce.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0592","q":"The concept of \"Equal Protection Under Law\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["Australia","United Kingdom","Ireland","United States of America"],"a":3,"x":"'Equal protection of the laws' in Article 14 is borrowed from the US Constitution (14th Amendment); 'equality before law' comes from Britain.","e":"Also from the USA: judicial review, Fundamental Rights, the President as Supreme Commander.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0595","q":"Which among the following Constitutional Amendment incorporated Dadra and Nagar Havelli as a Union Territory?","o":["8th","9th","10th","11th"],"a":2,"x":"The 10th Amendment (1961) made Dadra and Nagar Haveli a Union Territory after its freedom from Portugal.","e":"12th Amendment (1962): Goa, Daman and Diu. 14th Amendment (1962): Puducherry.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0633","q":"Which among the following constitutional amendment is the Land Boundary Agreement (LBA) between India and Bangladesh?","o":["98th","99th","101st","100th"],"a":3,"x":"The 100th Constitution Amendment Act (2015) put the India–Bangladesh Land Boundary Agreement into effect, swapping enclaves (chhitmahals).","e":"India transferred 111 enclaves and received 51.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0672","q":"Which among the following words is not there in the Preamble of the Constitution of India?","o":["Fraternity","Justice","Equality","Protection"],"a":3,"x":"The Preamble speaks of Justice, Liberty, Equality and Fraternity. 'Protection' is not in it.","e":"Words added by the 42nd Amendment (1976): Socialist, Secular, Integrity.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0673","q":"Which among the following constitutional amendments added Bodo, Dogri, Maithili and Santhali languages in the Eighth Schedule?","o":["88th","92nd","98th","102nd"],"a":1,"x":"The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali to the Eighth Schedule, taking the total to 22.","e":"The 71st Amendment (1992) had added Konkani, Manipuri and Nepali.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0675","q":"The concept of \"Five Year Planning\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["United States","United Kingdom","USSR","Japan"],"a":2,"x":"The idea of Five-Year Plans is borrowed from the USSR (Soviet Union), along with the Fundamental Duties and the ideals of justice in the Preamble.","e":"The Soviet Union ran its first Five-Year Plan from 1928.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0713","q":"The concept of \"Freedom of trade and commerce\" in the Indian Constitution is borrowed from the constitution of which of the following countries?","o":["Australia","Canada","United States","Japan"],"a":0,"x":"Freedom of trade, commerce and intercourse (Part XIII), the Concurrent List and joint sittings of Parliament are borrowed from Australia.","e":"From Canada: a federation with a strong centre, and residuary powers with the Centre.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0714","q":"Which among the following constitutional amendments incorporated Goa, Daman and Diu in the Indian Union?","o":["5th","18th","22nd","12th"],"a":3,"x":"The 12th Amendment (1962) added Goa, Daman and Diu to India as a Union Territory, after Operation Vijay (1961).","e":"Goa became a state in 1987.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0715","q":"In which year did Lord Mountbatten address the Constituent Assembly for the last time?","o":["1945","1946","1947","1948"],"a":2,"x":"Lord Mountbatten addressed the Constituent Assembly at the midnight session of 14–15 August 1947 as Governor-General; his time ended in June 1948.","e":"Nehru's 'Tryst with Destiny' speech was made at the same session.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0752","q":"As of April 2020, which one of the following is not mentioned in the Preamble to the Constitution of India?","o":["Justice","Peace","Equality","Liberty"],"a":1,"x":"The Preamble secures Justice, Liberty, Equality and Fraternity. 'Peace' is not in it.","e":"The Preamble was amended only once, by the 42nd Amendment (1976).","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q0755","q":"As of April 2020, which one of the following languages is not a part of the Eighth Schedule to the Constitution of India?","o":["Tulu","Sindhi","Sanskrit","Urdu"],"a":0,"x":"Tulu (coastal Karnataka and Kerala) is not in the Eighth Schedule. Sindhi, Sanskrit and Urdu are.","e":"Tulu speakers have long asked for its inclusion.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q6800","q":"Who among the following was the chairman of the Union Powers Committee of the Constituent Assembly?","o":["Sardar Vallabhbhai Patel","H.C. Mookherjee","Jawaharlal Nehru","Rajendra Prasad"],"a":2,"x":"Jawaharlal Nehru chaired the Union Powers Committee of the Constituent Assembly.","e":"","src":["Junior Assistant 25 Aug 2021"]},{"id":"q1769","q":"Which schedule of the Indian constitution deals with forms of Oaths or Affirmations?","o":["First","Third","Fifth","Sixth"],"a":1,"x":"The Third Schedule contains the forms of oaths and affirmations for ministers, MPs, MLAs, judges and the CAG.","e":"1st: states and UTs; 2nd: salaries; 3rd: oaths; 4th: Rajya Sabha seats.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1773","q":"In which year did the Eighty sixth amendment of the Indian constitution took place?","o":["2002","2000","1998","2005"],"a":0,"x":"The 86th Amendment (2002) added Article 21A (free and compulsory education for ages 6–14), changed Article 45 and added the 11th Fundamental Duty.","e":"Right to Education Act followed in 2009.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q2053","q":"In which year did the third amendement of the Indian constitution take place?","o":["1951","1954","1953","1952"],"a":1,"x":"The Third Amendment (1954) changed Entry 33 of the Concurrent List on trade and commerce in essential goods.","e":"First Amendment: 1951; Seventh: 1956 (States Reorganisation).","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2095","q":"Through which constitutional amendment words Socialist, Secular and Republic were added in the Preamble of the Indian constitution?","o":["First","Eleventh","Forty fourth","Forty second"],"a":3,"x":"The 42nd Amendment (1976) added 'Socialist', 'Secular' and 'Integrity' to the Preamble.","e":"42nd Amendment is called the 'mini-Constitution'.","src":["Junior Clerk 13 Nov 2021 S1"],"k":"'Republic' was already in the original Preamble of 1950; only 'Socialist' and 'Secular' (and 'Integrity') were added by the 42nd Amendment."},{"id":"q2418","q":"Which of the following countries doesn't have a single, written Constitution, but rather a series of documents and decisions that, taken collectively, are referred to as the constitution?","o":["Germany","USA","United kingdom","Canada"],"a":2,"x":"The United Kingdom has no single written constitution; its constitution is made of statutes, conventions and court decisions.","e":"India's is the longest written constitution in the world.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2506","q":"Which of the following parts of the Indian Constitution is related to the amendments to the Constitution?","o":["Part XIX","Part XX","Part XXI","Part XXII"],"a":1,"x":"Part XX (Article 368) deals with amending the Constitution.","e":"Article 368: amendment procedure.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2507","q":"In which year had M. N. Roy suggested for the formation of a Constituent Assembly?","o":["In 1932","In 1933","In 1934","In 1935"],"a":2,"x":"M.N. Roy first proposed a Constituent Assembly for India in 1934; the Congress officially demanded one in 1935.","e":"The Assembly finally met on 9 December 1946.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2621","q":"With respect to the Indian constitution, which of the following pair is/are correct? I. Third Schedule – Forms of Oaths or Affirmations II. Fourth Schedule – Allocation of seats in the Council of States","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Third Schedule has forms of oaths and affirmations; the Fourth Schedule allocates Rajya Sabha seats to states and UTs. Both pairs are correct.","e":"3rd oaths, 4th Rajya Sabha seats.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2891","q":"With respect to the Indian constitution, which of the following pair is/are correct? I. Tenth Schedule – Validation of certain Acts and Regulations II. Ninth Schedule – Provisions as to disqualification on ground of defection.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both pairs are swapped: the Ninth Schedule validates certain Acts and Regulations (land reforms), and the Tenth Schedule covers disqualification on grounds of defection (52nd Amendment, 1985).","e":"9th: validation; 10th: anti-defection.","src":["Junior Clerk 17 Nov 2021 S1"]},{"id":"q6223","q":"Which of the following languages is mentioned in the Eighth schedule of the Indian constitution? I. Gujarati II. Punjabi","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Both Gujarati and Punjabi are among the 22 languages in the Eighth Schedule.","e":"","src":["Junior Clerk 9 Nov 2021 S3"]},{"id":"q1346","q":"Who among the following is recognised as the \"Father of the Constitution of India\"?","o":["Rajendra Prasad","B. R. Ambedkar","Sachchidananda Sinha","Jawaharlal Nehru"],"a":1,"x":"Dr B. R. Ambedkar, chairman of the Drafting Committee, is called the 'Father of the Indian Constitution'.","e":"Sachchidananda Sinha was the Constituent Assembly's first (temporary) chairman.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1350","q":"The concept of 'Judicial Review' in the Indian Constitution has been borrowed from the constitution of which of the following countries?","o":["United Kingdom","Australia","Japan","United States of America"],"a":3,"x":"Judicial review is borrowed from the Constitution of the USA (Marbury v. Madison, 1803).","e":"From the UK: parliamentary government, rule of law, single citizenship.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1360","q":"Which among the following Constitutional Amendments included the Tamil Nadu Reservation Act of 1994 in the 9th Schedule to protect it from judicial review?","o":["89th","65th","76th","72nd"],"a":2,"x":"The 76th Amendment (1994) placed the Tamil Nadu Reservation Act (69% reservation) in the Ninth Schedule to protect it from judicial review.","e":"The Ninth Schedule was created by the 1st Amendment (1951).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q4065","q":"Which among the following Schedules in the Indian Constitution deals with the validation of certain acts and regulations?","o":["Eighth","Ninth","Tenth","Seventh"],"a":1,"x":"The Ninth Schedule (added by the 1st Amendment, 1951) protects listed laws and regulations from challenge in court.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q6930","q":"The concept of 'Rule of Law' in the Indian Constitution is borrowed from the constitution of __________.","o":["Australia","Germany","United States of America","United Kingdom"],"a":3,"x":"The Rule of Law was borrowed from the British (UK) Constitution.","e":"","src":["Stenographer 14 Aug 2021 S2"]},{"id":"q6973","q":"Which among the following Schedule in the Indian Constitution contains provisions as to the Administration and Control of Scheduled Areas and Scheduled Tribes?","o":["Third","Fourth","Fifth","Sixth"],"a":2,"x":"The Fifth Schedule deals with the administration and control of Scheduled Areas and Scheduled Tribes; the Sixth covers tribal areas of Assam, Meghalaya, Tripura and Mizoram.","e":"","src":["Stenographer 8 Aug 2021"]},{"id":"q6975","q":"The concept of Cabinet system in the Indian Constitution is borrowed from the constitution of ____________.","o":["United Kingdom","Ireland","Germany","France"],"a":0,"x":"The cabinet (parliamentary) system was borrowed from the United Kingdom.","e":"","src":["Stenographer 8 Aug 2021"]},{"id":"q9506","q":"Which of the following is NOT a feature of the Indian Constitution?","o":["Presidential form of government","Separation of powers","Parliamentary form of government","Fundamental rights"],"a":0,"x":"India has a parliamentary, not presidential, form of government.","e":"","src":["Assistant Superintendent 14 Jul 2024 S1"]},{"id":"q4462","q":"Which country’s constitution had been considered by India to adopt the terms “Liberty, Equality and Fraternity”?","o":["Constitution of Australia","Constitution of France","Constitution of South Africa","Constitution of Britain"],"a":1,"x":"The ideals of liberty, equality and fraternity in the Preamble were taken from the French Revolution and France's constitution.","e":"","src":["Office Superintendent 24 Oct 2021 S2"]},{"id":"q4463","q":"The words “Satyamev Jayate” are inscribed below the abacus are written in ______ Script.","o":["Devanagari","Sanskrit","Pali","Grantha"],"a":0,"x":"'Satyameva Jayate', from the Mundaka Upanishad, is inscribed below the abacus of the national emblem in Devanagari script.","e":"","src":["Office Superintendent 24 Oct 2021 S2"]},{"id":"q3851","q":"Which schedule of the Indian constitution deals with the states?","o":["First","Second","Third","Fourth"],"a":0,"x":"The First Schedule lists the states and union territories and their territories.","e":"","src":["Store Keeper 22 Apr 2021 S2"]},{"id":"q3886","q":"Who among the following was the chairman of \"Provincial Constitution Committee \" of the Constituent Assembly?","o":["Jawaharlal Nehru","B. R. Ambedkar","Sachchidananda Sinha","Sardar Vallabhbhai Patel"],"a":3,"x":"Sardar Vallabhbhai Patel chaired the Provincial Constitution Committee of the Constituent Assembly (as well as the Advisory Committee on Fundamental Rights and Minorities).","e":"Nehru: Union Constitution and Union Powers committees.","src":["Store Keeper 22 Apr 2021 S3"]},{"id":"q3888","q":"In which year did the Constituent Assembly adopt the song \"Jana Gana Mana\" as the national anthem of India?","o":["1949","1950","1952","1948"],"a":1,"x":"The Constituent Assembly adopted 'Jana Gana Mana' as the national anthem on 24 January 1950.","e":"The national song 'Vande Mataram' was also given equal honour that day.","src":["Store Keeper 22 Apr 2021 S3"]},{"id":"q2733","q":"The Constituent Assembly took almost ____________ to complete its historic task of drafting the Constitution for an Independent India.","o":["3 years","5 years","7 years","9 years"],"a":0,"x":"The Constituent Assembly took about 3 years (2 years, 11 months, 18 days) to draft the Constitution, from 9 December 1946 to 26 November 1949.","e":"","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2847","q":"Which among the following features of the Indian Constitution was not borrowed from United States of America Constitution?","o":["Fundamental Rights","Independence of Judiciary","Impeachment of President","Parliamentary Privileges & Bicameralism"],"a":3,"x":"Parliamentary privileges, bicameralism, the parliamentary system and the rule of law come from the British constitution. Fundamental Rights, judicial independence and impeachment of the President come from the US constitution.","e":"US: Fundamental Rights, judicial review, impeachment, Vice-President.","src":["Ahlmad 16 Oct 2021 S3"]},{"id":"q3275","q":"Which article of the Indian Constitution is related to amendments?","o":["123","356","368","375"],"a":2,"x":"Article 368 lays down Parliament's power and procedure to amend the Constitution.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S3"]},{"id":"q4028","q":"On 26 November, 1949, the constitution of India was _____________.","o":["adopted","written","reviewed","signed"],"a":0,"x":"The Constituent Assembly adopted the Constitution on 26 November 1949 (Constitution Day); it came into force on 26 January 1950.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4029","q":"Jawaharlal Nehru introduced the objective resolution in ____________.","o":["The legislative assembly","The constituent assembly","The Parliament","The legislative council"],"a":1,"x":"Jawaharlal Nehru moved the Objectives Resolution in the Constituent Assembly on 13 December 1946; it was adopted on 22 January 1947.","e":"It became the basis of the Preamble.","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4031","q":"The original Constitution of India was handwritten by ___________.","o":["Dr Sachchidananda Sinha","Bhimrao Ramji Ambedkar","Mohandas Karamchand Gandhi","Prem Behari Narain Raizada"],"a":3,"x":"The original Constitution was handwritten in flowing italic calligraphy by Prem Behari Narain Raizada.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4312","q":"The National Emblem of India was adopted on ______________.","o":["26 November, 1949","26th January, 1950","24 January, 1950","15 August, 1947"],"a":1,"x":"The national emblem, adapted from the Lion Capital of Sarnath, was adopted on 26 January 1950.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S2"]},{"id":"q4313","q":"The concept of the five year plans in The Indian Constitution was borrowed from which constitution?","o":["France","Japan","Union of Soviet Socialist Republics","United States of America"],"a":2,"x":"The idea of Five Year Plans was borrowed from the USSR.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S2"]},{"id":"q4357","q":"Which of the following states had the highest representation in the Constituent Assembly?","o":["United Provinces","Madras","Bombay","Bihar"],"a":0,"x":"The United Provinces (now Uttar Pradesh) had the largest representation in the Constituent Assembly.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q4360","q":"Who was the Chairman of the Committee on the Functions of the Constituent Assembly?","o":["J.B. Kriplani","A.V. Thakkar","Jawaharlal Nehru","G.V. Mavalankar"],"a":3,"x":"G.V. Mavalankar chaired the Committee on the Functions of the Constituent Assembly.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S3"]},{"id":"q4402","q":"Name the country with the longest constitution in the world.","o":["France","India","Japan","United States Of America"],"a":1,"x":"India has the longest written constitution of any country.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q4404","q":"In 1950, the constitution of India was published in the city of_____________.","o":["Mussoorie","Bombay","Dehradun","Delhi"],"a":2,"x":"The first copies of the Constitution were printed in 1950 in Dehradun, at the Survey of India.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q4405","q":"The first president (temporary Chairman of the Assembly) of the Constituent Assembly when it met on 9 December 1946 was___________.","o":["Dr Sachchidananda Sinha","Bhimrao Ramji Ambedkar","Mohandas Karamchand Gandhi","Prem Behari Narain Raizada"],"a":0,"x":"Dr Sachchidananda Sinha, the oldest member, was the temporary chairman at the first meeting on 9 December 1946; Rajendra Prasad was elected President on 11 December.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q4567","q":"Exactly how long did it take the Constituent Assembly to formulate the Constitution?","o":["3 years, 11 months, 20 days","3 years, 9 months, 20 days","2 years, 11 months, 18 days","2 years, 9 months, 18 days"],"a":2,"x":"The Constituent Assembly took 2 years, 11 months and 18 days to make the Constitution.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S1"]},{"id":"q4568","q":"Anti-defection laws are listed in which Schedule of the Indian Constitution?","o":["Fourth","Second","Twelfth","Tenth"],"a":3,"x":"The anti-defection law is in the Tenth Schedule, added by the 52nd Amendment (1985).","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S1"]},{"id":"q1220","q":"Which statement correctly reflects the constitutional mandate for laws enacted under Articles 2 and 3?","o":["Parliament must amend the First and Fourth Schedules through a separate constitutional amendment.","Laws under Article 3 can be introduced only by state legislatures with the President's prior approval.","They must contain the necessary amendments to the First and Fourth Schedules and may include supplemental and incidental provisions.","Such laws need ratification by at least half the states before affecting the Schedules."],"a":2,"x":"Article 4 says laws under Articles 2 and 3 (admitting or forming states) must amend the First and Fourth Schedules as needed and may add supplemental provisions. They are not treated as constitutional amendments under Article 368.","e":"They pass by simple majority in Parliament.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1234","q":"By which constitutional amendment was the Ninth Schedule added to the Indian Constitution?","o":["First Amendment, 1951","Forty-fourth Amendment, 1978","Forty-second Amendment, 1976","Seventh Amendment, 1956"],"a":0,"x":"The First Amendment (1951) added the Ninth Schedule to protect land-reform laws from court challenge on the ground of violating fundamental rights.","e":"After I.R. Coelho (2007), Ninth Schedule laws added after 24 April 1973 can be reviewed.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1456","q":"Which of the following was the first amendment to the Indian Constitution passed in 1951 by the Provisional Parliament?","o":["Right against Exploitation","Right to Freedom of religion","Cultural and Educational Rights","Right to Freedom of Speech and expression"],"a":3,"x":"The First Amendment (1951) added 'reasonable restrictions' to freedom of speech and expression (Article 19(2)), and also created the Ninth Schedule.","e":"It was passed by the Provisional Parliament under Nehru.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1466","q":"Which Article of the Indian Constitution says that the official language of the Union shall be Hindi in the Devanagari script?","o":["Article 343","Article 280","Article 324","Article 226"],"a":0,"x":"Article 343: the official language of the Union shall be Hindi in the Devanagari script.","e":"Article 280: Finance Commission. Article 324: Election Commission. Article 226: High Court writs.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1501","q":"Which of the following concepts was NOT present in the Preamble of the Indian Constitution before 1976?","o":["Sovereign","Socialist","Democratic","Justice"],"a":1,"x":"'Socialist' (with 'Secular' and 'Integrity') was added to the Preamble by the 42nd Amendment in 1976. 'Sovereign', 'Democratic' and 'Justice' were there from the start.","e":"The Preamble is based on Nehru's Objectives Resolution (1946).","src":["TGT 29 Aug 2025"]},{"id":"q1533","q":"How many Schedules did the original Indian Constitution have at its commencement?","o":["8","15","11","5"],"a":0,"x":"The original Constitution (1950) had 8 Schedules (and 395 Articles in 22 Parts); there are now 12.","e":"9th (1951), 10th (1985), 11th (1992), 12th (1992) were added later.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1887","q":"India, also known as Bharat, is a:","o":["Union of World","Union of peoples","Union of States","Union of country"],"a":2,"x":"Article 1: India, that is Bharat, shall be a Union of States.","e":"","src":["TGT 11 Sep 2021 S3"]},{"id":"q2358","q":"By which amendment the word ‘Secular’ was added to the preamble of the constitution of India?","o":["42nd","44th","86th","28th"],"a":0,"x":"The 42nd Amendment (1976) added 'Socialist', 'Secular' and 'Integrity' to the Preamble.","e":"","src":["TGT 14 Sep 2021 S2"]},{"id":"q3389","q":"By which of the following articles did the farmers of the Indian Constitution repeal prior acts passed by the British Parliament?","o":["Article 343","Article 356","Article 395","Article 51A"],"a":2,"x":"Article 395 repealed the Indian Independence Act, 1947 and the Government of India Act, 1935.","e":"","src":["TGT 18 Sep 2021 S3"]},{"id":"q5037","q":"_______ is known as the Father of the Indian Constitution.","o":["Sardar Vallabhbhai Patel","Shri Lal Bahadur Shstri","Dr Babasaheb Ambedkar","Shri Mohandas Gandhi"],"a":2,"x":"Dr B.R. Ambedkar, chairman of the Drafting Committee, is called the Father of the Indian Constitution.","e":"","src":["TGT 26 Sep 2021 S1"]},{"id":"q5784","q":"Which country's Constitution did not have an influence while drafting the Constitution of India?","o":["United Kingdom","United States of America","France","Italy"],"a":3,"x":"India borrowed features from the UK, USA and France (liberty, equality, fraternity), but not from Italy.","e":"","src":["TGT 5 Sep 2021 S1"]},{"id":"q6035","q":"In which of the following case, the Supreme Court state Preamble as key to the minds of the makers of the Constitution?","o":["Berubari Union Case 1960","I.C.Golaknath Case 1967","Minerva Mills Case 1980","Kesavananda Bharati Case 1973"],"a":0,"x":"In the Berubari Union case (1960) the Supreme Court called the Preamble a key to the minds of the Constitution's makers.","e":"","src":["TGT 8 Sep 2021 S2"]},{"id":"q7564","q":"Which of the following pair of schedule – contents of Indian constitution is correct? I. Third – Validation of certain acts and regulations II. Eleventh – Powers, authority and responsibilities of Panchayats","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"The Eleventh Schedule covers powers of panchayats; validation of Acts is in the Ninth Schedule, not the Third.","e":"","src":["TGT 7 Aug 2021"]},{"id":"q0792","q":"The Preamble declares India to be a Republic, which means that ____________.","o":["the head of the state is the Home Minister","the head of the state is the Chief Justice of India","the head of the state is the Prime Minister","the head of the state is the President"],"a":3,"x":"A Republic means the head of state is elected, not hereditary. In India the President, elected indirectly for five years, is the head of state.","e":"The UK is a democracy but not a republic, because its head of state is a hereditary monarch.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0809","q":"The 101st Constitutional Amendment Act is related to the introduction of:","o":["Panchayati Raj","Right to Education","Fundamental Rights","Goods and Services Tax (GST)"],"a":3,"x":"The 101st Amendment Act (2016) introduced the Goods and Services Tax, adding Articles 246A, 269A and 279A (GST Council).","e":"GST came into force on 1 July 2017.","src":["PGT 22 Sep 2025"]},{"id":"q0829","q":"Which Article of the Indian Constitution states that 'this Constitution may be called the Constitution of India'?","o":["Article 393","Article 441","Article 1","Article 1 B"],"a":0,"x":"Article 393 gives the short title: 'This Constitution may be called the Constitution of India.'","e":"Article 394A: Hindi translation. Article 395: repeal of the Indian Independence Act and GoI Act, 1935.","src":["PGT 26 Sep 2025"]},{"id":"q6579","q":"Which among the following statements is incorrect?","o":["Twelfth Schedule contains the powers, authority and responsibilities of Municipalities.","Ninth Schedule contains provisions as to validation of certain Acts and Regulations.","Seventh Schedule contains the Union list, State list and the concurrent list.","Fifth Schedule contains provisions as to the allocation of seats in the Council of States."],"a":3,"x":"The Fourth Schedule, not the Fifth, allocates seats in the Rajya Sabha; the Fifth deals with Scheduled Areas.","e":"","src":["PGT 3 Jul 2021 S1"]},{"id":"q7091","q":"Which of the following pair of schedule – contents of Indian constitution is correct? I. Third – Allocation of seats in council of states II. Eighth – Languages","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"The Eighth Schedule lists languages; Rajya Sabha seats are in the Fourth Schedule, not the Third (oaths).","e":"","src":["PGT 17 Jul 2021"]},{"id":"q8370","q":"Which of the following parts of the Indian Constitution is adopted from the Ireland Constitution?","o":["Directive Principles of State Policy","Fundamental Rights","Fundamental Duties","Union and Executive"],"a":0,"x":"The Directive Principles of State Policy were borrowed from the Irish Constitution.","e":"","src":["PGT 3 Nov 2022"]},{"id":"q9552","q":"The feature of 'Suspension of fundamental rights during emergency' in the Indian Constitution is borrowed from the Constitution of ___________.","o":["United States of America","Germany","France","Japan"],"a":1,"x":"Suspension of Fundamental Rights during an emergency was borrowed from Germany's Weimar Constitution.","e":"","src":["PGT 30 Jun 2021 S1"]},{"id":"q9553","q":"Part X of the Constitution of India consists of Articles on the _________________.","o":["Scheduled and Tribal Areas","Fundamental Duties","Citizenship","Elections"],"a":0,"x":"Part X of the Constitution covers the Scheduled and Tribal Areas.","e":"","src":["PGT 30 Jun 2021 S1"]},{"id":"q9574","q":"The feature of 'Impeachment of President' in the Indian Constitution is borrowed from the Constitution of ___________.","o":["Germany","Japan","United States of America","Australia"],"a":2,"x":"Impeachment of the President was borrowed from the US Constitution.","e":"","src":["PGT 28 Jun 2021 S1"]},{"id":"q9601","q":"Which of the following individuals was appointed as the Constitutional Adviser to the Constituent Assembly of India in 1946?","o":["BR Ambedkar","BN Rau","Mahatma Gandhi","Jawarharlal Nehru"],"a":1,"x":"Sir B.N. Rau was the Constitutional Adviser to the Constituent Assembly.","e":"","src":["PGT 28 Jun 2021"]},{"id":"q9602","q":"How many languages were initially included in the Eighth Schedule of the Indian Constitution?","o":["22","14","16","18"],"a":1,"x":"The Eighth Schedule originally listed 14 languages; it now has 22.","e":"","src":["PGT 28 Jun 2021"]},{"id":"q9603","q":"According to Article 343(1) of the Indian Constitution, what language is the official language of the Union?","o":["Hindi","English","Hindi in Devnagari Script","Sanskrit"],"a":2,"x":"Article 343(1): the official language of the Union is Hindi in Devanagari script.","e":"","src":["PGT 28 Jun 2021"]},{"id":"q9631","q":"Who served as the first ever Chairman of the Constituent Assembly before the appointment of Dr. Rajendra Prasad?","o":["Dr Sachidanand Sinha","Dr BR Ambedkar","Pt. Jawaharlal Nehru","Dr AK Ayyar"],"a":0,"x":"Dr Sachchidananda Sinha was the Constituent Assembly's temporary chairman before Rajendra Prasad was elected.","e":"","src":["PGT 29 Jun 2021"]},{"id":"q9657","q":"The words \"socialist and secular\" were added to the preamble through which amendment act?","o":["44th Amendment Act, 1978","42nd Amendment Act, 1976","86th Amendment Act, 2002","69th Amendment Act, 1991"],"a":1,"x":"'Socialist' and 'secular' were added to the Preamble by the 42nd Amendment (1976).","e":"","src":["PGT 29 Jun 2021"]},{"id":"q1643","q":"Which of the following pair of Part –Constituents of Indian Constitution is CORRECT? I. Part X – The Scheduled and Tribal areas. II. Part XI – Relations between the union and the states.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Part X covers the Scheduled and Tribal Areas and Part XI covers Union–State relations.","e":"","src":["Senior Scientific Assistant (Lie-Detection) 10 Oct 2021 S1"]},{"id":"q1684","q":"The concept of Concurrent List in the Indian Constitution was borrowed from the constitution of ___________.","o":["United Kingdom","France","Canada","Australia"],"a":3,"x":"The Concurrent List was borrowed from the Australian Constitution.","e":"","src":["Technical Assistant (Computer) 10 Sep 2021 S1"]},{"id":"q2240","q":"The Indian Constitution was adopted by the Constituent Assembly on ____________.","o":["26 November, 1949","24 November, 1948","25 November, 1949","26 January, 1950"],"a":0,"x":"The Constituent Assembly adopted the Constitution on 26 November 1949.","e":"","src":["Laboratory Assistant (Lie Detection) 13 Sep 2021 S1"]},{"id":"q2579","q":"Part IX B of the Indian Constitution deals with ________.","o":["Union","Panchayats","Cooperative Societies","Tribunals"],"a":2,"x":"Part IX-B (added by the 97th Amendment, 2011) deals with co-operative societies.","e":"","src":["Technical Assistant (Medical Electronics) 16 Nov 2021 S2"]},{"id":"q2955","q":"By which Constitutional Amendment Act was the 10th Schedule added to the Constitution of India?","o":["61st Constitutional Amendment Act","52nd Constitutional Amendment Act","85th Constitutional Amendment Act","24th Constitutional Amendment Act"],"a":1,"x":"The 52nd Amendment (1985) added the Tenth Schedule (anti-defection law).","e":"","src":["Technical Assistant (Intrumentation & Control) 17 Nov 2021 S3"]},{"id":"q3089","q":"The Government run by the Priests in the name of God is termed as","o":["Autocracy","Democracy","Theocracy","Plutocracy"],"a":2,"x":"Government by priests in the name of God is a theocracy.","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q3344","q":"Which of the following statement is CORRECT? I. On December 11, 1946, the constituent assembly elected Dr. Rajendra Prasad as its permanent chairman. II. Provision of directive principles of state policy in Indian constitution were borrowed from the constitution of Russia.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Rajendra Prasad was elected permanent chairman on 11 December 1946, but the Directive Principles came from Ireland, not Russia.","e":"","src":["Senior Scientific Assistant (Biology) 18 Sep 2021 S2"]},{"id":"q3992","q":"At the time of Indian Constitution adoption, the Constitution contained how many Aricles and Schedules?","o":["495 Articles and 10 Schedules","395 Articles and 8 Schedules","399 Articles and 9 Schedules","425 Articles and 11 Schedules"],"a":1,"x":"When adopted, the Constitution had 395 Articles and 8 Schedules.","e":"","src":["Technical Assistant (Printing) 22 Nov 2021 S3"]},{"id":"q4127","q":"21st Constitutional Amendment included Sindhi as ______ language in the Eighth Schedule.","o":["12th","15th","16th","19th"],"a":1,"x":"The 21st Amendment (1967) added Sindhi as the 15th language in the Eighth Schedule.","e":"","src":["Veterinary and Livestock Inspector 23 Apr 2021 S3"]},{"id":"q4135","q":"When did the drafting committee headed by Dr. B.R.Ambedkar submitted a draft constitution of India to the President of the assembly?","o":["21st Jan, 1948","27th June, 1949","21st Feb, 1948","28th Nov, 1948"],"a":2,"x":"The Drafting Committee submitted the draft Constitution on 21 February 1948.","e":"","src":["Manager (Public Relations) 23 Oct 2021 S2"]},{"id":"q4661","q":"Indian Constitution is the longest written Constitution in the world originally containing -","o":["395 Articles, 25 Parts and 10 Schedules","395 Articles, 20 Parts and 12 Schedules","395 Articles, 22 Parts and 08 Schedules","395 Articles, 22 Parts and 11 Schedules"],"a":2,"x":"The original Constitution had 395 Articles in 22 Parts and 8 Schedules.","e":"","src":["Librarian 25 Nov 2021 S3"]},{"id":"q4732","q":"The total numbers of members in the Constituent Assembly after partition of India in 1947 was __________.","o":["300","299","250","489"],"a":1,"x":"After Partition the Constituent Assembly's strength fell to 299.","e":"","src":["Laboratory Assistant (HRD Quality Control) 25 Sep 2021 S1"]},{"id":"q4914","q":"The language, that is NOT included in the 8th Schedule of the Constitution of India is:","o":["Oriya","Nepali","Kannada","Bhojpuri"],"a":3,"x":"Bhojpuri is not in the Eighth Schedule; Odia, Nepali and Kannada are.","e":"","src":["Assistant Bacteriologist 26 Nov 2021 S2"]},{"id":"q5327","q":"In which form of government, power is exercised by a group of men?","o":["Oligarchy","Kingship","Commandership","Zamindari"],"a":0,"x":"Rule by a small group is an oligarchy.","e":"","src":["Laboratory Assistant (Biology) 28 Aug 2021"]},{"id":"q5331","q":"Through which Constitutional Amendment of India did Privy Purse get abolished?","o":["25th Amendment","23rd Amendment","26th Amendment","21st Amendment"],"a":2,"x":"The 26th Amendment (1971) abolished privy purses.","e":"","src":["Laboratory Assistant (Biology) 28 Aug 2021"]},{"id":"q5356","q":"The term 'Republic' means:","o":["Head of state is elected","Head of state is monarch","Oligarchy","Ruler"],"a":0,"x":"In a republic the head of state is elected, not hereditary.","e":"","src":["Laboratory Assistant (Physics) 28 Aug 2021"]},{"id":"q5464","q":"Rajendra Prasad was NOT the Chairman of the _____ of the Constituent Assembly of India.","o":["Committee on the Rules of Procedure","Steering Committee","States Committee","Finance and Staff Committee"],"a":2,"x":"Rajendra Prasad did not chair the States Committee; Nehru did.","e":"","src":["Assistant Chemist 29 Nov 2021 S3"]},{"id":"q5807","q":"The feature of 'Prerogative Writs' in the Indian Constitution is borrowed from the Constitution of __________.","o":["United Kingdom","United States of America","France","South Africa"],"a":0,"x":"Prerogative writs were borrowed from the United Kingdom.","e":"","src":["Technical Assistant (Electrical) 5 Sep 2021 S2"]},{"id":"q5933","q":"The drafting committee of Indian Constitution was headed by:","o":["Dr Rajendra Prasad","Dr. B. R. Ambedkar","C. Rajagopalachari","Sachchidananda Sinha"],"a":1,"x":"B.R. Ambedkar chaired the Drafting Committee of the Constitution.","e":"","src":["Laboratory Assistant (Chemistry) 7 Sep 2021 S1"]},{"id":"q6066","q":"Which among the following Constitutional Amendments made it compulsory for the president to give his assent to a Constitutional Amendment Bill?","o":["24th","27th","32nd","18th"],"a":0,"x":"The 24th Amendment (1971) made it compulsory for the President to assent to Constitutional Amendment Bills.","e":"","src":["Technical Assistant (Mechanical) 8 Sep 2021 S3"]},{"id":"q6544","q":"Part __________ of the Indian Constitution deals with Temporary, Transitional and Special Provisions.","o":["XX","XXI","XIX","XVII"],"a":1,"x":"Part XXI covers Temporary, Transitional and Special Provisions.","e":"","src":["Technical Assistant (Garments Fabrication Technology) 2 Aug 2021"]},{"id":"q6545","q":"Which among the following Constitutional Amendments made it obligatory for seekers of public office to swear their allegiance to the Indian Republic and prescribe the various obligatory templates?","o":["27th","21st","16th","12th"],"a":2,"x":"The 16th Amendment (1963) added allegiance to India's sovereignty and integrity to the oaths for public office.","e":"","src":["Technical Assistant (Garments Fabrication Technology) 2 Aug 2021"]},{"id":"q6724","q":"Which schedule of Indian constitution is related to allocation of seats in the council of states?","o":["Third","Fourth","Fifth","Ninth"],"a":1,"x":"The Fourth Schedule allocates Rajya Sabha seats to states and UTs.","e":"","src":["Investigator 26 Jul 2021"]},{"id":"q8581","q":"The 42nd Constitutional Amendment was made in the light of the recommendations of the Swaran Singh Committee Report that was set up by which government?","o":["Charan Singh Government","Indira Gandhi Government","Morarji Desai Government","Lal Bahadur Shastri Government"],"a":1,"x":"The Swaran Singh Committee, whose report led to the 42nd Amendment, was set up by Indira Gandhi's government.","e":"","src":["Shift Incharge 25 Jun 2023 S2"]},{"id":"q9690","q":"Which of the following features in the Indian Constitution was borrowed from the Constitution of France?","o":["Method of election of President","Judicial review","Fundamental duties","Concept of Republic"],"a":3,"x":"The ideals of a republic (and liberty, equality, fraternity) were borrowed from France.","e":"","src":["Junior Engineer 29 Jun 2022 S1"]}]},{"id":"rights","n":"Citizenship, Rights, DPSP and Duties","qs":[{"id":"q0034","q":"Which of the following is NOT included in the Right to Equality in the Indian Constitution?","o":["Abolition of untouchability","Equality of opportunity","Absolute equality","Equality before law"],"a":2,"x":"Articles 14–18 give equality before law, no discrimination, equal opportunity in public jobs, abolition of untouchability and abolition of titles. Equality is not absolute: reasonable classification is allowed.","e":"Reservation under Article 16(4) is possible precisely because equality is not absolute.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0101","q":"Which Article of the Indian Constitution guarantees the Right to Equality Before Law and Equal Protection of Laws?","o":["Article 14","Article 16","Article 15","Article 17"],"a":0,"x":"Article 14: the State shall not deny any person equality before the law or equal protection of the laws within India.","e":"Equality before law comes from British law; equal protection of laws comes from the US Constitution.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0114","q":"Which of the following is NOT a mode of acquiring Indian citizenship?","o":["Investment","Registration","Birth","Descent"],"a":0,"x":"The Citizenship Act, 1955 allows citizenship by birth, descent, registration, naturalisation and incorporation of territory. Investment is not a route.","e":"It can be lost by renunciation, termination or deprivation.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0142","q":"Which of the following Articles of the Constitution of India has provisions regarding citizenship?","o":["Articles 5-11","Articles 1-4","Articles 12-17","Articles 18-21"],"a":0,"x":"Citizenship is in Articles 5–11, Part II of the Constitution; Parliament used Article 11 to pass the Citizenship Act, 1955.","e":"Article 5: citizenship at the commencement of the Constitution.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0155","q":"Which Part of the Indian Constitution has provisions on citizenship?","o":["Part III","Part IV","Part II","Part V"],"a":2,"x":"Part II of the Constitution (Articles 5–11) deals with citizenship.","e":"Part III = Fundamental Rights; Part IV = Directive Principles; Part IVA = Fundamental Duties.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0195","q":"Under the Citizenship Act, 1955, which government authority is referred to as 'a Government in India'?","o":["Only a State Government","Central Government or a State Government","Only the Central Government","Local government"],"a":1,"x":"In the Citizenship Act, 1955, 'a Government in India' means the Central Government or a State Government.","e":"Section 2 of the Act holds the definitions.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0222","q":"Which Article of the Indian Constitution abolishes 'Untouchability'?","o":["Article 17","Article 15","Article 14","Article 16"],"a":0,"x":"Article 17 abolishes untouchability and forbids its practice in any form.","e":"14 equality, 15 no discrimination, 16 jobs, 17 untouchability, 18 titles.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0229","q":"Which of the following statements is correct regarding Overseas Citizenship of India (OCI)?","o":["OCI status can be granted to PIOs from countries that permit dual citizenship under their laws.","The Constitution of India allows dual citizenship through OCI status.","Persons of Indian Origin (PIOs) from Pakistan and Bangladesh are eligible for OCI.","The OCI scheme was introduced by the Government of India in 1986."],"a":0,"x":"OCI status can be given to persons of Indian origin whose country allows dual citizenship in some form. It is not full dual citizenship; it started in 2005, not 1986; and people from Pakistan and Bangladesh are excluded.","e":"OCI card holders get a lifelong multiple-entry visa but cannot vote.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0234","q":"Which Section of the Citizenship Act, 1955, defines the term 'illegal migrant'?","o":["Section 2(1)(b)","Section 2(b)(ii)","Section 2(a)","Section 2(1)(d)"],"a":0,"x":"Section 2(1)(b) of the Citizenship Act, 1955 defines an 'illegal migrant': a foreigner who entered without valid documents, or stayed beyond the permitted time.","e":"The Citizenship (Amendment) Act, 2019 added a proviso to this clause for certain minorities from Afghanistan, Bangladesh and Pakistan.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0304","q":"The Right to Education (RTE) Act in India ensures free and compulsory education for children up to which age?","o":["12 years","18 years","14 years","16 years"],"a":2,"x":"The Right to Education Act, 2009 gives free and compulsory education to children aged 6 to 14, under Article 21A (added by the 86th Amendment, 2002).","e":"It reserves 25% of seats in private unaided schools for disadvantaged children.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0318","q":"The Citizenship Act of 1955 provides how many total ways of acquiring citizenship?","o":["5","6","4","3"],"a":0,"x":"The Citizenship Act, 1955 gives five ways to acquire citizenship: birth, descent, registration, naturalisation and incorporation of territory.","e":"It gives three ways to lose it: renunciation, termination and deprivation.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0346","q":"The right to freedom of speech and expression has been set out in which Article of the Indian Constitution?","o":["Article 20","Article 21","Article 22","Article 19"],"a":3,"x":"Article 19(1)(a) guarantees freedom of speech and expression; Article 19 lists six freedoms in all.","e":"Freedom of the press is read into Article 19(1)(a).","src":["ASO 21 Aug 2025 S2"]},{"id":"q0425","q":"As of 1 January 2024, how many Fundamental Duties are included for citizens in the Indian Constitution?","o":["11","9","7","10"],"a":0,"x":"Article 51A lists 11 Fundamental Duties: 10 were added by the 42nd Amendment (1976) and the 11th (education for children aged 6–14) by the 86th Amendment (2002).","e":"Borrowed from the USSR constitution.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0429","q":"Articles 12 to 35, dealing with Fundamental Rights, are contained in which Part of the Indian Constitution?","o":["Part III","Part II","Part IV","Part I"],"a":0,"x":"Fundamental Rights are in Part III (Articles 12–35), called the 'Magna Carta' of India.","e":"Part IV: Directive Principles (36–51). Part IVA: Fundamental Duties (51A).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0469","q":"Which Article contained in Part IV A of the Indian Constitution deals with Fundamental Duties?","o":["Article 51 'A'","Article 71 ‘A’","Article 61","Article 41"],"a":0,"x":"Article 51A in Part IVA lists the Fundamental Duties, added by the 42nd Amendment (1976) on the Swaran Singh Committee's advice.","e":"There are now 11 duties; the 11th (education for children 6–14) came with the 86th Amendment (2002).","src":["ASO 27 Aug 2025 S1"]},{"id":"q0474","q":"Under the leadership of which Indian Prime Minister were the Fundamental Duties added in the Constitution of India?","o":["Lal Bahadur Shastri","Indira Gandhi","Jawaharlal Nehru","Rajiv Gandhi"],"a":1,"x":"The Fundamental Duties were added by the 42nd Amendment (1976), when Indira Gandhi was Prime Minister, during the Emergency.","e":"The idea was borrowed from the Constitution of the USSR.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1569","q":"Which Article of the Indian Constitution relates to equality before law?","o":["Article 30","Article 12","Article 34","Article 14"],"a":3,"x":"Article 14 guarantees equality before law and equal protection of the laws.","e":"It applies to citizens and non-citizens alike.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1582","q":"Which Article of the Indian Constitution dealt with the citizenship at the commencement of the Constitution?","o":["Article 6","Article 5","Article 4","Article 3"],"a":1,"x":"Article 5 dealt with citizenship at the commencement of the Constitution (26 January 1950), based on domicile together with birth or residence.","e":"Articles 5–11 form Part II.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1595","q":"In which year were the recommendations of the Mandal Commission implemented after the court's verdict?","o":["1991","1992","1990","1993"],"a":1,"x":"The Supreme Court upheld 27% OBC reservation from the Mandal Commission report in Indra Sawhney (November 1992); the key takes 1992 as the year it came into effect after the verdict.","e":"The same verdict set the 50% ceiling and excluded the 'creamy layer'.","src":["Patwari 17 Sep 2022 S2"],"k":"The V. P. Singh government's order came in 1990 and the post-verdict order in September 1993; DSSSB's key marks 1992, the verdict year."},{"id":"q1598","q":"Which Article of the Indian Constitution gives minorities the right to establish educational institutions?","o":["Article 32","Article 30","Article 15","Article 29"],"a":1,"x":"Article 30 gives religious and linguistic minorities the right to establish and run educational institutions of their choice.","e":"Article 29 protects any section of citizens' distinct language, script or culture.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q1604","q":"Which Article of the Constitution guarantees equality of opportunity for all citizens in matters relating to employment or appointment to any office under the State?","o":["Article 21","Article 17","Article 16","Article 15"],"a":2,"x":"Article 16 guarantees equality of opportunity in public employment; 16(4) allows reservation for backward classes.","e":"Article 15 bans discrimination in general.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q1624","q":"Article 51 'A', of Indian constitution contained in ______ of the Constitution deals with Fundamental Duties.","o":["Part IV A","Part III A","Part II A","Part V A"],"a":0,"x":"Article 51A, which lists the Fundamental Duties, is in Part IVA of the Constitution.","e":"Part IVA has only this one Article.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0513","q":"Article 23 and 24 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":2,"x":"Articles 23 and 24 make up the Right against Exploitation: Article 23 bans human trafficking and forced labour (begar), and Article 24 bans child labour under 14 in factories, mines and hazardous work.","e":"Articles 25–28: freedom of religion.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0635","q":"According to which of the following Articles, the state shall not deny to any person equality before the law or the equal protection of the laws within the territory of India?","o":["24","14","32","20"],"a":1,"x":"Article 14: the State shall not deny to any person equality before the law or equal protection of the laws within India.","e":"It applies to 'any person', citizen or foreigner.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0674","q":"Article 19 to 22 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":0,"x":"Articles 19–22 form the Right to Freedom: six freedoms (19), protection in conviction (20), life and personal liberty (21), right to education (21A), and protection against arbitrary arrest (22).","e":"Article 21 has been read to include the right to privacy (2017).","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0712","q":"Article 29 and 30 of the Indian Constitution deals with the ____________.","o":["Right to Freedom","Right to Equality","Right Against Exploitation","Cultural and Educational Rights"],"a":3,"x":"Articles 29 and 30 are the Cultural and Educational Rights: protecting minorities' language, script and culture, and their right to set up educational institutions.","e":"Article 32 (constitutional remedies) was called the 'heart and soul' of the Constitution by Dr Ambedkar.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q1770","q":"Article 16 of the Indian constitution deals with _____________.","o":["Abolition of Untouchability","Equality before law","Equality of opportunity in matters of public employment","Abolition of titles"],"a":2,"x":"Article 16 guarantees equality of opportunity in public employment. Article 14 is equality before law, 17 abolishes untouchability, 18 abolishes titles.","e":"14 law, 15 discrimination, 16 jobs, 17 untouchability, 18 titles.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q2173","q":"In which year was the Swaran Singh Committee set up by the Indian Government?","o":["1973","1970","1979","1976"],"a":3,"x":"The Swaran Singh Committee was set up in 1976; on its recommendation the 42nd Amendment added Fundamental Duties (Article 51A).","e":"It suggested 8 duties; 10 were added.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2462","q":"Which of the following amendments of the Indian Constitution had inserted the Article 21A to provide free and compulsory education of all children?","o":["Seventy-sixth","Eightieth","Eighty-second","Eighty-sixth"],"a":3,"x":"The 86th Amendment (2002) inserted Article 21A, making free and compulsory education a fundamental right for children aged 6–14.","e":"It also added the 11th Fundamental Duty (Article 51A(k)).","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2466","q":"The Fundamental Duties of the Indian Constitution was inspired from which of the following country's constitution?","o":["USA","Canada","USSR","France"],"a":2,"x":"The idea of Fundamental Duties was borrowed from the constitution of the former USSR.","e":"Also from the USSR: the ideals of justice (social, economic, political) in the Preamble.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2505","q":"Which of the following articles of the Indian Constitution is related to the right against exploitation?","o":["Articles 18 and 19","Articles 20 and 21","Articles 22 and 23","Articles 23 and 24"],"a":3,"x":"The Right against Exploitation is in Articles 23 (ban on trafficking and forced labour) and 24 (ban on child labour in factories and mines).","e":"Articles 23–24: right against exploitation.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q3482","q":"Which article of the Indian constitution deals with Right to Education?","o":["21","24","21 A","28"],"a":2,"x":"Article 21A (86th Amendment, 2002) makes free and compulsory education a fundamental right for children aged 6–14.","e":"","src":["Junior Clerk 9 Nov 2021 S2","Store Keeper 19 Apr 2021 S3"]},{"id":"q6128","q":"Which article of the Indian constitution deals with ‘Abolition of Untouchability’?","o":["14","16","17","19"],"a":2,"x":"Article 17 abolishes untouchability.","e":"","src":["Junior Clerk 9 Nov 2021 S1"]},{"id":"q6169","q":"Part III of the Indian constitution deals with __________________ .","o":["Fundamental rights","Directive principles and state policy","Fundamental duties","The Union"],"a":0,"x":"Part III (Articles 12–35) deals with Fundamental Rights.","e":"Part IV: DPSP; Part IVA: Fundamental Duties.","src":["Junior Clerk 9 Nov 2021 S2"]},{"id":"q4895","q":"The Right to Property ceased to be a ‘fundamental right’ in India in the year ______.","o":["1973","1978","1982","1995"],"a":1,"x":"The 44th Amendment (1978) removed the right to property from Fundamental Rights; it is now a legal right under Article 300A.","e":"","src":["Stenographer 26 Nov 2021 S1"]},{"id":"q5023","q":"Which of the following Articles of the Constitution of India is related to the abolition of the title?","o":["Article 14","Article 15","Article 17","Article 18"],"a":3,"x":"Article 18 abolishes titles; Article 17 abolishes untouchability.","e":"","src":["Stenographer 26 Nov 2021 S2"]},{"id":"q4971","q":"Article 20 of the Constitution of India deals with the:","o":["abolition of titles","protection in respect of conviction for offences","continuance of the rights of citizenship","promotion of co-operative societies"],"a":1,"x":"Article 20 gives protection in respect of conviction for offences: no ex post facto punishment, no double jeopardy, no self-incrimination.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q4972","q":"Which of the following is correctly matched?","o":["Article 19(e) – Right to form associations","Article 19(b) – Right to practice any profession","Article 19(a) – Right to freedom of speech and expression","Article 19(g) – Right to assemble peaceably and without arms"],"a":2,"x":"Article 19(1)(a) guarantees freedom of speech and expression; (b) assembly, (c) associations, (g) profession.","e":"","src":["Personal Assistant 26 Nov 2021 S3"]},{"id":"q5186","q":"The 86th Constitutional Amendment Act added a new fundamental duty to the Constitution of India, according to which it shall be the duty of every citizen in India to provide opportunities for education to his child or ward between the age of:","o":["5 to 10 years","5 to 15 years","6 to 18 years","6 to 14 years"],"a":3,"x":"The 86th Amendment (2002) added duty 51A(k): parents or guardians must provide opportunities for education to children aged 6–14.","e":"","src":["Personal Assistant 27 Nov 2021 S1"]},{"id":"q5447","q":"Which committee recommended the inclusion of a separate chapter on fundamental duties in the Constitution?","o":["Swaran Singh Committee","Harendra Coomar Mookerjee Committee","B. N. Rau Committee","J. B. Kripalani Committee"],"a":0,"x":"The Swaran Singh Committee (1976) recommended adding Fundamental Duties; the 42nd Amendment did so.","e":"","src":["Personal Assistant 29 Nov 2021 S2"]},{"id":"q10137","q":"According to the Constitution of India, who among the following is the protector of the fundamental rights of the citizen?","o":["President","Supreme court","Chief justice of India","Parliament"],"a":1,"x":"The Supreme Court is the protector (guardian) of Fundamental Rights.","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q10141","q":"Which of the following fundamental rights does NOT come under the “Right to Freedom of Religion” provided by the Indian Constitution?","o":["Right of minorities to establish educational institutions","Freedom to manage religious affairs","Freedom of conscience and free profession, practice and propagation of religion","Freedom to pay taxes for promotion of any particular religion"],"a":0,"x":"The right of minorities to set up educational institutions is under Cultural and Educational Rights (Article 30), not Freedom of Religion (Articles 25–28).","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q10152","q":"Which of the following is Cultural and Educational Rights provided by Indian constitution?","o":["Equality of opportunity in public employment","Abolition of titles","Protection of language, culture of minorities","Freedom of speech and expression"],"a":2,"x":"Protection of the language, script and culture of minorities (Article 29) is a Cultural and Educational Right.","e":"","src":["Assistant Superintendent 20 Jul 2024 S3"]},{"id":"q8892","q":"In which Article of Part III of the Indian Constitution is the Right to Constitutional Remedies mentioned?","o":["Articles 30","Articles 31","Article 33","Articles 32"],"a":3,"x":"Article 32 gives the Right to Constitutional Remedies; Ambedkar called it the 'heart and soul' of the Constitution.","e":"","src":["MTS 2 Mar 2026 S3"]},{"id":"q8960","q":"As of November 2025, how many Fundamental Rights are guaranteed by the Indian Constitution?","o":["Five","Eight","Six","Seven"],"a":2,"x":"The Constitution now guarantees six Fundamental Rights; the right to property was removed in 1978.","e":"","src":["MTS 3 Mar 2026 S2"]},{"id":"q8997","q":"Which Fundamental Right protects citizens against exploitation in India?","o":["Article 25","Article 19","Articles 23 and 24","Article 21"],"a":2,"x":"Articles 23 and 24 give the Right against Exploitation (no forced labour, no child labour in hazardous work).","e":"","src":["MTS 3 Mar 2026 S3"]},{"id":"q9089","q":"'Prohibition of discrimination on grounds of religion, race, caste, sex or place of birth' is placed under which of the following articles of the Indian Constitution?","o":["Article 13","Article 12","Article 15","Article 14"],"a":2,"x":"Article 15 prohibits discrimination on grounds of religion, race, caste, sex or place of birth.","e":"","src":["MTS 6 Mar 2026 S1"]},{"id":"q9115","q":"The Constitution of India enshrines the 'Right to Equality' in which of the following Articles? 1. Article 13 2. Article 14 3. Article 15 4. Article 16","o":["2 and 3 only","1 and 2 only","1, 2 and 3 only","2, 3 and 4 only"],"a":3,"x":"The Right to Equality covers Articles 14 to 18; Article 13 deals with laws inconsistent with Fundamental Rights.","e":"","src":["MTS 6 Mar 2026 S2"]},{"id":"q9151","q":"Freedom of religion is guaranteed under which Articles of the Constitution of India?","o":["Articles 19-22","Articles 29-30","Articles 25-28","Articles 12-15"],"a":2,"x":"Articles 25 to 28 guarantee freedom of religion.","e":"","src":["MTS 6 Mar 2026 S3"]},{"id":"q9340","q":"Which Fundamental Right is available only to Indian citizens and not to foreigners?","o":["Right to Freedom of Speech and Expression","Right to Life and Personal Liberty","Right to Equality before law","Right against Exploitation"],"a":0,"x":"The Article 19 freedoms, including speech and expression, are available only to citizens.","e":"","src":["MTS 25 Feb 2026 S1"]},{"id":"q9351","q":"Which of the following Articles of the Indian Constitution encourages citizens to preserve the rich heritage of our composite culture?","o":["Article 15A","Article 15","Article 51A","Article 21A"],"a":2,"x":"Article 51A (Fundamental Duties) asks citizens to value and preserve the rich heritage of our composite culture.","e":"","src":["MTS 25 Feb 2026 S1"]},{"id":"q3481","q":"Through which constitutional amendment part IV A was inserted in the Indian constitution?","o":["Forty second","Tenth","First","Twenty seventh"],"a":0,"x":"Part IVA (Fundamental Duties, Article 51A) was inserted by the 42nd Amendment (1976).","e":"","src":["Store Keeper 19 Apr 2021 S3"]},{"id":"q2778","q":"Which among the following rights was deleted from the list of fundamental rights by the 44th Constitutional Amendment?","o":["Right to Equality","Right to Property","Right to Freedom","Right against Exploitation"],"a":1,"x":"The 44th Amendment (1978) removed the Right to Property from Fundamental Rights; it is now a legal right under Article 300A.","e":"","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2848","q":"A list of ten fundamental duties was included in the Indian Constitution by the _________ Amendment.","o":["40th","42nd","44th","52nd"],"a":1,"x":"The 42nd Amendment (1976) added ten Fundamental Duties (Article 51A); the 86th Amendment (2002) added the eleventh.","e":"","src":["Ahlmad 16 Oct 2021 S3"]},{"id":"q4090","q":"Which among the following constitutional amendments curtailed the fundamental right to property?","o":["26th","22nd","24th","25th"],"a":3,"x":"The 25th Amendment (1971) curtailed the right to property, letting the state pay an 'amount' instead of full compensation; the 44th Amendment (1978) removed it from Fundamental Rights.","e":"","src":["Jr. Telephone Operator 23 Apr 2021 S2"]},{"id":"q0943","q":"Match the following Directive Principles of State Policy (DPSP) with their Articles. A. Right to work, to education and to public assistance in certain cases — i. Article 48; B. Organisation of agriculture and animal husbandry — ii. Article 41; C. Living wage etc. for workers — iii. Article 43; D. Promotion of international peace and security — iv. Article 51","o":["A-i, B-ii, C-iii, D-iv","A-iii, B-i, C-ii, D-iv","A-i, B-iii, C-ii, D-iv","A-ii, B-i, C-iii, D-iv"],"a":3,"x":"Article 41: right to work, education and public assistance in certain cases; Article 48: organisation of agriculture and animal husbandry; Article 43: living wage for workers; Article 51: promotion of international peace and security.","e":"41 work, 43 living wage, 48 agriculture and cows, 51 world peace.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0944","q":"Match the Directive Principles with their Articles: A. Right to work, to education and to public assistance in certain cases; B. Organisation of agriculture and animal husbandry; C. Living wage etc. for workers; D. Promotion of international peace and security — i. Article 48, ii. Article 41, iii. Article 43, iv. Article 51.","o":["A-i, B-ii, C-iii, D-iv","A-iii, B-i, C-ii, D-iv","A-i, B-iii, C-ii, D-iv","A-ii, B-i, C-iii, D-iv"],"a":3,"x":"Right to work, education and public assistance – Article 41; organising agriculture and animal husbandry – Article 48; living wage for workers – Article 43; international peace and security – Article 51.","e":"DPSPs are in Part IV, Articles 36–51.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0957","q":"Which of the following is NOT one of the categories under which the Directive Principles of State Policy have been classified?","o":["Cultural heritage principles","Principles and policies related to international peace and security","Gandhian principles","Economic and social principles"],"a":0,"x":"Directive Principles are usually grouped as socialistic (economic and social), Gandhian and liberal-intellectual (including international peace and security). 'Cultural heritage principles' is not such a category.","e":"Gandhian principles: village panchayats, cottage industries, prohibition, cow protection.","src":["PRT 18 Feb 2026 S2"]},{"id":"q1036","q":"Which of the following is constitutionally prohibited under the Right against Exploitation?","o":["Contract workers in offices","Bonded labour in brick kilns","Employing adults at construction sites","Children working on family farms"],"a":1,"x":"Article 23 bans human trafficking, begar and other forced labour; bonded labour at brick kilns is exactly what it forbids. The Bonded Labour System (Abolition) Act, 1976 enforces it.","e":"Article 24 bans children under 14 in factories, mines and hazardous work.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1141","q":"What is the primary constitutional protection given by Article 31B regarding the Ninth Schedule?","o":["It allows the temporary suspension of Fundamental Rights during emergency provisions.","It safeguards Acts in the 9th Schedule from being declared void for violating Fundamental Rights.","It bars judicial review of all future amendments made to Part III of the Constitution.","It empowers High Courts to validate laws repugnant to the Directive Principles."],"a":1,"x":"Article 31B (added by the 1st Amendment, 1951) protects Acts placed in the Ninth Schedule from being struck down for violating Fundamental Rights.","e":"In I. R. Coelho (2007) the Supreme Court ruled such laws added after 24 April 1973 can still be tested against the basic structure.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1150","q":"Which statement correctly reflects the constitutional status and function of the Directive Principles of State Policy?","o":["They represent the fundamental obligations of citizens in a democratic polity and are enforceable in courts.","They are non-justiciable but act as essential guidelines for the state in ensuring socio- economic justice.","They are judicially enforceable, similar to Fundamental Rights, and override conflicting laws.","They are temporary provisions adopted by Parliament to be repealed after the implementation of the first Five-Year Plan"],"a":1,"x":"Directive Principles are non-justiciable (Article 37): courts cannot enforce them, but they are fundamental in governance and guide the state towards social and economic justice.","e":"Dr Ambedkar called them 'novel features' of the Constitution; the idea comes from Ireland.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1279","q":"Which Article among the Fundamental Rights prohibits the employment of children in factories, stating that 'no child below the age of fourteen years shall be employed to work in any factory or mine or engaged in any other hazardous employment'?","o":["Article 19","Article 24","Article 31","Article 14"],"a":1,"x":"Article 24 prohibits employing children below 14 in factories, mines or other hazardous work.","e":"Right against exploitation = Articles 23 and 24.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1286","q":"What does the Indian Constitution say about the Directive Principles of State Policy?","o":["They override rights during a national emergency.","They are not enforceable but guide the governance of the state.","They are legally binding and enforceable by courts.","They are optional and can be ignored by the government."],"a":1,"x":"Directive Principles are not enforceable by courts, but they are fundamental in governance and guide the state in making laws (Article 37).","e":"Fundamental Rights are justiciable; DPSPs are not.","src":["PRT 10 Apr 2026 S2"]},{"id":"q4195","q":"Which of the following Articles deals with the improvement of public health under the Directive Principles of State Policy in the Indian Constitution?","o":["Article 40","Article 43","Article 47","Article 49"],"a":2,"x":"Article 47 directs the state to raise nutrition and living standards and improve public health.","e":"","src":["Nursery Teacher 23 Oct 2021 S1"]},{"id":"q7838","q":"Equality of opportunity in matters of public employment comes under which of the following Fundamental Rights?","o":["Right to Equality","Right to Freedom","Right against Exploitation","Cultural and Educational Rights"],"a":0,"x":"Equality of opportunity in public employment (Article 16) is part of the Right to Equality.","e":"","src":["Nursery Teacher 24 Jun 2023 S1"]},{"id":"q1471","q":"Which Article of the Indian Constitution provides protection of life and personal liberty?","o":["Article 29","Article 25","Article 21","Article 19"],"a":2,"x":"Article 21: no person shall be deprived of life or personal liberty except according to procedure established by law.","e":"Maneka Gandhi (1978) held the procedure must be 'just, fair and reasonable'.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1511","q":"In which of the following Articles of the Indian Constitution have the provisions regarding 'Rights of citizenship of certain migrants to Pakistan' been discussed?","o":["Article 3","Article 7","Article 13","Article 23"],"a":1,"x":"Article 7 covers the citizenship rights of people who migrated to Pakistan after 1 March 1947: they are not citizens of India unless they came back under a resettlement permit.","e":"Article 6: migrants from Pakistan to India. Article 8: persons of Indian origin living abroad.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1560","q":"Which Part of the Indian Constitution deals with Fundamental Duties?","o":["Part VIB","Part IIA","Part IVA","Part VB"],"a":2,"x":"Part IVA (Article 51A) deals with Fundamental Duties, added by the 42nd Amendment (1976).","e":"Fundamental Duties are not enforceable in court.","src":["TGT 31 Aug 2025 S1"]},{"id":"q3390","q":"Articles 36-51 of the Indian Constitution specify the:","o":["Fundamental Rights of citizens","Directive Principles of State Policy","Number of seats and election process to the Rajya Sabha","The powers and provisions with regard to The Union"],"a":1,"x":"Articles 36–51 (Part IV) contain the Directive Principles of State Policy.","e":"","src":["TGT 18 Sep 2021 S3"]},{"id":"q3530","q":"Which article of Indian constitution is related to Uniform Civil Code for the citizents?","o":["Article 42","Article 44","Article 40","Article 46"],"a":1,"x":"Article 44 (a Directive Principle) asks the state to secure a Uniform Civil Code for citizens.","e":"","src":["TGT 1 Oct 2021 S1"]},{"id":"q5087","q":"In which year was the Citizenship Act passed in India?","o":["1951","1955","1959","1964"],"a":1,"x":"The Citizenship Act was passed in 1955.","e":"","src":["TGT 26 Sep 2021 S2"]},{"id":"q5873","q":"According to Indian Constitution, which pair of Article – Fundamental right is correct? I. Article 14 – Equality before law II. Article 26 – Freedom to manage religious affairs","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 14 gives equality before law and Article 26 freedom to manage religious affairs, so both pairs are correct.","e":"","src":["TGT 6 Sep 2021 S1"]},{"id":"q5909","q":"______ has the power to regulate the right of citizenship in India.","o":["President","Prime minister","Parliament","Supreme court"],"a":2,"x":"Under Article 11, Parliament has the power to regulate citizenship by law.","e":"","src":["TGT 6 Sep 2021 S3"]},{"id":"q6268","q":"From which country’s constitution the provision of fundamental rights has been borrowed?","o":["United states of America","Canada","Ireland","Australia"],"a":0,"x":"The idea of Fundamental Rights was borrowed from the US Constitution (Bill of Rights).","e":"","src":["TGT 9 Oct 2021 S3"]},{"id":"q6458","q":"What Article of the Indian Constitution provides for organization of Village Panchayats?","o":["39","39A","48","40"],"a":3,"x":"Article 40 (a Directive Principle) asks the state to organise village panchayats.","e":"","src":["TGT 26 Jul 2021 S1"]},{"id":"q7968","q":"Which committee on Fundamental Rights made the following suggestions about Fundamental Rights in India: 1- it made distinction between justiciable rights and non-justiciable rights. 2- it suggested that rights of the minorities must be protected.","o":["Nehru committee","The Sapru Committee","Sub-Committee of the Constituent Assembly on Fundamental Rights","Annie Besant Committee"],"a":1,"x":"The Sapru Committee (1945) distinguished justiciable and non-justiciable rights and stressed protection of minorities.","e":"","src":["TGT 6 Jul 2023 S2"]},{"id":"q8784","q":"The ways in which the government has tried to implement the equality that is guaranteed in the constitution is ______. I. through laws II. through government programmes","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The government puts constitutional equality into practice through laws and through government programmes (NCERT Class 7).","e":"","src":["TGT 24 Jun 2023 S2"]},{"id":"q9805","q":"In which of the following Articles of the Indian Constitution have the provisions regarding 'Rights of citizenship of certain migrants to Pakistan' been discussed?","o":["Article 3","Article 7","Article 13","Article 23"],"a":1,"x":"Article 7 deals with the citizenship rights of certain migrants to Pakistan.","e":"","src":["TGT 24 Aug 2025 S1"]},{"id":"q8799","q":"Under Article 29(1) of the Indian Constitution, which of the following is a right given to citizens?","o":["Right to property and life","Right to conserve their distinct language, script or culture","Right to form associations or unions","Right to establish and administer educational institutions"],"a":1,"x":"Article 29(1) gives citizens with a distinct language, script or culture the right to conserve it.","e":"","src":["Special Educator 24 Jun 2025 S3"]},{"id":"q8841","q":"Which of the following best describes the Supreme Court's writ jurisdiction under Article 32?","o":["It can issue writs only for enforcing Fundamental Rights.","It can issue writs for administrative purposes.","It cannot issue writs at all.","It can issue writs only for enforcing legal rights."],"a":0,"x":"Under Article 32 the Supreme Court can issue writs only to enforce Fundamental Rights; High Courts (Article 226) can also enforce other legal rights.","e":"","src":["Special Educator 29 Jun 2025 S1"]},{"id":"q9843","q":"The Indian Constitution provides for citizenship for anyone who has been ordinarily resident in the territory of India for not less than ______.","o":["5 years","3 years","2 years","4 years"],"a":0,"x":"Under Article 5, a person ordinarily resident in India for at least five years before 26 January 1950 became a citizen.","e":"","src":["Special Educator 14 Jul 2024 S1"]},{"id":"q0838","q":"Which of the following statements about Fundamental Rights are correct? 1. Article 17 abolishes untouchability and forbids its practice in any form. 2. The concept of equality before law is taken from the British Constitution. 3. Article 15 prohibits discrimination against any citizen on grounds of religion, race, caste, sex or place of birth.","o":["Only 1 and 2","All 1, 2 and 3","Only 3","Only 2 and 3"],"a":1,"x":"All three are correct: Article 17 abolishes untouchability; 'equality before law' comes from Britain; Article 15 bans discrimination on religion, race, caste, sex or place of birth.","e":"'Equal protection of laws' in Article 14 comes from the USA.","src":["PGT 26 Sep 2025"]},{"id":"q0854","q":"Which statements about the rights guaranteed under Article 19 are correct? 1. The right to form associations or unions or co-operative societies. 2. The right to move freely throughout the territory of India. 3. The right to seek foreign employment.","o":["3 only","1, 2 and 3 only","1 and 2 only","1 only"],"a":2,"x":"Statements 1 and 2 are right: Article 19(1)(c) gives the right to form associations and unions, and 19(1)(d) the right to move freely in India. There is no Article 19 right to foreign employment.","e":"Article 19 has six freedoms; the right to property, 19(1)(f), was removed in 1978.","src":["PGT 14 Jul 2025"]},{"id":"q7802","q":"What Article of the Indian Constitution provides for free legal aid to the poor and weaker sections of the society?","o":["30","39A","36","41"],"a":1,"x":"Article 39A (a Directive Principle, added in 1976) provides for equal justice and free legal aid.","e":"","src":["PGT 23 Jul 2021"]},{"id":"q8090","q":"Which of the following Rights is available only to citizens and NOT to foreigners?","o":["Protection in respect of conviction for offences","Protection of life and personal liberty","Right to elementary education","Prohibition on discrimination on grounds of religion, race, caste, sex or place of birth"],"a":3,"x":"The Article 15 bar on discrimination (religion, race, caste, sex, place of birth) is available only to citizens.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8387","q":"Who among the following has described Part III ‘as the most criticised part’ of the Constitution?","o":["S Radhakrishnan","B R Ambedkar","Mahatma Gandhi","MN Roy"],"a":1,"x":"Ambedkar said Part III (Fundamental Rights) was the most criticised part of the Draft Constitution.","e":"","src":["PGT 5 Jul 2023 S1"]},{"id":"q8439","q":"The 86th Constitutional Amendment Act of 2002, passed by the Indian Parliament, establishes the basic rights to primary education for children aged ______.","o":["5-11 years","6-14 years","7-16 years","6-17 years"],"a":1,"x":"The 86th Amendment (2002) made education a fundamental right for children aged 6 to 14 (Article 21A).","e":"","src":["PGT 22 Jun 2023 S1"]},{"id":"q8472","q":"Who among the following described fundamental rights ‘as a pledge to our people and a pact with the civilised world’?","o":["Balwant Rai Mehta","S Radhakrishnan","Zakir Hussain","Ashok Mehta"],"a":1,"x":"S. Radhakrishnan called Fundamental Rights a pledge to our people and a pact with the civilised world.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q8507","q":"Who among the following grants the permission to a person (who is holding any office of profit or trust under the State) to accept any present, emolument, or office of any kind from or under any foreign State, under Article 18 of the Constitution?","o":["President","Prime Minister","Union Home Minister","Union External Affairs"],"a":0,"x":"Under Article 18(4), a person holding an office of profit needs the President's consent to accept any gift or office from a foreign state.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q8538","q":"The Fundamental Duties were added to the constitution vide 42nd Amendment upon the recommendation of which committee?","o":["Verma Committee","Justice Lodha Committee","Joint Committee on Indian Constitutional Reforms","Swaran Singh Committee"],"a":3,"x":"Fundamental Duties were added by the 42nd Amendment (1976) on the Swaran Singh Committee's recommendation.","e":"","src":["PGT 3 Nov 2022"]},{"id":"q8558","q":"No person shall be prosecuted and punished for the same offence more than once. Which Article of the Indian Constitution states this?","o":["Article 19","Article 20","Article 21","Article 22"],"a":1,"x":"Protection against double jeopardy is in Article 20(2).","e":"","src":["PGT 3 Nov 2022"]},{"id":"q9531","q":"Which among the following articles prohibits discrimination on the basis of religion, race, sex, or place of birth?","o":["12","13","14","15"],"a":3,"x":"Article 15 bars discrimination on grounds of religion, race, caste, sex or place of birth.","e":"","src":["PGT 30 Jun 2021 S2"]},{"id":"q10035","q":"Which article of the constitution mentions that “No person who is not a citizen of India shall, while he holds any office of profit or trust under the State, accept without the consent of the President any title from any foreign State”?","o":["Article – 18 (3)","Article – 19 (1)","Article - 15 (2)","Article – 22 (2)"],"a":0,"x":"Article 18(3): a non-citizen holding an office of profit needs the President's consent to accept a foreign title.","e":"","src":["Junior Engineer (Civil) or Section Officer (Civil) 27 Jun 2022 S1"]},{"id":"q1642","q":"Which article of Indian Constitution is related to the separation of judiciary from executive?","o":["44","47","50","54"],"a":2,"x":"Article 50 (a Directive Principle) calls for separating the judiciary from the executive.","e":"","src":["Senior Scientific Assistant (Lie-Detection) 10 Oct 2021 S1"]},{"id":"q2564","q":"The Kerala High Court had ruled that the right to have access to the Internet is part of the fundamental Right to Education (RTE) & also the Right to Privacy under Article _______ of the Constitution.","o":["25","21","243","345"],"a":1,"x":"The Kerala High Court (2019) held internet access to be part of the right to education and privacy under Article 21.","e":"","src":["Technical Assistant (Medical Electronics) 16 Nov 2021 S2"]},{"id":"q2789","q":"In 1978, the 44th amendment to the Constitution removed the right to property from the list under ______.","o":["Article 342 A","Article 300 A","Article 246 A","Article 279 A"],"a":1,"x":"The 44th Amendment (1978) made the right to property a legal right under Article 300A.","e":"","src":["Inspecting Officer 16 Oct 2021 S1"]},{"id":"q3300","q":"Which of the following statement is CORRECT? I. Article 44 of Indian constitution deals with uniform civil code for the citizens. II. Article 24 of Indian constitution deals with protection of interests of minorities.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Article 44 deals with a uniform civil code; Article 24 bans child labour, not minority rights (Articles 29–30).","e":"","src":["Senior Scientific Assistant (Document) 18 Sep 2021 S1"]},{"id":"q5065","q":"Article 31A was added to the Constitution of India by the virtue of which of the following amendments?","o":["5th Amendment","4th Amendment","2nd Amendment","1st Amendment"],"a":3,"x":"Article 31A was added by the 1st Amendment (1951).","e":"","src":["Scientific Assistant (Physics) 26 Sep 2021 S1"]},{"id":"q5129","q":"The concept of Fundamental Duties in the Indian constitution is borrowed from the constitution of __________.","o":["France","Canada","Union of Soviet Socialist Republics (USSR)","Ireland"],"a":2,"x":"Fundamental Duties were borrowed from the Constitution of the USSR.","e":"","src":["Assistant Engineer (Civil) 26 Sep 2021 S3"]},{"id":"q5238","q":"Which of the following statement is CORRECT? I. Part II of Indian constitution is related with citizenship. II. Article 17 of Indian constitution is related with abolition of titles.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Part II covers citizenship, but Article 17 abolishes untouchability; titles are abolished by Article 18.","e":"","src":["Senior Scientific Assistant (Chemistry) 27 Sep 2021 S2"]},{"id":"q5279","q":"Which of the following statement is CORRECT? I. Part IV of Indian constitution deals with provision of fundamental rights. II. Article 24 of Indian constitution deals with freedom to manage religious affairs.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both are wrong: Part III has the Fundamental Rights (Part IV is DPSP), and Article 24 bans child labour.","e":"","src":["Senior Scientific Assistant (Physics) 27 Sep 2021 S3"]},{"id":"q8150","q":"Under Assam Accord of 1985, foreigners who had entered Assam before March 25, ________ were to be given citizenship.","o":["1966","1971","1954","1981"],"a":1,"x":"Under the 1985 Assam Accord, foreigners who entered Assam before 25 March 1971 were to get citizenship.","e":"","src":["Junior Engineer (Civil) or Section Officer (Civil) 27 Jun 2022 S2"]},{"id":"q8164","q":"In which of the following years, right of child to free and compulsory education act was passed?","o":["2005","1988","1999","2009"],"a":3,"x":"The Right of Children to Free and Compulsory Education Act was passed in 2009.","e":"","src":["Junior Engineer (Civil) or Section Officer (Civil) 27 Jun 2022 S2"]},{"id":"q8223","q":"Which article of the constitution mentions that “When any person is detained in pursuance of an order made under any law providing for preventive detention, the authority making the order shall, as soon as may be, communicate to such person the grounds on which the order has been made and shall afford him the earliest opportunity of making a representation against the order”?","o":["18 (1)","20 (3)","22 (5)","16 (3)"],"a":2,"x":"Article 22(5) requires preventive detainees to be told the grounds and allowed to make a representation.","e":"","src":["Legal Assistant or Assistant Law Officer 20 Jun 2022 S2"]},{"id":"q8722","q":"Under which of the following Articles of the Indian Constitution are the citizens given Fundamental Rights?","o":["Articles 12-15","Articles 12-35","Articles 25-28","Articles 29-30"],"a":1,"x":"Fundamental Rights are in Articles 12–35.","e":"","src":["Tailor Master 25 Jun 2023 S3"]},{"id":"q8723","q":"The Supreme Court of India has issued a landmark ruling and declared privacy a fundamental right since ________.","o":["26 January 2010","1 April 2010","11 August 2017","24 August 2017"],"a":3,"x":"The Supreme Court declared privacy a fundamental right on 24 August 2017 (Puttaswamy case).","e":"","src":["Tailor Master 25 Jun 2023 S3"]},{"id":"q9881","q":"Which of the following Articles of the Indian Constitution forbids the class legislation but permits reasonable classification of persons, objects and transactions by the law?","o":["Article 14","Article 17","Article 21","Article 19"],"a":0,"x":"Article 14 forbids class legislation but allows reasonable classification.","e":"","src":["Scientific Assistant 27 Jul 2024 S2"]},{"id":"q9938","q":"Which of the following is NOT included under right to freedom as per the Indian Constitution?","o":["Move freely throughout the territory of India.","Formation of associations or unions.","To promote the religion of one’s choice.","Freedom of speech and expression."],"a":2,"x":"Promoting one's religion is not under the Right to Freedom (Article 19); religious freedom is in Articles 25–28.","e":"","src":["Junior Engineer (Electrical) or Section Officer (Electrical) 16 Mar 2022"]},{"id":"q9948","q":"Which of the following is NOT one of the fundamental duties of Indian citizens as per the Indian Constitution?","o":["To cherish and follow the noble ideals which inspired our national struggle for freedom.","To uphold and protect the sovereignty, unity, and integrity of India.","To follow all religious norms under all circumstances.","To value and preserve the rich heritage of our composite culture."],"a":2,"x":"'Following all religious norms' is not a Fundamental Duty.","e":"","src":["Junior Engineer (Electrical) or Section Officer (Electrical) 16 Mar 2022"]}]},{"id":"union","n":"President, Prime Minister and Parliament","qs":[{"id":"q0075","q":"On whose advice does the President summon or prorogue Parliament sessions and dissolve the Lok Sabha?","o":["The Election Commission","The Chief Justice","The Speaker","The Council of Ministers"],"a":3,"x":"Under Article 74 the President acts on the advice of the Council of Ministers headed by the Prime Minister, including when summoning and proroguing Parliament or dissolving the Lok Sabha.","e":"Article 85 is the summon/prorogue/dissolve power; the advice is binding after the 42nd and 44th Amendments.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0076","q":"The Rajya Sabha in India is also known as the _______.","o":["Legislative Council","Upper Council","Council of States","National Assembly"],"a":2,"x":"The Rajya Sabha is the Council of States, the upper house that represents the states and UTs; it is a permanent body that is never dissolved.","e":"Lok Sabha = House of the People. One-third of Rajya Sabha members retire every two years.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0109","q":"Who among the following has the power to promulgate ordinances during the recess of Parliament, as per Article 123?","o":["The Speaker of Lok Sabha","The Chief Justice of India","The Prime Minister","The President of India"],"a":3,"x":"Article 123 lets the President issue ordinances when Parliament is not in session; an ordinance lapses six weeks after Parliament reassembles unless approved.","e":"Governors have the same power for states under Article 213.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0221","q":"Who is the executive head of the government at the central level in India?","o":["The Vice President","The Prime Minister","The President","The Chief Justice of India"],"a":2,"x":"Under Article 53 the executive power of the Union is vested in the President, the formal (constitutional) head of the executive. Real power is used by the Council of Ministers led by the Prime Minister.","e":"The President is the nominal head; the Prime Minister is the real head of government.","src":["ASO 20 Aug 2025 S1"],"k":"Many books call the Prime Minister the 'real executive head'; this question's key takes the constitutional head, the President."},{"id":"q0223","q":"Who is the only President of India to have been elected unopposed?","o":["Dr. Shankar Dayal Sharma","Dr. Neelam Sanjiva Reddy","Dr. Rajendra Prasad","Dr. APJ Abdul Kalam"],"a":1,"x":"Neelam Sanjiva Reddy is the only President elected unopposed, in 1977.","e":"Dr Rajendra Prasad is the only President elected twice.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0263","q":"The Parliament of India consists of the _____.","o":["Lok Sabha and the President","Lok Sabha and the Rajya Sabha","Lok Sabha, the Rajya Sabha and the President of India","Rajya Sabha and the President"],"a":2,"x":"Under Article 79, Parliament consists of the President and two Houses: the Rajya Sabha (Council of States) and the Lok Sabha (House of the People).","e":"The President is part of Parliament but not a member of either House.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0274","q":"Which of the following is a key difference between Standing Committees and Ad hoc Committees of the Indian Parliament?","o":["Standing Committees are elected, while Ad hoc Committees are nominated.","Standing Committees are permanent, while Ad hoc Committees are temporary and task specific.","Standing Committees deal with financial matters, while Ad hoc Committees deal with legislative matters.","Standing Committees report to the Speaker, while Ad hoc Committees report to the House."],"a":1,"x":"Standing committees are permanent and meet all the time (for example the Public Accounts Committee). Ad hoc committees are formed for one task and end when it is done.","e":"An example of an ad hoc committee is a Joint Committee on a particular bill.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0305","q":"As per the Constitution, the executive power of the Central Government is vested in the _____.","o":["Vice President","Prime Minister","Parliament","President"],"a":3,"x":"Article 53: the executive power of the Union is vested in the President, used directly or through subordinate officers.","e":"For states, Article 154 vests it in the Governor.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0320","q":"Which of the following statements about the role of the President in India’s parliamentary system is correct?","o":["The President’s assent is mandatory for a bill to become law.","A bill becomes law immediately after it is passed by both Houses.","The President has no role in summoning or dissolving the Houses.","The Indian system follows the American pattern of governance."],"a":0,"x":"A bill becomes law only after the President's assent (Article 111), even after both Houses pass it.","e":"On a non-money bill the President may return it once for reconsideration.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0388","q":"Which of the following is the maximum permissible strength that the Rajya Sabha can have?","o":["240","300","245","250"],"a":3,"x":"Article 80 fixes the maximum strength of the Rajya Sabha at 250: 238 elected from states and UTs, and 12 nominated by the President.","e":"Present strength is 245.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0468","q":"Which of the following is the second-highest Constitutional position in India?","o":["President of India","Home Minister of India","Prime Minister of India","Vice President of India"],"a":3,"x":"The Vice President is the second-highest constitutional office in India and is the ex-officio Chairman of the Rajya Sabha.","e":"The Prime Minister comes after them in the order of precedence.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1575","q":"Which article of the Constitution lays down the maximum strength of Rajya Sabha as 250?","o":["Article 67","Article 79","Article 80","Article 56"],"a":2,"x":"Article 80 fixes the Rajya Sabha's maximum strength at 250 (238 elected + 12 nominated).","e":"Article 81 sets the composition of the Lok Sabha.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1580","q":"The President used to nominate two members of Anglo-Indian Community to Lok Sabha till which year, which now has been abolished?","o":["2019","2016","2020","2017"],"a":2,"x":"The President could nominate two Anglo-Indian members to the Lok Sabha (Article 331) until January 2020; the 104th Amendment (2019) ended this.","e":"The same amendment extended SC/ST reservation by 10 years, to 2030.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q0552","q":"The quorum for the meeting of the Rajya Sabha is fixed at __________ of the total members.","o":["one-tenth","one-seventh","one-sixth","one-ninth"],"a":0,"x":"The quorum of each House of Parliament is one-tenth of its total membership (Article 100).","e":"Presiding officers: Lok Sabha Speaker; Rajya Sabha Chairman (the Vice President).","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0593","q":"Who among the following is the ex-officio chairman of the Rajya Sabha?","o":["Vice President of India","Finance Minister of India","President of India","Prime Minister of India"],"a":0,"x":"The Vice President is the ex-officio Chairman of the Rajya Sabha (Article 89).","e":"The Deputy Chairman is elected from among Rajya Sabha members.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0753","q":"As of April 2020, the membership of the Rajya Sabha contains a provision for how many nominated members?","o":["20","12","16","18"],"a":1,"x":"The President nominates 12 members to the Rajya Sabha for special knowledge in literature, science, art and social service (Article 80).","e":"The two Anglo-Indian seats in the Lok Sabha ended in 2020.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1772","q":"Which of the following statement regarding Eligibility for election of Vice President is correct? I. He has completed the age of thirty five years. II. He is Qualified for election as a member of the council of states.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Under Article 66 a Vice-President must be a citizen of India, at least 35 years old and qualified for election as a member of the Rajya Sabha.","e":"President: qualified for the Lok Sabha; Vice-President: for the Rajya Sabha.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1812","q":"Which article of the Indian constitution deals with The President of India?","o":["52","54","55","53"],"a":0,"x":"Article 52 says there shall be a President of India; Article 53 vests the Union's executive power in him.","e":"52 President, 53 executive power, 54 election, 58 qualifications.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1815","q":"Which of the following statement regarding the President is correct? I. Article 54 of the Indian constitution deals with election of President. II. Article 58 of the Indian constitution deals with qualifications for election as President.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 54 covers the President's election (by an electoral college) and Article 58 the qualifications for election as President, so both are correct.","e":"Article 55: manner of election; 56: term; 61: impeachment.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1964","q":"Which article of the Indian Constitution deals with power of President to grant pardons etc. and to suspend, remit or commute sentences in certain cases?","o":["68","69","70","72"],"a":3,"x":"Article 72 gives the President power to grant pardons, reprieves, respites or remissions and to suspend, remit or commute sentences; Article 161 gives Governors a similar power.","e":"President: 72; Governor: 161.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1965","q":"Which article of the Indian Constitution deals with Annual Financial Statement?","o":["109","110","111","112"],"a":3,"x":"Article 112 requires the President to lay the Annual Financial Statement (the Union Budget) before Parliament.","e":"112 budget, 113 grants, 114 appropriation, 117 financial bills.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2005","q":"Which article of the Indian Constitution deals with council of ministers to aid and advise President?","o":["70","71","74","75"],"a":2,"x":"Article 74: a Council of Ministers headed by the Prime Minister aids and advises the President, who must act on its advice (42nd and 44th Amendments).","e":"74 advises; 75 appoints.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2006","q":"Which article of the Indian Constitution deals with Appropriation Bills?","o":["114","112","111","110"],"a":0,"x":"Article 114 covers the Appropriation Bill, which authorises withdrawal of money from the Consolidated Fund of India.","e":"No money leaves the Consolidated Fund without an Appropriation Act.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2007","q":"Which of the following statement(s) regarding article 361 of the Indian Constitution is/are correct? I. No criminal proceedings what so even shall be instituted or continued against the President or the Governor of a state in any court during his term of office. II. No process for the arrest or imprisonment of the President or the Governor of a state, shall issue from any court during his term of office.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 361: no criminal proceedings can be started or continued, and no arrest or imprisonment ordered, against the President or a Governor during the term of office. Both statements are correct.","e":"Civil proceedings need two months' notice.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2050","q":"Which article of the Indian Constitution deals with the Attorney General of India?","o":["76","75","74","73"],"a":0,"x":"Article 76 deals with the Attorney General of India, the government's chief legal adviser, appointed by the President.","e":"Article 165: Advocate General of a state.","src":["Junior Clerk 12 Nov 2021 S3","Junior Clerk 13 Nov 2021 S1"]},{"id":"q2051","q":"Which article of the Indian Constitution deals with courts not to inquire into proceedings of parliament?","o":["121","117","122","119"],"a":2,"x":"Article 122 says courts shall not inquire into the proceedings of Parliament; Article 212 says the same for state legislatures.","e":"Parliament 122; state legislatures 212.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2096","q":"______ shall be ex officio chairman of the council of states and shall not hold any other office of profit.","o":["The Vice President","President","The Prime Minister","Attorney General of India"],"a":0,"x":"Under Article 64 the Vice-President is the ex-officio Chairman of the Rajya Sabha (Council of States) and holds no other office of profit.","e":"The Deputy Chairman is elected by the Rajya Sabha.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2133","q":"Which of the following statement regarding Parliament is correct? I. Article 83 of the Indian constitution deals with Duration of houses of parliament. II. Article 84 of the Indian constitution deals with Qualification for membership of parliament.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 83 deals with the duration of the Houses of Parliament and Article 84 with qualifications for membership, so both are correct.","e":"Lok Sabha minimum age 25; Rajya Sabha 30.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2174","q":"Which of the following articles of the Indian Constitution is related to the impeachment of the President?","o":["Article 52","Article 57","Article 61","Article 65"],"a":2,"x":"Article 61 lays down the procedure for impeaching the President for violating the Constitution; it needs a two-thirds majority in both Houses.","e":"Article 56: term; 57: re-election; 61: impeachment.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2175","q":"According to the 84th Amendment Act of 2001, till which year has the allocation of seats in the Lok Sabha to the states and the division of each state into territorial constituencies been frozen?","o":["2021","2023","2025","2026"],"a":3,"x":"The 84th Amendment (2001) froze the allocation of Lok Sabha seats to states and the delimitation of constituencies until the first census after 2026.","e":"The 42nd Amendment had first frozen seats on the 1971 census.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2421","q":"Which of the following articles of the Indian Constitution states that \"There shall be a Council of Ministers with the Prime Minister at the head to aid and advise the President\"?","o":["74(1)","74(2)","75(1)","75(2)"],"a":0,"x":"Article 74(1) says there shall be a Council of Ministers with the Prime Minister at its head to aid and advise the President.","e":"74(2): courts cannot inquire into the advice given.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2453","q":"Who out of the following is Shankar Dayal Sharma?","o":["Former President of India","Former Prime Minister of India","Former Governor of RBI","Former Home Minister of India"],"a":0,"x":"Dr Shankar Dayal Sharma was the ninth President of India (1992–97); before that he was Vice-President.","e":"Presidents in order: Venkataraman → S.D. Sharma → K.R. Narayanan.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2618","q":"Which article of the Indian Constitution deals with composition of the house of the people?","o":["79","80","81","84"],"a":2,"x":"Article 81 deals with the composition of the Lok Sabha (House of the People).","e":"Article 80: Rajya Sabha; 81: Lok Sabha.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2689","q":"Which article of the Indian Constitution deals with composition of the council of states?","o":["81","80","79","78"],"a":1,"x":"Article 80 deals with the composition of the Rajya Sabha (up to 250 members, 12 nominated).","e":"","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q6131","q":"Which of the following are appointed by the President of India? I. The Attorney General of India II. Vice President","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"The President appoints the Attorney General; the Vice President is elected by an electoral college of both Houses of Parliament.","e":"","src":["Junior Clerk 9 Nov 2021 S1"]},{"id":"q6226","q":"Article 80 of the Indian constitution deals with _____________.","o":["Constitution of Parliament","Readjustment after each census","Composition of the council of states","Composition of the house of the people"],"a":2,"x":"Article 80 deals with the composition of the Rajya Sabha (Council of States); Article 81 covers the Lok Sabha.","e":"","src":["Junior Clerk 9 Nov 2021 S3"]},{"id":"q1320","q":"Which of the following articles of the Indian Constitution empowers each House of the Parliament to make rules for regulations, subject to the provisions of this Constitution, its procedure and the conduct of its business?","o":["Article 118(1)","Article 118(2)","Article 118(4)","Article 118(3)"],"a":0,"x":"Article 118(1) lets each House of Parliament make rules for its procedure and conduct of business, subject to the Constitution.","e":"Article 118(4): the Speaker presides over joint sittings.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1349","q":"The 91st Constitutional Amendment restricted the size of council of ministers to ________ of legislative members.","o":["18 percent","20 percent","10 percent","15 percent"],"a":3,"x":"The 91st Amendment (2003) capped the Council of Ministers at 15% of the total strength of the Lok Sabha or state Legislative Assembly.","e":"Small states must still have at least 12 ministers.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q4896","q":"The joint sitting of the Parliament is called by ______.","o":["President of India","Vice President of India","Deputy Speaker of the Lok Sabha","Deputy Chairman of the Rajya Sabha"],"a":0,"x":"The President summons a joint sitting of Parliament (Article 108); the Speaker presides.","e":"","src":["Stenographer 26 Nov 2021 S1"]},{"id":"q7020","q":"The method of election of President in the Indian Constitution is borrowed from the constitution of _____________.","o":["United States of America","Ireland","Germany","France"],"a":1,"x":"The method of electing the President was borrowed from Ireland.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q5395","q":"Who among them was the Minister in charge of disinvestment in the NDA government at the Centre?","o":["Ajit Singh","Arun Shourie","Yashwant Sinha","I K Gujral"],"a":1,"x":"Arun Shourie was India's first Minister of Disinvestment, in the Vajpayee (NDA) government.","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q10069","q":"In which Article of the Indian Constitution is the provision for reservation of seats for Scheduled Castes and Scheduled Tribes in the Lok Sabha?","o":["Article 330","Article 148","Article 280","Article 213"],"a":0,"x":"Article 330 reserves seats for Scheduled Castes and Scheduled Tribes in the Lok Sabha.","e":"","src":["Assistant Superintendent 20 Jul 2024 S1"]},{"id":"q4491","q":"During the tenure of which Prime Minister India carried out the Pokhran II nuclear test?","o":["Atal Bihari Vajpayee","APJ Abdul Kalam","Inder Kumar Gujral","Manmohan Singh"],"a":0,"x":"The Pokhran-II nuclear tests (May 1998) took place when Atal Bihari Vajpayee was Prime Minister.","e":"","src":["Office Superintendent 24 Oct 2021 S2"]},{"id":"q8927","q":"Who acts as President if there is a vacancy in the office of the President of India?","o":["Vice-President","Chief Justice of India","Prime Minister","Speaker of Lok Sabha"],"a":0,"x":"When the President's office falls vacant, the Vice-President acts as President.","e":"If both are vacant, the Chief Justice of India acts.","src":["MTS 3 Mar 2026 S1"]},{"id":"q8999","q":"Members of the Lok Sabha are ________.","o":["Nominated by State Governors","Chosen by the Judiciary","Directly elected by the citizens","Appointed by the President"],"a":2,"x":"Members of the Lok Sabha are directly elected by the people.","e":"","src":["MTS 3 Mar 2026 S3"]},{"id":"q9008","q":"Which of the following is NOT part of the electoral college that elects the President of India?","o":["Elected members of Legislative Assemblies of the states","Elected members of Lok Sabha and Rajya Sabha","Elected members of Union Territories of Delhi and Puducherry","Nominated members of Lok Sabha and Rajya Sabha"],"a":3,"x":"Only elected members of Parliament and of the state and Delhi and Puducherry assemblies elect the President; nominated members do not vote.","e":"","src":["MTS 3 Mar 2026 S3"]},{"id":"q9046","q":"Under the constitutional scheme, the appointment of the Prime Minister, the appointment of other ministers on the Prime Minister’s advice, and the allocation of ministerial portfolios on such advice are carried out by which constitutional authority of India?","o":["Council of Ministers","President of India","Prime Minister of India","Speaker of the Lok Sabha"],"a":1,"x":"The President appoints the Prime Minister and, on the PM's advice, other ministers and their portfolios (Article 75).","e":"","src":["MTS 5 Mar 2026 S2"]},{"id":"q9091","q":"The constitutional provision stating that there shall be a Parliament for the Union consisting of the President and two Houses, namely the Council of States and the House of the People, is contained in which Article of the Indian Constitution?","o":["Article 81","Article 79","Article 74","Article 80"],"a":1,"x":"Article 79: Parliament consists of the President and two Houses, the Council of States and the House of the People.","e":"","src":["MTS 6 Mar 2026 S1"]},{"id":"q9116","q":"The Constitutional Provision that fixes the normal term of the House of the People at five years and permits its extension during a Proclamation of Emergency is contained in which Article of the Indian Constitution?","o":["Article 172","Article 81","Article 85","Article 83(2)"],"a":3,"x":"Article 83(2) fixes the Lok Sabha's term at five years; during an emergency Parliament can extend it one year at a time.","e":"","src":["MTS 6 Mar 2026 S2"]},{"id":"q9118","q":"Which Articles of the Constitution cover the Union Executive’s roles and responsibilities in India?","o":["Articles 100 to 120","Articles 80 to 100","Articles 1 to 51","Articles 52 to 78"],"a":3,"x":"Articles 52 to 78 (Part V) deal with the Union Executive.","e":"","src":["MTS 6 Mar 2026 S2"]},{"id":"q9196","q":"Which of the following statements is/are correct regarding the functions of the Vice-President of India? (a) They act as the ex-officio Chairman of Rajya Sabha. (b) When a vacancy occurs in the office of the President, they can act as the President only for a maximum period of 3 months, within which a new President has to be elected.","o":["Only (b)","Only (a)","Neither (a) nor (b)","Both (a) and (b)"],"a":1,"x":"The Vice-President is ex-officio Chairman of the Rajya Sabha. If the President's office falls vacant, an election must be held within six months, not three.","e":"","src":["MTS 8 Mar 2026 S1"]},{"id":"q9310","q":"Which of the following advises the President of India in the exercise of its functions?","o":["The Prime Minister and The Union Council of Ministers","Prime Minister and Chief Justice of India","Cabinet Secretariat and Rajya Sabha","Prime Minister and Speaker of Lok Sabha"],"a":0,"x":"The Prime Minister and the Union Council of Ministers aid and advise the President (Article 74).","e":"","src":["MTS 24 Feb 2026 S3"]},{"id":"q9354","q":"The Committee on Public Undertakings was created in 1964 following recommendations of which committee?","o":["Mathai Committee","Joint Parliamentary Committee","Krishna Menon Committee","Rules Committee"],"a":2,"x":"The Committee on Public Undertakings was set up in 1964 on the recommendation of the Krishna Menon Committee.","e":"","src":["MTS 25 Feb 2026 S1"]},{"id":"q9380","q":"Which voting method is used to elect the President of India?","o":["Preferential voting","Secret ballot with single transferable voting","Open voting","Hand raise"],"a":1,"x":"The President is elected by proportional representation through the single transferable vote, by secret ballot.","e":"","src":["MTS 25 Feb 2026 S3"]},{"id":"q9391","q":"Which of the following is conducted during the first hour of Parliament?","o":["Debate Hour","Zero Hour","Question Hour","Motion Hour"],"a":2,"x":"The first hour of a sitting of Parliament is Question Hour; Zero Hour follows.","e":"","src":["MTS 25 Feb 2026 S3"]},{"id":"q9459","q":"How many members does the Estimates Committee have, and how are they selected?","o":["15 members, elected by both Houses","30 members, elected by the Lok Sabha","22 members, nominated by the Speaker","30 members, nominated by the President"],"a":1,"x":"The Estimates Committee has 30 members, all elected by the Lok Sabha.","e":"","src":["MTS 26 Feb 2026 S3"]},{"id":"q3443","q":"Who appoints the Attorney General of India?","o":["The Prime Minister","The Governor","The President","The Chief Minister"],"a":2,"x":"The President appoints the Attorney General of India (Article 76); the Governor appoints a state's Advocate General (Article 165).","e":"","src":["Store Keeper 19 Apr 2021 S2"]},{"id":"q2732","q":"A member of Lok Sabha should not be less than _______ years of age.","o":["20","25","30","35"],"a":1,"x":"A Lok Sabha member must be at least 25 years old; a Rajya Sabha member at least 30.","e":"Article 84.","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q2734","q":"A bill that deals exclusively with money matters that are mentioned in Article _______ in Constitution is called a Money Bill.","o":["110","58","61","94"],"a":0,"x":"Article 110 defines a Money Bill: one dealing only with matters such as taxes, borrowing and the Consolidated Fund.","e":"The Speaker certifies a Money Bill.","src":["Ahlmad 16 Oct 2021 S1","PGT 31 Jul 2021 S1"]},{"id":"q2849","q":"For an individual to qualify for election as President of India, he/she must have completed the age of _________ years.","o":["35","30","40","45"],"a":0,"x":"To be elected President a person must be a citizen, at least 35 years old and qualified for election to the Lok Sabha (Article 58).","e":"","src":["Ahlmad 16 Oct 2021 S3"]},{"id":"q3230","q":"What is the maximum strength of the Lok Sabha envisaged by the Constitution?","o":["530","538","546","552"],"a":3,"x":"Article 81 allowed a maximum Lok Sabha strength of 552: up to 530 from states, 20 from UTs, and 2 nominated Anglo-Indians.","e":"Present strength: 543 elected.","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S2"],"k":"The two nominated Anglo-Indian seats ended in 2020 (104th Amendment), so the ceiling is now effectively 550."},{"id":"q3233","q":"Who out of the following is entitled for a casting vote in the Rajya Sabha?","o":["Rajya Sabha Chairman","Prime Minister","Leader of Opposition","President of India"],"a":0,"x":"The Chairman of the Rajya Sabha (the Vice-President) has only a casting vote, used in case of a tie.","e":"The Speaker also has a casting vote in the Lok Sabha.","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S2"]},{"id":"q3277","q":"How many members are sent from Uttar Pradesh to the Rajya Sabha?","o":["26","28","31","35"],"a":2,"x":"Uttar Pradesh sends 31 members to the Rajya Sabha, the most of any state.","e":"Seats follow the Fourth Schedule.","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S3"]},{"id":"q5493","q":"Who was popularly known as \"People's President of India”?","o":["Dr. A P J Abdul Kalam","Dr. Sarvepalli Radhakrishnan","Ramaswamy Venkataraman","Dr. Shankar Dayal Sharma"],"a":0,"x":"A.P.J. Abdul Kalam was called the 'People's President'.","e":"","src":["Accountant 29 Nov 2021 S3"]},{"id":"q0887","q":"According to which Amendment of the Constitution can the total number of ministers, including the Prime Minister, not exceed 15% of the Lok Sabha's strength?","o":["91st Amendment","42nd Amendment","44th Amendment","73rd Amendment"],"a":0,"x":"The 91st Amendment (2003) caps the Council of Ministers, including the PM, at 15% of the Lok Sabha's total strength (Article 75(1A)); the same cap applies to states, with a minimum of 12.","e":"It also tightened the anti-defection law by removing the 'split' exception.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0888","q":"Money Bills can be introduced only in _______.","o":["Rajya Sabha","Lok Sabha","Joint Sitting","either House"],"a":1,"x":"Under Article 109 a Money Bill can be introduced only in the Lok Sabha, and only on the President's recommendation; the Rajya Sabha can delay it for at most 14 days.","e":"The Speaker certifies what is a Money Bill.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0931","q":"According to the Constitution of India, which of the following is NOT a qualification for a Member of Parliament?","o":["Must be a citizen of India and make an oath or affirmation in the form set out in the Third Schedule","Must be at least 30 years old for the Rajya Sabha and at least 25 years old for the Lok Sabha","Must hold a degree from a university recognised by the University Grants Commission (UGC)","Must possess any additional qualifications prescribed by law made by Parliament"],"a":2,"x":"Article 84 requires an MP to be a citizen of India, to take the oath in the Third Schedule, to be at least 30 (Rajya Sabha) or 25 (Lok Sabha), and to meet any other qualification Parliament sets. No educational degree is required.","e":"The Representation of the People Act, 1951 sets the further conditions.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0967","q":"Which Article of the Indian Constitution relates to the appointment of the Prime Minister of India?","o":["Article 80","Article 62","Article 60","Article 75"],"a":3,"x":"Article 75: the Prime Minister is appointed by the President, and other ministers on the PM's advice.","e":"Article 74: Council of Ministers aids and advises the President.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0972","q":"Which statement correctly links constitutional provisions about ministers with the appropriate Schedules?","o":["A member disqualified under the Tenth Schedule cannot be appointed a minister for a specified period under Article 75(1B).","Under the Ninth Schedule, ministers hold office during the pleasure of the President.","The form of oath for ministers is laid down in the Second Schedule.","Collective responsibility of the Council of Ministers is enforced through the Fourth Schedule."],"a":0,"x":"Article 75(1B): a member disqualified for defection under the Tenth Schedule cannot become a minister until the end of that House's term or re-election. The ministers' oath forms are in the Third Schedule, not the Second.","e":"The 91st Amendment (2003) inserted Article 75(1B).","src":["PRT 18 Feb 2026 S3"]},{"id":"q1065","q":"How many times can the President return a bill passed by Parliament for reconsideration?","o":["Only once","Four times","Three times","More than four times"],"a":0,"x":"Under Article 111 the President can return a non-money bill to Parliament for reconsideration only once; if Parliament passes it again, the President must assent.","e":"Money bills cannot be returned.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1255","q":"According to the Indian Constitution, the executive power of the Union is:","o":["Shared equally between the President and the Chief Justice of India","Vested solely in the Prime Minister","Exercised only during a national emergency","Vested in the President and exercised by him directly or through subordinate officers"],"a":3,"x":"Article 53: the executive power of the Union is vested in the President and exercised by him directly or through subordinate officers under the Constitution.","e":"Supreme command of the armed forces also rests with the President.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1257","q":"Which of the following statements is CORRECT regarding the term of office of the President of India?","o":["The President can only be removed by the Prime Minister or the Chief Justice of India.","The President continues in office even after the term ends, until a successor takes charge.","The President must vacate office exactly on the completion of five years.","The President holds office for six years and cannot resign."],"a":1,"x":"The President's term is five years, but under Article 56(1)(c) the President continues in office after the term ends until a successor takes charge.","e":"The President can resign by writing to the Vice President.","src":["PRT 10 Apr 2026 S1"]},{"id":"q4194","q":"When was the last time (as of August 2021) that a bill was passed successfully at a joint session of the Indian Parliament?","o":["The Jammu and Kashmir Reorganisation Bill, 2019","Prevention of Terrorism Act, 2002","Banking Service Commission Act (repeal), 1978","Dowry Prohibition Act, 1961"],"a":1,"x":"The last bill passed at a joint sitting of Parliament was the Prevention of Terrorism Bill, 2002.","e":"Joint sittings: Dowry Prohibition 1961, Banking Service Commission (Repeal) 1978, POTA 2002.","src":["Nursery Teacher 23 Oct 2021 S1"]},{"id":"q4516","q":"By which amendment was the process of election of the Vice President changed to an electoral college from joint meeting of Houses?","o":["7th Amendment","11th Amendment","15th Amendment","24th Amendment"],"a":1,"x":"The 11th Amendment (1961) made the Vice-President elected by an electoral college of both Houses instead of a joint meeting.","e":"","src":["Nursery Teacher 24 Oct 2021 S3"]},{"id":"q1414","q":"With reference to the constitutional provisions regarding Rajya Sabha, which of the following statements is correct?","o":["The Attorney General of India is the ex-officio chairman of the Rajya Sabha.","The Prime Minister of India is the ex-officio chairman of the Rajya Sabha.","The Vice-President of India is the ex-officio chairman of the Rajya Sabha.","The President of India is the ex-officio chairman of the Rajya Sabha."],"a":2,"x":"The Vice-President of India is the ex-officio Chairman of the Rajya Sabha (Article 64).","e":"The Vice-President is elected by an electoral college of members of both Houses.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1481","q":"Which Article of the Indian Constitution empowers the Vice President to act as President or discharge his functions during casual vacancies in the office or in the absence of the President?","o":["Article 72","Article 61","Article 65","Article 52"],"a":2,"x":"Article 65 lets the Vice President act as President when the office falls vacant (until a new election, within six months) or when the President is absent or ill.","e":"If both are vacant, the Chief Justice of India acts as President.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1500","q":"The impeachment charges on the President of India can be initiated in either House of Parliament. These charges should be signed by ___________ of members of that particular House.","o":["one-third","one-fourth","one-sixth","one-tenth"],"a":1,"x":"Impeachment charges against the President must be signed by at least one-fourth of the members of the House where they start, after 14 days' notice (Article 61).","e":"The charge must then be passed by a two-thirds majority of the total membership of each House.","src":["TGT 29 Aug 2025"]},{"id":"q1503","q":"Which of the following statements is/are correct regarding the executive powers of the Union vested in the President of India? 1. Article 53 deals with the executive powers of the President of India. 2. Article 75 requires the Prime Minister to communicate to the President regarding all decisions of the Union Council of Ministers. 3. Article 77 holds that all executive powers of the Union government shall be exercised in the name of the President.","o":["Only 1 and 3","1, 2 and 3","Only 1 and 2","Only 2 and 3"],"a":0,"x":"Statements 1 and 3 are correct: Article 53 vests executive power in the President, and Article 77 requires executive action in the President's name. The PM's duty to inform the President is in Article 78, not 75.","e":"Article 75 deals with the appointment of the PM and ministers.","src":["TGT 29 Aug 2025"]},{"id":"q1700","q":"The real executive power is vested in:","o":["Governor of the State","Union Minister","Council of Ministers headed by Prime Minister","Supreme Court"],"a":2,"x":"Real executive power lies with the Council of Ministers headed by the Prime Minister; the President is the nominal head.","e":"","src":["TGT 10 Sep 2021 S2"]},{"id":"q2190","q":"How many Veto Powers does the President of India have?","o":["Three","Five","Two","One"],"a":0,"x":"The President has three veto powers: absolute, suspensive and pocket veto.","e":"","src":["TGT 13 Sep 2021 S1"]},{"id":"q2338","q":"Which article of Indian constitution is related with manner of election of President?","o":["Article 63","Article 49","Article 55","Article 59"],"a":2,"x":"Article 55 describes the manner of election of the President.","e":"","src":["TGT 14 Sep 2021 S1"]},{"id":"q4743","q":"______ represents the budget of the central government in the Lok Sabha.","o":["Defence minister","Home Minister","Finance minister","External Minister"],"a":2,"x":"The Union Finance Minister presents the central budget in the Lok Sabha.","e":"","src":["TGT 25 Sep 2021 S2"]},{"id":"q5198","q":"Who was The first Women External Affair Minister of India?","o":["Mrs Indira Gandhi","Mrs Pratibha Patil","Mrs Sonia Gandhi","Mrs Jayalalitha"],"a":0,"x":"Indira Gandhi was India's first woman External Affairs Minister (holding the portfolio herself, 1967–69).","e":"","src":["TGT 27 Sep 2021 S1"]},{"id":"q5507","q":"Twelve members are nominated in the Rajya Sabha by whom?","o":["Prime Minister","Union Minister","Speaker of the Lok Sabha","President"],"a":3,"x":"The President nominates 12 members to the Rajya Sabha for their knowledge of literature, science, art and social service.","e":"","src":["TGT 2 Sep 2021 S1"]},{"id":"q5532","q":"What is the minimum age limit to be a Lok Sabha candidate?","o":["25 years","45 years","30 years","35 years"],"a":0,"x":"The minimum age to contest a Lok Sabha election is 25 years (30 for the Rajya Sabha).","e":"","src":["TGT 2 Sep 2021 S2"]},{"id":"q5891","q":"According to the constitution of India, which pair of Article – Provision is correct? I. Article 54 – Election of President II. Article 17 – Abolition of Untouchability","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 54 covers election of the President and Article 17 abolishes untouchability, so both pairs are correct.","e":"","src":["TGT 6 Sep 2021 S2"]},{"id":"q5962","q":"On January 26, 1950, the Constitution was came into force and Dr. Rajendra Prasad was elected the ______.","o":["First Vice President of India","First Home minister of India","First President of India","First foreign minister of India"],"a":2,"x":"When the Constitution came into force on 26 January 1950, Dr Rajendra Prasad became the first President of India.","e":"","src":["TGT 7 Sep 2021 S3"]},{"id":"q7969","q":"The final discussion on the motion that the Bill or the Bill, as amended, be passed in Lok Sabha is done in which reading?","o":["First Reading","Second Reading","Third Reading","Fourth Reading"],"a":2,"x":"The final discussion on passing a bill in the Lok Sabha takes place at the third reading.","e":"","src":["TGT 6 Jul 2023 S2"]},{"id":"q7970","q":"Which of the following statements about Money Bill is correct? 1- Money Bills can be introduced only in Lok Sabha. 2. Rajya Sabha cannot make amendments in a Money Bill passed by Lok Sabha and transmitted to it. 3. Rajya Sabha can recommend amendments in a Money Bill. 4.Rajya Sabha must return all Money Bills to Lok Sabha within fifteen days from the date of their receipt.","o":["1 and 2 only","2 and 3 only","1, 2 and 3 only","1, 3 and 4 only"],"a":2,"x":"Money Bills start only in the Lok Sabha; the Rajya Sabha cannot amend but may recommend changes, and must return them within 14 days, not 15.","e":"","src":["TGT 6 Jul 2023 S2"]},{"id":"q7608","q":"Who among the following was the first Home Minister of India?","o":["Sardar Vallabhbhai Patel","Jawaharlal Nehru","Rajendra Prasad","Bhimrao Ramji Ambedkar"],"a":0,"x":"Sardar Vallabhbhai Patel was India's first Home Minister.","e":"","src":["Special Educator 8 Aug 2021 S2"]},{"id":"q8794","q":"Who was appointed as Prime Minister by the President using personal discretion after the sudden death of the sitting PM in 1984?","o":["Charan Singh","Rajiv Gandhi","AB Vajpayee","VP Singh"],"a":1,"x":"After Indira Gandhi's assassination in 1984, President Zail Singh used his discretion to appoint Rajiv Gandhi as Prime Minister.","e":"","src":["Special Educator 24 Jun 2025 S3"]},{"id":"q8825","q":"Members of the Rajya Sabha are elected by the:","o":["General public","Members of the Lok Sabha","Members of State Legislative Council","Elected members of State Legislative Assemblies"],"a":3,"x":"Rajya Sabha members are elected by the elected members of the State Legislative Assemblies.","e":"","src":["Special Educator 26 Jun 2025 S3"]},{"id":"q9838","q":"Which of the following statements is/are CORRECT about a Financial Bill? Statement 1: Financial Bills, other than Money Bills, are covered under Article 117. Statement 2: A Financial Bill coming under the purview of Clause (2) can be introduced only in the Lok Sabha. Statement 3: A Financial Bill coming under the purview of Clause (3) may be introduced in either House of the Parliament.","o":["Only 2","Only 1 and 2","Only 1 and 3","Only 3"],"a":2,"x":"Financial Bills are under Article 117; a Bill under clause (3) can start in either House, but clause (2) is not a Financial Bill category.","e":"","src":["Special Educator 14 Jul 2024 S1"]},{"id":"q0804","q":"The advice of the Council of Ministers is binding on the _______.","o":["President","Judiciary","Chief Justice","Speaker"],"a":0,"x":"Under Article 74(1) (as amended by the 42nd and 44th Amendments) the advice of the Council of Ministers binds the President, who may send it back once for reconsideration.","e":"In states, the Governor acts on the advice of the state Council of Ministers.","src":["PGT 22 Sep 2025"]},{"id":"q6398","q":"The feature of 'Joint Sitting of two houses of Parliament' in the Indian Constitution is borrowed from the constitution of ____________.","o":["Canada","United States of America","Australia","France"],"a":2,"x":"The joint sitting of the two Houses of Parliament was borrowed from Australia.","e":"","src":["PGT 18 Jul 2021 S1"]},{"id":"q6503","q":"The Rajya Sabha held its first meeting in _________.","o":["1952","1941","1949","1938"],"a":0,"x":"The Rajya Sabha held its first sitting in May 1952.","e":"","src":["PGT 23 Jul 2021 S1"]},{"id":"q6526","q":"Which among the following states has the highest number of representatives in the Lok Sabha?","o":["Uttar Pradesh","Maharashtra","West Bengal","Bihar"],"a":0,"x":"Uttar Pradesh sends the most members to the Lok Sabha (80).","e":"","src":["PGT 30 Jul 2021 S1"]},{"id":"q7092","q":"Article 361 of Indian constitution is related to ______.","o":["Effect of proclamation of emergency","Protection of President, Governor and Rajpramukhs","Proclamation of emergency","Power of parliament to amend the constitution"],"a":1,"x":"Article 361 protects the President and Governors (and former Rajpramukhs) from court proceedings for official acts.","e":"","src":["PGT 17 Jul 2021"]},{"id":"q7136","q":"Who is the only Chief Justice to be appointed as the Acting President of India?","o":["M. Hidayatullah","A.K. Sarkar","VV Giri","Ramnath Kovind"],"a":0,"x":"Justice M. Hidayatullah is the only Chief Justice of India to have served as acting President (1969).","e":"","src":["PGT 31 Jul 2021"]},{"id":"q7281","q":"Who can initiate the process for the removal of the Vice-President of India?","o":["House of People","Council of States","Council of Ministers","President"],"a":1,"x":"A resolution to remove the Vice-President can be moved only in the Rajya Sabha (Council of States).","e":"","src":["PGT 10 Jul 2021"]},{"id":"q7303","q":"What is the Maximum Strength of the Rajya Sabha according to the Article 80 of the Indian Constitution?","o":["545","238","245","250"],"a":3,"x":"The Rajya Sabha can have at most 250 members: 238 elected and 12 nominated.","e":"","src":["PGT 4 Jul 2021"]},{"id":"q7620","q":"Dr Zakir Hussain was the ________ president of India.","o":["Third","Fourth","Fifth","Second"],"a":0,"x":"Dr Zakir Husain was the third President of India.","e":"","src":["PGT 17 Jul 2021"]},{"id":"q7628","q":"Which of the following individuals was the second President of India?","o":["J Nehru","Dr. Rajendra Prasad","VV Giri","S. Radhakrishnan"],"a":3,"x":"Dr S. Radhakrishnan was the second President of India.","e":"","src":["PGT 17 Jul 2021"]},{"id":"q7696","q":"Who served as the acting President of India after the death of the former President Fakhruddin Ali Ahmed?","o":["BD Jatti","Shankar Dayal Sharma","Zakir Hussain","Neelam Sanjiva Reddy"],"a":0,"x":"Vice-President B.D. Jatti served as acting President after President Fakhruddin Ali Ahmed died in 1977.","e":"","src":["PGT 31 Jul 2021"]},{"id":"q7697","q":"Which of the following posts was described as \"the linchpin of Government\" by Pandit Nehru?","o":["President","Speaker","Prime Minister","Leader of Opposition"],"a":2,"x":"Nehru described the Prime Minister as the 'linchpin of Government'.","e":"","src":["PGT 31 Jul 2021"]},{"id":"q7780","q":"Which of the following Articles provides for the requirement of the President of India?","o":["61","66","52","76"],"a":2,"x":"Article 52 says there shall be a President of India.","e":"","src":["PGT 22 Jul 2021"]},{"id":"q8092","q":"Which Article of the Constitution of India expressly provides that the President is eligible for re- election?","o":["Article 56","Article 57","Article 58","Article 61"],"a":1,"x":"Article 57 says a President is eligible for re-election.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8128","q":"The Annual Financial Statement is a document presented to the Parliament every year under _________ of the Constitution of India.","o":["Article 110","Article 111","Article 112","Article 117"],"a":2,"x":"The Annual Financial Statement (budget) is presented under Article 112.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8388","q":"Which of the following Articles mentions that, “The President may, for the violation of the Constitution, be removed from the office by an impeachment in the manner provided in Article 61”?","o":["Article 53 (1)","Article 54 (a)","Article 56 (b)","Article 55 (1)"],"a":2,"x":"Article 56(1)(b) says a President may be removed for violating the Constitution by impeachment under Article 61.","e":"","src":["PGT 5 Jul 2023 S1"]},{"id":"q8418","q":"Which of the following about financial emergency is INCORRECT?","o":["The President proclaims such an emergency.","The Union government receives the right to give directions to any state to observe such canons of financial propriety.","The President may also reduce the salaries of public officials.","It is proclaimed under article 356."],"a":3,"x":"Financial emergency is proclaimed under Article 360; Article 356 is President's Rule.","e":"","src":["PGT 21 Jun 2023 S2"]},{"id":"q8473","q":"What is the minimum completed age to be elected as the President of India?","o":["25 years","30 years","35 years","40 years"],"a":2,"x":"A candidate for President must have completed 35 years of age.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q9876","q":"The President of India can promulgate ordinances during Parliament recess under which Article of the Constitution?","o":["Article 121","Article 129","Article 132","Article 123"],"a":3,"x":"The President issues ordinances when Parliament is not in session, under Article 123.","e":"","src":["PGT 25 Sep 2025"]},{"id":"q10018","q":"Which of these parties was formed in 1984 under the leadership of Kanshi Ram?","o":["Bahujan Samaj Party (BSP)","Nationalist Congress Party (NCP)","All India Trinamool Congress (AITC)","Communist Party of India (CPI)"],"a":0,"x":"Kanshi Ram founded the Bahujan Samaj Party in 1984.","e":"","src":["Junior Engineer (Civil) or Section Officer (Civil) 27 Jun 2022 S3"]},{"id":"q1926","q":"Which of the following articles of the Indian Constitution provides that the business in Parliament should be transacted in Hindi or in English?","o":["116","118","120","122"],"a":2,"x":"Article 120 says business in Parliament shall be transacted in Hindi or English.","e":"","src":["Scientific Assistant (Ballistics) 11 Sep 2021 S3"]},{"id":"q2241","q":"Which political party was the second largest party in terms of seats won in the first general election of India held in 1951-52?","o":["Socialist Party","Communist Party of India","Bharatiya Jana Sangh","Indian National Lok Dal"],"a":1,"x":"The Communist Party of India came second in seats in the 1951-52 general election.","e":"","src":["Laboratory Assistant (Lie Detection) 13 Sep 2021 S1"]},{"id":"q2263","q":"Which of the following statement is CORRECT regarding the Indian constitution? I. Constitution of India came into force on 26 January 1949. II. Article 74(1) of the Indian constitution provides that there shall be a council of Ministers with Prime Minister as its head to aid and advice the president.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"The Constitution came into force on 26 January 1950, not 1949; Article 74(1) provides the Council of Ministers headed by the PM.","e":"","src":["Senior Scientific Assistant (Ballistics) 13 Sep 2021 S2"]},{"id":"q2802","q":"The first ever no-confidence motion against the Central Government was moved in which of the following year?","o":["1967","1975","1962","1963"],"a":3,"x":"The first no-confidence motion, moved by Acharya Kripalani against Nehru's government, was in 1963.","e":"","src":["Inspecting Officer 16 Oct 2021 S1"]},{"id":"q2954","q":"Who among the following is the first prime minister of India who resigned from office?","o":["Indira Gandhi","Gulzarilal Nanda","Morarji Desai","Lal Bahadur Shastri"],"a":2,"x":"Morarji Desai (1979) was the first Prime Minister to resign from office.","e":"","src":["Technical Assistant (Intrumentation & Control) 17 Nov 2021 S3"]},{"id":"q3074","q":"Who was appointed as the first and the only Indian Governor- general of India in 1948?","o":["C. Rajagopalchari","Sarvepalli Radhakrishnan","B.R. Ambedkar","Rajendra Prasad"],"a":0,"x":"C. Rajagopalachari (1948) was the first and only Indian Governor-General of India.","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q3075","q":"How many seats were won by Congress during the 16th Lok Sabha Elections in 2014?","o":["44","48","40","84"],"a":0,"x":"Congress won 44 seats in the 2014 Lok Sabha election.","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q3107","q":"The Aam Aadmi Party was formed in the year ______.","o":["2010","2011","2012","2013"],"a":2,"x":"The Aam Aadmi Party was formed in 2012.","e":"","src":["Legal Assistant 17 Oct 2021 S2"]},{"id":"q3724","q":"The party symbol of the All India Majlis-E-Ittehadul Muslimeen is ______.","o":["Dao","Kite","two leaves","Scales"],"a":1,"x":"The AIMIM's election symbol is the kite.","e":"","src":["Technical Assistant (Modern Office Practice) English 21 Oct 2021 S2"]},{"id":"q3739","q":"Indian political system provides for","o":["Multi-Party System","Single Party System","Two Party System","Zero Party System"],"a":0,"x":"India has a multi-party system.","e":"","src":["Technical Assistant (Modern Office Practice) English 21 Oct 2021 S2"]},{"id":"q4134","q":"In which year was the Rashtriya Janta Dal (RJD) formed?","o":["1997","1996","1999","1998"],"a":0,"x":"The Rashtriya Janata Dal was formed in 1997.","e":"","src":["Manager (Public Relations) 23 Oct 2021 S2"]},{"id":"q4264","q":"Which of the following Articles of the Constitution of India focuses on the Vice President of India?","o":["Article 72","Article 52","Article 123","Article 63"],"a":3,"x":"Article 63 says there shall be a Vice-President of India.","e":"","src":["Workshop Instructor 24 Nov 2021 S1"]},{"id":"q4680","q":"Who was the prime minister of India when the emergency was imposed in India on 25 June1975?","o":["Lal Bahadur Shastri","Rajiv Gandhi","Indira Gandhi","Jawaharlal Nehru"],"a":2,"x":"Indira Gandhi was Prime Minister when the Emergency was declared on 25 June 1975.","e":"","src":["Scientific Assistant (biology) 25 Nov 2021 S1"]},{"id":"q4684","q":"Who heads the Cabinet Committee on Economic Affairs in India?","o":["Finance Minister","Prime Minister","Minister for Commerce","Cabinet Secretary"],"a":1,"x":"The Prime Minister heads the Cabinet Committee on Economic Affairs.","e":"","src":["Scientific Assistant (biology) 25 Nov 2021 S1"]},{"id":"q4727","q":"Who was the Labour Minister of India in the first cabinet after Independence ?","o":["Mohan Lal Saxena","John Mathai","Jagjivan Ram","Amrit Kaur"],"a":2,"x":"Jagjivan Ram was Labour Minister in independent India's first cabinet.","e":"","src":["Laboratory Assistant (HRD Quality Control) 25 Sep 2021 S1"]},{"id":"q4731","q":"How many Lok Sabha Seats were there in the first general election in India?","o":["489","540","543","500"],"a":0,"x":"The first general election (1951-52) was held for 489 Lok Sabha seats.","e":"","src":["Laboratory Assistant (HRD Quality Control) 25 Sep 2021 S1"]},{"id":"q4838","q":"Who among the following is referred to as the nominal executive of India?","o":["Vice President","Chief Justice","President","Prime Minister"],"a":2,"x":"The President is India's nominal (constitutional) executive; the PM-led Council of Ministers is the real executive.","e":"","src":["Technical Assistant (Architecture) 26 Jul 2021"]},{"id":"q5299","q":"31st Constitutional Amendment increased the number of Lok Sabha seats from ______ to 545.","o":["525","520","532","535"],"a":0,"x":"The 31st Amendment (1973) raised the Lok Sabha's maximum strength from 525 to 545.","e":"","src":["Assistant Engineer (Civil) 27 Sep 2021 S3"]},{"id":"q5330","q":"Lal Bahadur Shashtri passed away (died) in which year?","o":["1966","1967","1968","1969"],"a":0,"x":"Lal Bahadur Shastri died in Tashkent in 1966.","e":"","src":["Laboratory Assistant (Biology) 28 Aug 2021"]},{"id":"q5634","q":"As per Indian Prime ministers and their year of tenure, which one of the following pairs is INCORRECT?","o":["Jawaharlal Nehru- August 15, 1947 - May 27, 1964","Lal Bahadur Shastri- May 27, 1964 - June 9, 1964","Indira Gandhi - January 24, 1966 - March 24, 1977","Morarji Desai- March 24, 1977 - July 28, 1979"],"a":1,"x":"Lal Bahadur Shastri was PM from June 1964 to January 1966, not for two weeks.","e":"","src":["Labour Welfare Inspector 30 Nov 2021 S2"]},{"id":"q5664","q":"As per the Constitution of India who among the following has all executive power vested in him and all executive actions are taken in his name?","o":["President","Prime Minister","Chief Justice of India","Chief Election Commissioner of India"],"a":0,"x":"Under Article 53 the executive power of the Union is vested in the President, and all executive action is taken in his name (Article 77).","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q5808","q":"India's first general election for the Lok Sabha was conducted in __________.","o":["1962-63","1958-59","1951-52","1955-56"],"a":2,"x":"India's first Lok Sabha election was held in 1951-52.","e":"","src":["Technical Assistant (Electrical) 5 Sep 2021 S2"]},{"id":"q6060","q":"C. Rajagopalachari founded the Swatantra Party in _________ after breaking away from the Congress.","o":["1951","1959","1962","1968"],"a":1,"x":"C. Rajagopalachari founded the Swatantra Party in 1959.","e":"","src":["Technical Assistant (Mechanical) 8 Sep 2021 S3"]},{"id":"q6065","q":"104th Constitutional Amendment extended the reservation of seats for scheduled caste and scheduled tribe in the Lok Sabha and states assemblies from 70 years to ____________.","o":["78 years","75 years","80 years","85 years"],"a":2,"x":"The 104th Amendment (2019) extended SC/ST seat reservation in Lok Sabha and assemblies from 70 to 80 years.","e":"","src":["Technical Assistant (Mechanical) 8 Sep 2021 S3"]},{"id":"q6286","q":"The ‘two bullocks with plough’ was the original symbol of which of the following political parties of India?","o":["Janata Party","Congress Party","Communist Party of India","Revolutionary Socialist Party"],"a":1,"x":"'Two bullocks with a yoke' was the Congress party's original election symbol.","e":"","src":["Section Officer (Horticulture) 9 Oct 2021 S1"]},{"id":"q6419","q":"The minimum age for election to the post of Vice-President of India is ______________.","o":["30 years","35 years","25 years","28 years"],"a":1,"x":"A candidate for Vice-President must be at least 35.","e":"","src":["Technical Assistant (Commercial Art) 14 Aug 2021 S2"]},{"id":"q6539","q":"Who among the following was famous as 'Loknayak'?","o":["Purushottam Das Tandon","Lala Lajpat Rai","Vallabhbhai Patel","Jayaprakash Narayan"],"a":3,"x":"Jayaprakash Narayan was called 'Loknayak'.","e":"","src":["Technical Assistant (Garments Fabrication Technology) 2 Aug 2021"]},{"id":"q7043","q":"Who among the following was the first Law Minister of India?","o":["Rajendra Prasad","Bhimrao Ramji Ambedkar","Sardar Vallabhbhai Patel","Jawaharlal Nehru"],"a":1,"x":"B.R. Ambedkar was independent India's first Law Minister.","e":"","src":["Technical Assistant (Medical Lab Technology) 1 Aug 2021"]},{"id":"q7432","q":"Article ______ of the Indian Constitution deals with the election of the Vice-president.","o":["49","58","62","66"],"a":3,"x":"Article 66 deals with the election of the Vice-President.","e":"","src":["Technical Assistant (Fashion Design) 14 Aug 2021"]},{"id":"q7453","q":"The total number of ministers, including the Prime Minister, in the Council of Ministers shall not exceed ________ of the total strength of the Lok Sabha.","o":["13%","21%","15%","24%"],"a":2,"x":"The Council of Ministers, including the PM, cannot exceed 15% of the Lok Sabha's strength (91st Amendment).","e":"","src":["Technical Assistant (Library Science) 7 Aug 2021"]},{"id":"q8582","q":"Which of the following statements about Rajya Sabha is INCORRECT?","o":["The Rajya Sabha cannot initiate, reject or amend money bills.","The Council of Ministers is responsible for Lok Sabha and not Rajya Sabha.","Rajya Sabha can criticise the government but cannot remove it.","A no-confidence motion can be moved by any member of the Rajya House."],"a":3,"x":"A no-confidence motion can be moved only in the Lok Sabha, not the Rajya Sabha.","e":"","src":["Shift Incharge 25 Jun 2023 S2"]},{"id":"q8583","q":"Under the anti-defection amendment, who has the final authority to decide if a member of a House has become subject to disqualification under this law?","o":["Presiding officer of the House","Prime Minister of India","The President of India","Chief Election Commissioner of India"],"a":0,"x":"Under the anti-defection law, the presiding officer of the House decides disqualification.","e":"","src":["Shift Incharge 25 Jun 2023 S2"]},{"id":"q8584","q":"Which of the following statements regarding 'collective responsibility' of the Indian Executive is true. 1-The Council of Ministers is collectively responsible for the Lok and Rajya Sabha. 2-It implies that a vote of no confidence even against a single minister leads to the resignation of the entire Council of Ministers. 3-It also indicates that if a minister does not agree with a policy or decision of the cabinet, he or she must either accept the decision or resign.","o":["Only 1","Only 1 and 2","Only 2","Only 2 and 3"],"a":3,"x":"Collective responsibility is to the Lok Sabha only; a no-confidence vote against one minister topples all, and a dissenting minister must accept or resign.","e":"","src":["Shift Incharge 25 Jun 2023 S2"]},{"id":"q8727","q":"Which of the following Articles of the Constitution mentions that “the Vice-President shall be ex officio Chairman of the Council of the States and shall NOT hold any other office of profit”?","o":["61","64","66","68"],"a":1,"x":"Article 64: the Vice-President is ex officio Chairman of the Rajya Sabha and holds no other office of profit.","e":"","src":["Tailor Master 25 Jun 2023 S3"]}]},{"id":"judiciary","n":"Judiciary","qs":[{"id":"q0070","q":"Which was the fourth High Court to be established in India after Calcutta, Bombay and Madras?","o":["Delhi","Patna","Allahabad","Punjab"],"a":2,"x":"After Calcutta, Bombay and Madras (1862), the Allahabad High Court was set up in 1866 (first at Agra), making it the fourth.","e":"Its principal seat moved from Agra to Allahabad in 1869.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0103","q":"Match the Union Territories with their judiciaries: a. Andaman and Nicobar Islands, b. Daman and Diu, c. Lakshadweep, d. Puducherry — with i. Bombay High Court, ii. Calcutta High Court, iii. Madras High Court, iv. Kerala High Court.","o":["a-iv; b-i; c-iii; d-ii","a-i; b-ii; c-iii; d-iv","a-ii; b-i; c-iv; d-iii","a-iii; b-iv; c-ii; d-i"],"a":2,"x":"Andaman and Nicobar → Calcutta High Court; Daman and Diu → Bombay High Court; Lakshadweep → Kerala High Court; Puducherry → Madras High Court.","e":"Delhi is the only UT with its own High Court (1966); Jammu and Kashmir and Ladakh share one.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0111","q":"According to the Constitution of India, which Article specifies the provision for the establishment of a High Court in each state?","o":["Article 214","Article 231","Article 125","Article 212"],"a":0,"x":"Article 214 says there shall be a High Court for each state; Article 231 lets Parliament set up one common High Court for two or more states.","e":"Oldest High Court: Calcutta (1862).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0342","q":"Which of the following has the original jurisdiction to settle disputes between the Union and the States?","o":["Supreme Court","High Court","Lok Sabha","Parliament"],"a":0,"x":"Under Article 131 the Supreme Court has original (and exclusive) jurisdiction over disputes between the Union and states, or between states.","e":"Article 32 (writs for Fundamental Rights) is also original jurisdiction.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0351","q":"Article 241 in Part VIII of the Indian Constitution deals with _____.","o":["the administration of Union Territories","capitals of Union Territories","the High Courts for Union Territories","special provisions with respect to Delhi"],"a":2,"x":"Article 241 lets Parliament set up a High Court for a Union Territory or declare a court to be its High Court.","e":"Delhi got its own High Court in 1966.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0385","q":"Which of the given Articles underlines the composition of the Supreme Court in India?","o":["Article 110","Article 124","Article 150","Article 324"],"a":1,"x":"Article 124 sets up the Supreme Court and its composition: the Chief Justice of India and other judges fixed by Parliament (now up to 34 in total).","e":"SC judges retire at 65; High Court judges at 62.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0476","q":"Which of the following High Courts has its jurisdiction over more than one state or union territory?","o":["Allahabad","Delhi","Patna","Bombay"],"a":3,"x":"The Bombay High Court covers Maharashtra, Goa, and Dadra and Nagar Haveli and Daman and Diu.","e":"The Guwahati High Court covers Assam, Nagaland, Mizoram and Arunachal Pradesh.","src":["ASO 27 Aug 2025 S1"]},{"id":"q2132","q":"Which of the following writ is mentioned in the Indian constitution? I. Habeas Corpus II. Prohibition","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Constitution provides five writs: habeas corpus, mandamus, prohibition, certiorari and quo warranto (Articles 32 and 226).","e":"Habeas corpus: 'produce the body'.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2134","q":"Which of the following statement regarding Supreme court is correct? I. Article 124 of the Indian constitution deals with Establishment and Constitution of Supreme court. II. Article 125 of the Indian constitution deals with salaries of Judges.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 124 establishes and constitutes the Supreme Court and Article 125 deals with judges' salaries, so both are correct.","e":"Article 124(4): removal of judges.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2419","q":"On which date was the Supreme Court of India established?","o":["January 26th, 1950","January 29th, 1950","January 30th, 1950","January 31st, 1950"],"a":0,"x":"The Supreme Court of India came into existence on 26 January 1950, when the Constitution came into force, replacing the Federal Court.","e":"First Chief Justice: H.J. Kania.","src":["Junior Clerk 15 Nov 2021 S1"],"k":"The Court was formally inaugurated two days later, on 28 January 1950; DSSSB's key uses 26 January, when it came into existence."},{"id":"q2464","q":"Which of the following articles of the Indian Constitution empowers the Supreme Court for original jurisdiction to deal with any dispute between the Centre and a state?","o":["Article 125","Article 131","Article 138","Article 141"],"a":1,"x":"Article 131 gives the Supreme Court original jurisdiction over disputes between the Centre and states, or between states.","e":"Article 32: writs; 136: special leave petitions.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2619","q":"Which article of the Indian Constitution deals with conferment on the supreme court of powers to issue certain writs?","o":["135","138","139","136"],"a":2,"x":"Article 139 allows Parliament to give the Supreme Court power to issue writs for purposes other than enforcing fundamental rights.","e":"Article 32: writs for fundamental rights.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2690","q":"Which article of the Indian Constitution deals with appointment of Ad hoc judges?","o":["126","123","127","125"],"a":2,"x":"Article 127 lets the Chief Justice of India appoint ad hoc judges to the Supreme Court when there is no quorum.","e":"Article 128: retired judges at sittings.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q2889","q":"Which article of the Indian Constitution deals with rules of court?","o":["140","145","143","142"],"a":1,"x":"Article 145 lets the Supreme Court make rules regulating its practice and procedure.","e":"Article 143: advisory jurisdiction.","src":["Junior Clerk 17 Nov 2021 S1"]},{"id":"q1323","q":"Which of the following constitutional amendment had replaced the Collegium System of appointing judges to the Supreme Court and High Courts with the National Judicial Appointments Commission (NJAC)?","o":["97th","98th","96th","99th"],"a":3,"x":"The 99th Amendment (2014) created the National Judicial Appointments Commission to replace the collegium; the Supreme Court struck it down in 2015.","e":"The collegium system remains in force.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1325","q":"In which of the following countries did the concept of Public Interest Litigation originate?","o":["USA","Ireland","Russia","Canada"],"a":0,"x":"Public Interest Litigation began in the USA in the 1960s; in India, Justices P. N. Bhagwati and V. R. Krishna Iyer pioneered it in the late 1970s and 1980s.","e":"Hussainara Khatoon (1979) is often cited as India's first PIL.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q5187","q":"Which of the following Constitutional Amendment Act of the Constitution of India was declared null and void by the Supreme Court?","o":["26th Constitutional Amendment Act","73rd Constitutional Amendment Act","74th Constitutional Amendment Act","99th Constitutional Amendment Act"],"a":3,"x":"The 99th Amendment (2014), which created the National Judicial Appointments Commission, was struck down by the Supreme Court in 2015.","e":"","src":["Personal Assistant 27 Nov 2021 S1"]},{"id":"q5412","q":"In which year did the Supreme Court of India first recognize transgender people as a third gender?","o":["2012","2013","2014","2015"],"a":2,"x":"In NALSA v. Union of India (2014) the Supreme Court recognised transgender people as a third gender.","e":"","src":["Personal Assistant 29 Nov 2021 S2"]},{"id":"q5449","q":"What is the name given to the benches of the Supreme Court of India which consists of at least five judges of the court?","o":["Legal bench","Regional bench","Constitution bench","Division bench"],"a":2,"x":"A bench of at least five Supreme Court judges hearing questions of constitutional interpretation is a Constitution Bench (Article 145(3)).","e":"","src":["Personal Assistant 29 Nov 2021 S2"]},{"id":"q10101","q":"A motion containing the charges against the judge must be approved by ______ in both Houses of the Parliament of India.","o":["absolute majority","simple majority","effective majority","special majority"],"a":3,"x":"A motion to remove a judge must be passed by a special majority in each House of Parliament.","e":"","src":["Assistant Superintendent 20 Jul 2024 S2"]},{"id":"q9497","q":"Which of the following means cases that can be directly considered by the Supreme Court without going to the lower courts before that?","o":["Advisory Jurisdiction","Writ Jurisdiction","Original Jurisdiction","Appellate Jurisdiction"],"a":2,"x":"Cases the Supreme Court hears directly, without going through lower courts, fall under its original jurisdiction (Article 131).","e":"","src":["Assistant Superintendent 14 Jul 2024 S1"]},{"id":"q8884","q":"In the Indian judicial system, the Supreme Court is called a Court of Record because:","o":["Its rulings are advisory and not binding on states","Its proceedings are recorded as legal testimony and precedents","It maintains official documents of the Union Parliament","It preserves old laws and statutes for future reference"],"a":1,"x":"The Supreme Court is a court of record (Article 129): its judgments are recorded as evidence and precedent, and it can punish for contempt.","e":"","src":["MTS 2 Mar 2026 S3"]},{"id":"q8964","q":"Which of the following articles of the Indian Constitution govern the organisation, jurisdiction, and powers of the Supreme Court of India?","o":["Articles 124 to 147","Articles 100 to 120","Articles 214 to 231","Articles 1 to 50"],"a":0,"x":"Articles 124 to 147 deal with the organisation, jurisdiction and powers of the Supreme Court.","e":"","src":["MTS 3 Mar 2026 S2"]},{"id":"q8970","q":"Which Article of the Indian Constitution provides the Supreme Court with the power of advisory jurisdiction?","o":["Article 143","Article 136","Article 124","Article 141"],"a":0,"x":"Article 143 gives the Supreme Court advisory jurisdiction: the President may seek its opinion.","e":"","src":["MTS 3 Mar 2026 S2"]},{"id":"q8974","q":"A motion for removal may be introduced in either House of Parliament and must be supported by at least 100 members of the Lok Sabha or 50 members of the Rajya Sabha before it is taken up. This removal procedure applies to which constitutional body of India?","o":["Election Commission of India","Comptroller and Auditor General of India","Union Public Service Commission","Supreme Court and High Courts Judges"],"a":3,"x":"A motion to remove a Supreme Court or High Court judge needs the signatures of 100 Lok Sabha or 50 Rajya Sabha members to be taken up.","e":"","src":["MTS 3 Mar 2026 S2"]},{"id":"q9035","q":"In which Supreme Court case was Section 66A of the Information Technology Act struck down for being vague and violative of freedom of speech and expression?","o":["A.K. Gopalan v. State of Madras","Maneka Gandhi v. Union of India","K.S. Puttaswamy v. Union of India","Shreya Singhal v. Union of India"],"a":3,"x":"In Shreya Singhal v. Union of India (2015) the Supreme Court struck down Section 66A of the IT Act.","e":"","src":["MTS 5 Mar 2026 S2"]},{"id":"q9044","q":"On which grounds can a judge of the Supreme Court of India be removed from office?","o":["He can be removed only on grounds of corruption and financial mismanagement.","He can be removed only on grounds of negligence and violation of official duties.","He can be removed only on grounds of misbehaviour or incapacity to hold office.","He can be removed only on grounds of political bias and conflict of interest."],"a":2,"x":"A Supreme Court judge can be removed only for proved misbehaviour or incapacity (Article 124(4)).","e":"","src":["MTS 5 Mar 2026 S2"]},{"id":"q9088","q":"Under which Article of the Constitution of India can High Court judges be appointed as ad hoc judges of the Supreme Court?","o":["Article 126 of the Constitution of India","Article 125 of the Constitution of India","Article 128 of the Constitution of India","Article 127 of the Constitution of India"],"a":3,"x":"Under Article 127, High Court judges can be appointed as ad hoc judges of the Supreme Court.","e":"","src":["MTS 6 Mar 2026 S1"]},{"id":"q9230","q":"Which article of the Indian constitution allows High Courts to have control over the subordinate courts?","o":["Article 225","Article 228","Article 235","Article 224"],"a":2,"x":"Article 235 gives High Courts control over subordinate courts.","e":"","src":["MTS 8 Mar 2026 S2"]},{"id":"q9397","q":"In which landmark Supreme Court case was it held that any procedure restricting the right to life and personal liberty must be fair, just, and reasonable, and not arbitrary or oppressive?","o":["Maneka Gandhi v. Union of India","ADM Jabalpur v. Shivkant Shukla","A.K. Gopalan v. State of Madras","Kesavananda Bharati v. State of Kerala"],"a":0,"x":"In Maneka Gandhi v. Union of India (1978) the Supreme Court held that procedure under Article 21 must be fair, just and reasonable.","e":"","src":["MTS 25 Feb 2026 S3"]},{"id":"q9403","q":"In 2001, which institution directed the Government of India to provide \"cooked\" mid-day meals instead of just distributing food grains?","o":["The Ministry of Education","The NITI Aayog","The Supreme Court of India","The Parliament of India"],"a":2,"x":"In 2001 the Supreme Court directed governments to serve cooked mid-day meals in schools.","e":"","src":["MTS 26 Feb 2026 S2"]},{"id":"q2998","q":"On which day was the Supreme Court of India inaugurated?","o":["January 26th, 1949","January 28th, 1949","January 26th, 1950","January 28th, 1950"],"a":3,"x":"The Supreme Court of India was formally inaugurated on 28 January 1950, two days after the Constitution came into force.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 17 Nov 2021 S3"]},{"id":"q3232","q":"Which of the following writs is issued when the court finds that a particular office holder is not doing legal duty and thereby is infringing on the right of an individual?","o":["Certiorari","Habeas Corpus","Quo Warranto","Mandamus"],"a":3,"x":"Mandamus ('we command') orders a public official to perform a legal duty they have failed to do.","e":"Quo warranto: 'by what authority'; certiorari: quash a lower court's order.","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S2"]},{"id":"q3276","q":"Which of the following writs means that the court orders that the arrested person should be presented before it?","o":["Mandamus","Quo Warranto","Habeas Corpus","Certiorari"],"a":2,"x":"Habeas corpus ('to have the body') orders a detained person to be produced before the court so it can test whether the detention is legal.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S3"]},{"id":"q4566","q":"The feature of Judicial Review in the Indian constitution was inspired by the constitution of which country?","o":["United Kingdom","United States of America","Ireland","France"],"a":1,"x":"Judicial review was borrowed from the Constitution of the USA.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S1"]},{"id":"q0929","q":"Under which Act have Lok Adalats been given statutory status?","o":["Legal Services Authorities Act, 1997","Legal Services Authorities Act, 1987","Legal Services Authorities Act, 2000","Legal Services Authorities Act, 1990"],"a":1,"x":"The Legal Services Authorities Act, 1987 (in force 1995) gave Lok Adalats statutory status; their awards are final and binding.","e":"Article 39A (free legal aid) is the constitutional basis.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0980","q":"Which of the following CORRECTLY illustrates the long-term constitutional consequence of the Kesavananda Bharati judgment in the context of parliamentary attempts at asserting supremacy?","o":["The constitutional review exercise post-1980 successfully removed all restrictions on amending fundamental rights","The 42nd Amendment annulled the basic structure doctrine, making Parliament sovereign in all constitutional matters.","Despite the 42nd Amendment, the Supreme Court in Minerva Mills reaffirmed the basic structure doctrine, limiting constitutional amendments.","The Minerva Mills judgment overturned Kesavananda and declared the Preamble non- justiciable."],"a":2,"x":"Kesavananda Bharati (1973) created the basic structure doctrine. The 42nd Amendment tried to put amendments beyond judicial review, but Minerva Mills (1980) struck that down and reaffirmed the basic structure.","e":"Minerva Mills held that the balance between Fundamental Rights and DPSPs is itself part of the basic structure.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1046","q":"Which of the following constitutional amendments is CORRECTLY matched with its judicial implication?","o":["54th Amendment – Revised the salary structure of judges in constitutional courts","15th Amendment – Increased the number of judges in the Supreme Court","42nd Amendment – Reduced the retirement age of Supreme Court judges to 60 years","44th Amendment – Raised the retirement age of High Court judges to 65 years"],"a":0,"x":"The 54th Amendment (1986) raised the salaries of Supreme Court and High Court judges and let Parliament change them by ordinary law.","e":"The 15th Amendment (1963) raised the retirement age of High Court judges from 60 to 62.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1062","q":"Which power does the Supreme Court have regarding laws passed by the legislature?","o":["The power to veto","The power to review","The power to enforce","The power to amend"],"a":1,"x":"The Supreme Court has the power of judicial review: it can declare laws void if they break the Constitution (Articles 13, 32, 131). It cannot veto, amend or enforce laws the way the executive does.","e":"Judicial review is part of the basic structure.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1087","q":"Where was the first Lok Adalat camp held in India?","o":["Gujarat","Andhra Pradesh","Rajasthan","West Bengal"],"a":0,"x":"The first Lok Adalat camp was held in Gujarat (Junagadh) in March 1982.","e":"Lok Adalat awards are final; no appeal lies against them.","src":["PRT 23 Feb 2026 S2"]},{"id":"q1094","q":"Lok Adalats in India were given statutory status under the Legal Services Authorities Act passed in the year ________.","o":["1977","1967","1987","1997"],"a":2,"x":"Lok Adalats got statutory status under the Legal Services Authorities Act, 1987, which came into force in 1995.","e":"Article 39A (free legal aid) is the constitutional basis.","src":["PRT 23 Feb 2026 S2"]},{"id":"q1180","q":"All Lok Adalat proceedings are deemed judicial proceedings under the Bharatiya Nyaya Sanhita, passed in the year __________.","o":["2020","2016","2018","2023"],"a":3,"x":"Section 22(3) of the Legal Services Authorities Act, 1987 deems Lok Adalat proceedings to be judicial proceedings under the penal law, now the Bharatiya Nyaya Sanhita, 2023 (which replaced the IPC from 1 July 2024).","e":"An award of a Lok Adalat is final; no appeal lies against it.","src":["PRT 31 Mar 2026 S1"]},{"id":"q4237","q":"Who among the following was the first Chief Justice of India?","o":["Hon’ble Mr. Justice M. Patanjali Sastri","Hon’ble Mr. Justice Harilal Jekisundas Kania","Hon’ble Mr. Justice Mehr Chand Mahajan","Hon’ble Mr. Justice Bijan Kumar Mukherjea"],"a":1,"x":"Justice H.J. Kania was the first Chief Justice of India.","e":"","src":["Nursery Teacher 23 Oct 2021 S3"]},{"id":"q4238","q":"Who was the first Indian judge to be appointed President of the International Court of Justice?","o":["Dr Nagendra Singh","Dalveer Bhandari","B.N. Rau","R.S. Pathak"],"a":0,"x":"Dr Nagendra Singh was the first Indian President of the International Court of Justice (1985–88).","e":"","src":["Nursery Teacher 23 Oct 2021 S3"]},{"id":"q4240","q":"In which year did the Supreme Court of India deem the instant Triple Talaq system unconstitutional?","o":["2017","2016","2015","2014"],"a":0,"x":"In 2017 (Shayara Bano case) the Supreme Court held instant triple talaq unconstitutional.","e":"","src":["Nursery Teacher 23 Oct 2021 S3"]},{"id":"q4241","q":"In which of the following cases did the Supreme Court of India rule that it can amend any part of the constitution except its basic structure?","o":["Champakam Dorairajan vs. The State of Madras","Golaknath vs. The State of Punjab","S.R. Bommai vs. Union of India","Kesavnanda Bharti vs. The State of Kerala"],"a":3,"x":"In Kesavananda Bharati v. State of Kerala (1973) the Supreme Court held that Parliament cannot change the basic structure.","e":"","src":["Nursery Teacher 23 Oct 2021 S3"]},{"id":"q1507","q":"What is the minimum number of judges in a Constitution Bench of the Supreme Court of India?","o":["7","5","3","8"],"a":1,"x":"Article 145(3): cases involving a substantial question of constitutional interpretation are heard by a bench of at least five judges (a Constitution Bench).","e":"Kesavananda Bharati had 13 judges, the largest bench.","src":["TGT 24 Aug 2025 S1"]},{"id":"q5721","q":"The provision of having a common High Court for two or more States was introduced by the:","o":["Tenth Amendment Act, 1961","Second Amendment Act, 1952","Seventh Amendment Act, 1956","Thirteenth Amendment Act, 1962"],"a":2,"x":"The 7th Amendment (1956) allowed a common High Court for two or more states.","e":"","src":["TGT 4 Sep 2021 S2"]},{"id":"q9822","q":"The Family Courts Act was enacted in which of the following years?","o":["1982","1984","1981","1980"],"a":1,"x":"The Family Courts Act was enacted in 1984.","e":"","src":["TGT 23 Aug 2025 S3"]},{"id":"q8805","q":"Which Part and Articles of the Indian Constitution deal with the provisions related to High Courts?","o":["Part IV, Articles 214 to 230","Part VI, Articles 220 to 240","Part VI, Articles 214 to 231","Part V, Articles 214 to 224"],"a":2,"x":"High Courts are covered in Part VI, Articles 214 to 231.","e":"","src":["Special Educator 24 Jun 2025 S3"]},{"id":"q8838","q":"In which of the following cases is the Supreme Court obligated to render advice to the President?","o":["On a pre-constitutional treaty or agreement dispute","On the President’s discretion","On a constitutional amendment question","On any bill passed by the Parliament"],"a":0,"x":"Under Article 143(2) the Supreme Court must give its opinion on disputes over pre-Constitution treaties; under 143(1) it may decline.","e":"","src":["Special Educator 29 Jun 2025 S1"]},{"id":"q9836","q":"Which of the following statements is/are true? 1. The Chief Justice and other judges of the Supreme Court are appointed by the President of India. 2. No person who has held office of a judge of the Supreme Court is allowed to plead as an advocate in any court or before any authority within the territory of India. 3. The judges of the Supreme Court are paid such salaries as are determined by the Parliament from time to time.","o":["1, 2 and 3","Only 1 and 3","Only 1","Only 2"],"a":0,"x":"All three are true: the President appoints SC judges, retired SC judges cannot plead in any Indian court, and Parliament fixes their salaries.","e":"","src":["Special Educator 14 Jul 2024 S1"]},{"id":"q0836","q":"Which of the following statements regarding jurisdiction of Subordinate Courts in India is INCORRECT?","o":["The district judge is the highest judicial authority in the district.","There are three tiers of civil and criminal courts below the High Court.","The district judge exercises both judicial and administrative powers.","The organisational structure and jurisdiction of these courts are laid down by the Union Government and they are the same in every state."],"a":3,"x":"The incorrect statement is that subordinate courts are organised uniformly by the Union. Their structure and jurisdiction are set by state laws and vary slightly between states.","e":"The district judge is the top judicial officer of a district.","src":["PGT 26 Sep 2025"]},{"id":"q0868","q":"In which case did the Supreme Court rule that constitutional amendments can be challenged in courts?","o":["S. R. Bommai case","Minerva Mills case","Kesavananda Bharati case","Vishaka case"],"a":2,"x":"In Kesavananda Bharati (1973) the Supreme Court held that Parliament can amend the Constitution but not its basic structure, so amendments can be challenged in court.","e":"13-judge bench, 7:6 verdict.","src":["PGT 24 Sep 2025"]},{"id":"q6486","q":"Which among the following options is incorrect with respect to the feature of the Indian Constitution and the country from which it is borrowed?","o":["Republic & ideals of liberty, equality & fraternity in the Preamble - France","Joint Sitting of two houses of Parliament - Australia","Prerogative Writs - United States of America","Directive Principles of State Policy - Ireland"],"a":2,"x":"Prerogative writs were borrowed from the UK, not the USA; the other pairs are correct.","e":"","src":["PGT 30 Jul 2021 S2"]},{"id":"q6647","q":"15th Constitutional Amendment increased the retirement age of high court judges from 60 years to ___ years.","o":["65","62","68","70"],"a":1,"x":"The 15th Amendment (1963) raised the retirement age of High Court judges from 60 to 62.","e":"","src":["PGT 18 Jul 2021 S2"]},{"id":"q7113","q":"Which article of Indian constitution is related to the special leave to appeal by the supreme court?","o":["168","152","136","144"],"a":2,"x":"Article 136 empowers the Supreme Court to grant special leave to appeal.","e":"","src":["PGT 11 Jul 2021"]},{"id":"q7652","q":"Which of the following articles provides for the Supreme Court of India?","o":["123","116","143","124"],"a":3,"x":"Article 124 establishes the Supreme Court of India.","e":"","src":["PGT 29 Jul 2021"]},{"id":"q8091","q":"Under which Article of the Constitution has the Supreme Court been given ancillary powers?","o":["Article 127","Article 130","Article 134","Article 140"],"a":3,"x":"Article 140 lets Parliament confer ancillary powers on the Supreme Court.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8126","q":"In which of the following famous cases have the fundamental duties been particularly invoked in litigation concerning the environment?","o":["Moti Lal v. State of Uttar Pradesh","Varghese v. Bank of Cochin case","Rural litigation and Entitlement Kendra v. State of Uttar Pradesh","Gramophone Co. v. Birendra Case"],"a":2,"x":"Fundamental duties were invoked on the environment in Rural Litigation and Entitlement Kendra v. State of UP (Doon Valley case).","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8389","q":"__________ is a judicial philosophy that courts can and should go beyond applicable law to consider the broader societal implications of their decisions.","o":["Judicial restraint","Judicial philosophy","Judiciary review","Judicial activism"],"a":3,"x":"Judicial activism is courts going beyond strict law to consider wider social effects of their decisions.","e":"","src":["PGT 5 Jul 2023 S1"]},{"id":"q8417","q":"The administrative expenses of a High Court including all salaries, allowances and pensions payable to or in respect of the officers and servants of the court shall be charged upon:","o":["the Consolidated Fund of India","the Consolidated Fund of the State","the Public Account of India","the Reserve Bank of India"],"a":1,"x":"A High Court's administrative expenses are charged on the Consolidated Fund of the State (Article 229).","e":"","src":["PGT 21 Jun 2023 S2"]},{"id":"q8445","q":"Under which Article of the Constitution can ad-hoc judges be appointed to the Supreme Court?","o":["Article 124","Article 125","Article 127","Article 128"],"a":2,"x":"Ad hoc judges can be appointed to the Supreme Court under Article 127.","e":"","src":["PGT 22 Jun 2023 S1"]},{"id":"q8474","q":"In India, which of the following Articles of the Constitution states that each judge of the Supreme Court shall be appointed by the President after consulting the other judges of the Supreme Court and the High Courts?","o":["Article 121 and 122","Article 124","Article 125","Article 129"],"a":1,"x":"Under Article 124 the President appoints Supreme Court judges after consulting judges of the Supreme Court and High Courts.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q5066","q":"Under which of the following articles of the Constitution of India can the High Court issue writ?","o":["Article 32","Article 124","Article 216","Article 226"],"a":3,"x":"High Courts issue writs under Article 226.","e":"","src":["Scientific Assistant (Physics) 26 Sep 2021 S1"]},{"id":"q5666","q":"The Sessions Judge is the highest judicial authority in a ______.","o":["District","Nation","State","Panchayat"],"a":0,"x":"The District and Sessions Judge is the highest judicial authority in a district.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q5667","q":"What kind of a Court is the ‘Gram Kachheri’?","o":["Panchayat Court","High Court","Sessions Court","Consumer Court"],"a":0,"x":"The Gram Kachahari is a village panchayat court in Bihar for settling small disputes.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q6338","q":"Which among the following is the oldest High Court in India?","o":["Calcutta High Court","Bombay High Court","Allahabad High Court","Delhi High Court"],"a":0,"x":"The Calcutta High Court (1862) is India's oldest High Court.","e":"","src":["Technical Assistant (Beauty Culture) 26 Jul 2021"]},{"id":"q6725","q":"Nation Judicial Appointment commission was established through which constitutional amendment?","o":["99","106","91","87"],"a":0,"x":"The 99th Amendment (2014) created the National Judicial Appointments Commission, struck down in 2015.","e":"","src":["Investigator 26 Jul 2021"]},{"id":"q7365","q":"Article 323A of Indian Constitution is related to ______.","o":["proclamation of emergency","suits and proceedings","administrative tribunals","official language of the union"],"a":2,"x":"Article 323A provides for administrative tribunals.","e":"","src":["Physical Education Teacher 2 Aug 2021"]},{"id":"q7412","q":"Which article of Indian constitution is related to seat of supreme court?","o":["108","130","148","164"],"a":1,"x":"Article 130 says the Supreme Court sits in Delhi (or elsewhere as the CJI decides).","e":"","src":["Physical Education Teacher 2 Aug 2021"]},{"id":"q7431","q":"Who among the following Chief Justice served the shortest tenure?","o":["Ranganath Misra","Kamal Narain Singh","Harilal Jekisundas Kania","Bhuvaneshwar Prasad Sinha"],"a":1,"x":"Justice K.N. Singh had the shortest tenure as Chief Justice of India (17 days, 1991).","e":"","src":["Technical Assistant (Fashion Design) 14 Aug 2021"]},{"id":"q8724","q":"Which Article of the Constitution has the provision of appellate jurisdiction of the Supreme Court with regards to criminal matters?","o":["Article 134","Article 135","Article 136","Article 137"],"a":0,"x":"Article 134 covers the Supreme Court's appellate jurisdiction in criminal matters.","e":"","src":["Tailor Master 25 Jun 2023 S3"]},{"id":"q8725","q":"Who resolves disputes that may arise between two states?","o":["Supreme Court of India","High Courts of concerned States","Subordinate Court","District Court"],"a":0,"x":"Disputes between states are decided by the Supreme Court (original jurisdiction, Article 131).","e":"","src":["Tailor Master 25 Jun 2023 S3"]},{"id":"q9731","q":"Which article of the Constitution deals with transfer of a judge from one high court to another?","o":["230","215","222","220"],"a":2,"x":"Article 222 deals with transferring a judge from one High Court to another.","e":"","src":["Junior Engineer 29 Jun 2022 S2"]},{"id":"q9966","q":"The provision for the removal of Supreme Court and High Court judges in the Indian Constitution was taken from which country?","o":["Canada","Japan","United States of America","Australia"],"a":2,"x":"The procedure for removing Supreme Court and High Court judges was borrowed from the USA.","e":"","src":["Junior Engineer (Electrical) or Section Officer (Electrical) 22 Jun 2022 S3"]}]},{"id":"states","n":"States, Union Territories, Delhi and Local Bodies","qs":[{"id":"q0021","q":"_________ provides that all the seats in a municipality shall be filled by the persons selected by direct elections from territorial constituencies in the municipal area.","o":["Article 243-R","Article 253-A","Article 243-A","Article 243-G"],"a":0,"x":"Article 243R (Part IXA, added by the 74th Amendment, 1992) says all seats in a municipality are filled by direct election from territorial constituencies (wards).","e":"The panchayat equivalent is Article 243C. Part IX = Panchayats; Part IXA = Municipalities.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0022","q":"Legislative Assembly DOES NOT exist in which of the following Union Territories?","o":["Jammu and Kashmir","Puducherry","Ladakh","Delhi"],"a":2,"x":"Ladakh became a Union Territory without a legislature under the Jammu and Kashmir Reorganisation Act, 2019; Jammu and Kashmir became a UT with one.","e":"UTs with an elected assembly: Delhi, Puducherry, Jammu and Kashmir.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0080","q":"Which of the following ministries exercises the administrative control over the Cantonment Boards established under the Cantonment Act?","o":["Ministry of Defence","Ministry of Housing and Urban Affairs","Ministry of Home Affairs","Ministry of Panchayati Raj"],"a":0,"x":"Cantonment Boards run civic affairs in military cantonments and are under the Ministry of Defence, now under the Cantonments Act, 2006.","e":"India has 62 notified cantonments; the Station Commander usually heads the board.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0105","q":"The North Cachar Hills district is an autonomous district council of which state?","o":["Mizoram","Assam","Nagaland","Tripura"],"a":1,"x":"The North Cachar Hills district (now Dima Hasao) of Assam has an autonomous district council under the Sixth Schedule.","e":"Sixth Schedule states: Assam, Meghalaya, Tripura, Mizoram.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0106","q":"Administration of Union Territories is mentioned in which of the following Parts of the Constitution of India?","o":["Part-VIII","Part-II","Part-VII","Part-IX"],"a":0,"x":"Part VIII (Articles 239–242) deals with Union Territories; each UT is run by the President through an administrator.","e":"Article 239AA (69th Amendment, 1991) gives Delhi its special status as the National Capital Territory.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0157","q":"Which of the following is a Union Territory with a Legislative Assembly?","o":["Andaman and Nicobar Islands","Chandigarh","Puducherry","Lakshadweep"],"a":2,"x":"Puducherry has a Legislative Assembly (Government of Union Territories Act, 1963), as do Delhi and Jammu and Kashmir.","e":"Chandigarh, Lakshadweep, and Andaman and Nicobar have no legislature.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0158","q":"What is the significance of the President’s powers in relation to state legislation under Article 200 of the Indian Constitution?","o":["The President can pass state laws without consulting the state legislature.","The President can dissolve the state legislature unilaterally.","The President’s assent is required for all the bills passed by a state legislature.","The President can reject any bill passed by a state legislature that was referred to him by the Governor of the state."],"a":3,"x":"Under Article 200 a Governor can reserve a state bill for the President; under Article 201 the President may then assent or withhold assent.","e":"Money bills reserved for the President cannot be returned to the state legislature for reconsideration.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0183","q":"Which of the following is NOT a duty of the Chief Minister under Article 167 of the Indian Constitution?","o":["To submit proposals for international treaties to the Governor","To communicate all decisions of the Council of Ministers to the Governor","To furnish information called for by the Governor about state administration","To submit matters decided by a Minister but not considered by the Council for consideration"],"a":0,"x":"Article 167 makes the Chief Minister communicate Cabinet decisions to the Governor, give information the Governor asks for, and put a minister's decision before the whole council if asked. Proposing international treaties is not a state function.","e":"Treaties are a Union List subject (entry 14).","src":["ASO 19 Aug 2025 S3"]},{"id":"q0345","q":"Which Constitutional Article deals with Union Territories?","o":["Article 244","Article 239","Article 152","Article 220"],"a":1,"x":"Article 239 says each Union Territory is administered by the President through an administrator appointed by the President.","e":"Article 239A: legislature for Puducherry. Article 239AA: Delhi.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0360","q":"In 1956, India had 14 states and _______ Union Territories.","o":["7","9","6","8"],"a":2,"x":"The States Reorganisation Act, 1956 organised India into 14 states and 6 union territories.","e":"It took effect on 1 November 1956.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0387","q":"Articles 239 to 241 in Part VIII of the Indian Constitution deal with the _________.","o":["High Courts","Parliament","Union Territories","Supreme Court"],"a":2,"x":"Articles 239–241 in Part VIII deal with Union Territories: their administration, Delhi and Puducherry, and High Courts for UTs.","e":"Part VIII was reshaped by the 7th Amendment (1956).","src":["ASO 21 Aug 2025 S3"]},{"id":"q0393","q":"What is the minimum age requirement for an Indian citizen to be appointed as Governor of any state in India?","o":["45 years","35 years","30 years","50 years"],"a":1,"x":"Article 157: a Governor must be a citizen of India and at least 35 years old.","e":"Same minimum age as the President and Vice President.","src":["ASO 21 Aug 2025 S3"]},{"id":"q1586","q":"Which Amendment Act, 1991 of Indian Constitution accorded a special status to the Union Territory of Delhi by designating it as the National Capital Territory of Delhi?","o":["47th","69th","55th","76th"],"a":1,"x":"The 69th Amendment (1991) added Articles 239AA and 239AB, making Delhi the National Capital Territory with an elected Legislative Assembly.","e":"The Balakrishnan Committee recommended the change.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q6799","q":"The 55th Constitutional Amendment gave special powers to the Governor consequent to formation of which of the following states?","o":["Arunachal Pradesh","Sikkim","Assam","Mizoram"],"a":0,"x":"The 55th Amendment (1986) added Article 371H, giving the Governor of Arunachal Pradesh special responsibility for law and order.","e":"","src":["Junior Assistant 25 Aug 2021"]},{"id":"q1855","q":"Which of the following state legislature has two houses? I. Maharashtra II. Kerala","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Maharashtra has a bicameral legislature (Assembly and Council); Kerala has only a Legislative Assembly.","e":"Six states have Legislative Councils: UP, Bihar, Maharashtra, Karnataka, Telangana, Andhra Pradesh.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1856","q":"Through which constitutional amendment part IX was inserted in the Indian constitution?","o":["44th","86th","73rd","11th"],"a":2,"x":"Part IX (The Panchayats) was inserted by the 73rd Amendment (1992); Part IXA (Municipalities) by the 74th.","e":"73rd = panchayats; 74th = municipalities.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1967","q":"Which of the following subject(s) is/are mentioned in the Eleventh Schedule of the Indian constitution? I. Fisheries II. Family Welfare","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Eleventh Schedule (73rd Amendment) lists 29 subjects for panchayats, including fisheries and family welfare.","e":"11th: panchayats (29 subjects); 12th: municipalities (18).","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2052","q":"Which of the following article(s) is/are mentioned in sixth schedule of the Indian constitution? I. 244(2) II. 275(1)","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Sixth Schedule (administration of tribal areas in Assam, Meghalaya, Tripura and Mizoram) is referred to in Articles 244(2) and 275(1).","e":"Fifth Schedule: other scheduled areas.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2135","q":"In which year did the Seventy fourth amendment of the Indian constitution take place?","o":["1992","1998","2002","1990"],"a":0,"x":"The 74th Amendment Act (1992) added Part IXA and the Twelfth Schedule, giving municipalities constitutional status.","e":"73rd: panchayats; 74th: municipalities.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2420","q":"In which year did the Supreme Court rule that the office of governor of a state is not an employment under the Central government?","o":["In 1961","In 1965","In 1974","In 1979"],"a":3,"x":"In Hargovind Pant v. Raghukul Tilak (1979) the Supreme Court held that a Governor's office is an independent constitutional office, not employment under the Central Government.","e":"The Governor is appointed by the President (Article 155).","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2509","q":"Which of the following was the first state to establish the Panchayati Raj system in India?","o":["Tamil Nadu","Uttar Pradesh","Maharashtra","Rajasthan"],"a":3,"x":"Rajasthan was the first state to set up Panchayati Raj: PM Nehru inaugurated it at Nagaur on 2 October 1959; Andhra Pradesh followed.","e":"It followed the Balwant Rai Mehta Committee (1957).","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2549","q":"With which of the following is the P. K. Thungon Committee of 1989 related to?","o":["Basic features of the Constitution","Appointment of judges in Supreme Court","Appointment of judges in High Court","Local government"],"a":3,"x":"The P.K. Thungon Committee (1989) recommended constitutional recognition for local government (panchayats), leading to the 73rd Amendment.","e":"Other panchayat committees: Balwant Rai Mehta (1957), Ashok Mehta (1977), L.M. Singhvi (1986).","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2692","q":"Through which constitutional amendment special provisions with respect to the state of Nagaland were added in the Indian constitution?","o":["Tenth","Twelfth","Thirteenth","Eleventh"],"a":2,"x":"The 13th Amendment (1962) added Article 371A, with special provisions for Nagaland, which became a state in 1963.","e":"371A Nagaland, 371B Assam, 371C Manipur.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1312","q":"In which year was the Fazl Ali Commission appointed?","o":["1952","1953","1954","1951"],"a":1,"x":"The States Reorganisation Commission, chaired by Fazl Ali with K. M. Panikkar and H. N. Kunzru, was appointed in December 1953; its report led to the States Reorganisation Act, 1956.","e":"The Dhar Commission (1948) and JVP Committee (1948–49) came earlier.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q4066","q":"Which among the following Constitutional Amendments led to the formation of the state of Nagaland?","o":["13th","8th","15th","17th"],"a":0,"x":"The 13th Amendment (1962) added Article 371A and made Nagaland a state (inaugurated 1963).","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q4067","q":"The 83rd Constitutional Amendment exempted _______________ from reservation for Scheduled Castes in Panchayati Raj institutions.","o":["Tamil Nadu","Arunachal Pradesh","Madhya Pradesh","Andhra Pradesh"],"a":1,"x":"The 83rd Amendment (2000) exempted Arunachal Pradesh from SC reservation in panchayats, as it has no Scheduled Caste population.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q6931","q":"72nd Constitutional Amendment provided for reservation of seats for the Scheduled Tribes in the Legislative Assembly of __________.","o":["Nagaland","Tripura","Mizoram","Sikkim"],"a":1,"x":"The 72nd Amendment (1992) provided for reservation of seats for Scheduled Tribes in the Tripura Legislative Assembly.","e":"","src":["Stenographer 14 Aug 2021 S2"]},{"id":"q5408","q":"Which of the following states is having maximum members of legislative assembly?","o":["Utter Pradesh","Rajasthan","Bihar","Madhya Pradesh"],"a":0,"x":"Uttar Pradesh has the largest Legislative Assembly, with 403 seats.","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q9509","q":"In which Article of the Indian Constitution there is a provision for \"Advocate General for the State\"?","o":["Article 280","Article 213","Article 165","Article 76"],"a":2,"x":"Article 165 provides for the Advocate General of a state; Article 76 is for the Attorney General of India.","e":"","src":["Assistant Superintendent 14 Jul 2024 S1"]},{"id":"q8887","q":"How many subjects are listed in the Eleventh Schedule related to Panchayati Raj functions?","o":["21","29","12","25"],"a":1,"x":"The Eleventh Schedule (73rd Amendment) lists 29 subjects for panchayats; the Twelfth lists 18 for municipalities.","e":"","src":["MTS 2 Mar 2026 S3"]},{"id":"q8893","q":"The 73rd and 74th Constitutional Amendment Acts were passed by the Parliament of India in which of the following years?","o":["1992","1989","1990","1988"],"a":0,"x":"The 73rd (panchayats) and 74th (municipalities) Amendments were passed in 1992 and came into force in 1993.","e":"","src":["MTS 2 Mar 2026 S3"]},{"id":"q8915","q":"Under which of the following circumstances can the Governor exercise discretionary powers?","o":["Appointment of the Chief Minister of his/her choice when no party has a clear majority","Rejection of a Financial Bill","Dismissing a ministry that has lost majority support","Appointment of Chief Secretary"],"a":2,"x":"A Governor may use discretion to dismiss a ministry that has lost its majority; he cannot simply appoint a Chief Minister of his own choice or reject a money bill.","e":"","src":["MTS 3 Mar 2026 S1"]},{"id":"q8930","q":"The Ashok Mehta Committee recommended replacing the three-tier system with which structure?","o":["Six-tier system","Two-tier system","One-tier system","Four-tier system"],"a":1,"x":"The Ashok Mehta Committee (1977–78) recommended a two-tier panchayat system instead of three tiers.","e":"","src":["MTS 3 Mar 2026 S1"]},{"id":"q9003","q":"If there is a dispute in Panchayat elections, then where can it be challenged?","o":["State Governor","Supreme Court","High Court","Authority prescribed by State Legislature"],"a":3,"x":"A panchayat election dispute can be challenged only before the authority and in the manner provided by state law (Article 243-O).","e":"","src":["MTS 3 Mar 2026 S3"]},{"id":"q9153","q":"In the Panchayati Raj system, which body is responsible for approving plans and budgets at the village level and questioning the functioning of the elected village council?","o":["Block Panchayat","Chief Minister","Gram Sabha","District Court"],"a":2,"x":"The Gram Sabha approves village plans and budgets and questions the gram panchayat's work.","e":"","src":["MTS 6 Mar 2026 S3"]},{"id":"q9162","q":"Which of the following committees/commissions recommended the three-tier Panchayati Raj System in India?","o":["Sarkaria Commission","Balwant Rai Mehta Committee","Rajamannar Committee","Swaran Singh Committee"],"a":1,"x":"The Balwant Rai Mehta Committee (1957) recommended three-tier Panchayati Raj; Rajasthan adopted it first in 1959.","e":"","src":["MTS 6 Mar 2026 S3"]},{"id":"q9198","q":"Who fixes the powers and functions of the Gram Sabha by law?","o":["Sarpanch of the village","Panchayat at intermediate level","State Legislature","Central Government"],"a":2,"x":"Under Article 243A the Gram Sabha has the powers and functions given to it by the State Legislature.","e":"","src":["MTS 8 Mar 2026 S1"]},{"id":"q9268","q":"Which of the following is created at Block level for the Gram Panchayat in India?","o":["Panchayat Samiti","Village Panchayat","Zila Parishad","Municipal Corporation"],"a":0,"x":"The Panchayat Samiti is the block-level (middle) tier of Panchayati Raj.","e":"","src":["MTS 8 Mar 2026 S3"]},{"id":"q9271","q":"As part of efforts to strengthen decentralised governance after the 73rd Constitutional Amendment, in which year was the Ministry of Panchayati Raj established to oversee matters relating to Panchayati Raj Institutions?","o":["2014","1993","2004","1992"],"a":2,"x":"The Ministry of Panchayati Raj was set up in 2004.","e":"","src":["MTS 8 Mar 2026 S3"]},{"id":"q9314","q":"Zila Parishad occupies apex position as which tier in the Panchayati Raj System in India?","o":["It is the second tier","It is the fifth tier","It is the fourth tier","It is the third tier"],"a":3,"x":"The Zila Parishad is the third (top) tier of Panchayati Raj.","e":"","src":["MTS 24 Feb 2026 S3"]},{"id":"q9442","q":"The Assam Legislative Assembly election scheduled for early 2026 is expected to elect how many members?","o":["70","126","293","80"],"a":1,"x":"The Assam Legislative Assembly has 126 seats.","e":"","src":["MTS 26 Feb 2026 S3"]},{"id":"q3483","q":"Which of the following state legislature has two houses? I. Karnataka II. Kerala","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Karnataka has a bicameral legislature (Assembly and Council); Kerala has only a Legislative Assembly.","e":"Six states have a Council: UP, Bihar, Maharashtra, Karnataka, Andhra Pradesh, Telangana.","src":["Store Keeper 19 Apr 2021 S3"]},{"id":"q2997","q":"By which constitutional amendment was Puducherry made a Union Territory?","o":["12th","13th","14th","15th"],"a":2,"x":"The 14th Amendment (1962) made Puducherry (then Pondicherry) a Union Territory.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 17 Nov 2021 S3"]},{"id":"q3231","q":"Which of the following schedules of the Indian Constitution contains the powers, authority and responsibilities of Municipalities?","o":["Ninth","Tenth","Eleventh","Twelfth"],"a":3,"x":"The Twelfth Schedule (74th Amendment, 1992) lists 18 functions of municipalities.","e":"11th: panchayats (29); 12th: municipalities (18).","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S2"]},{"id":"q3934","q":"Which of the following states does not have Bicameral legislature?","o":["Andhra Pradesh","Punjab","Karnataka","Bihar"],"a":1,"x":"Punjab has only a Legislative Assembly; Andhra Pradesh, Karnataka and Bihar have two houses.","e":"Six councils: UP, Bihar, Maharashtra, Karnataka, Andhra Pradesh, Telangana.","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S1"]},{"id":"q4024","q":"Which Article gave special status to Jammu and Kashmir to have a separate constitution, a state flag and autonomy over the internal administration of the state?","o":["Article 350","Article 370","Article 371","Article 351"],"a":1,"x":"Article 370 gave Jammu and Kashmir special status, with its own constitution and flag.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"],"k":"Article 370's special provisions were revoked in August 2019."},{"id":"q5494","q":"According to Article 155 of the Indian constitution, who has the power to appoint the Governor of a State?","o":["President","Chief Minister","Prime Minister","Vice-President"],"a":0,"x":"Under Article 155 the President appoints state Governors.","e":"","src":["Accountant 29 Nov 2021 S3"]},{"id":"q0892","q":"According to Article 371F of the Indian Constitution, how many members does the Legislative Assembly of Sikkim have?","o":["25","32","45","65"],"a":1,"x":"Article 371F (36th Amendment, 1975, when Sikkim became a state) says Sikkim's Legislative Assembly shall have at least 30 members; it has 32.","e":"Sikkim is India's least populous state; 22nd state, 1975.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0911","q":"Which of the following statements is correct about the relationship of the State Council of Ministers with the Governor?","o":["They advise the Governor on governmental affairs.","They assist the Governor in drafting state laws.","They supervise the Governor's actions.","They hold office at the pleasure of the Governor."],"a":0,"x":"Article 163: a Council of Ministers headed by the Chief Minister aids and advises the Governor in exercising his functions.","e":"Article 164(1): the Chief Minister is appointed by the Governor.","src":["PRT 17 Feb 2026 S3"],"k":"Under Article 164(1) ministers also hold office during the pleasure of the Governor, so option D is technically true as well; DSSSB's key is A."},{"id":"q0915","q":"Which Article of the Constitution says there shall be a Minister in charge of tribal welfare in Chhattisgarh, Jharkhand, Madhya Pradesh and Odisha?","o":["Article 164","Article 166","Article 168","Article 170"],"a":0,"x":"The proviso to Article 164(1) requires a Minister in charge of tribal welfare in Chhattisgarh, Jharkhand, Madhya Pradesh and Odisha. The 94th Amendment (2006) replaced Bihar with Chhattisgarh and Jharkhand.","e":"The same minister may also handle SC and OBC welfare.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0973","q":"Which qualification is required for a person to be appointed Governor of an Indian state?","o":["Is a Member of Parliament","Belongs to the state of appointment and has completed 30 years of age","Has served as a judge of a High Court","Is a citizen of India and has completed 35 years of age"],"a":3,"x":"A Governor must be a citizen of India and at least 35 years old (Article 157).","e":"By convention a Governor is not from the state being governed, but this is not a legal requirement.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0981","q":"The Governor of a State shall be appointed by the ___________ by warrant under his hand and seal.","o":["Prime Minister of India","Chief Justice of India","Respective State's Chief Minister","President of India"],"a":3,"x":"Under Article 155 the President appoints the Governor by warrant under hand and seal; the Governor holds office at the President's pleasure (Article 156).","e":"Normal term: five years.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1006","q":"Which of the following statements is CORRECT regarding the term of office of a Governor in India?","o":["The Governor holds office during the pleasure of the President and may resign by writing to the President.","The Legislative Assembly of the State elects the Governor.","The Governor cannot resign once appointed until the five-year term is complete.","The governor can be removed only through impeachment in Parliament on the recommendation of the Chief Justice of India."],"a":0,"x":"A Governor holds office during the pleasure of the President (Article 156) and may resign by writing to the President. There is no impeachment for Governors.","e":"The Governor is appointed, not elected.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1019","q":"Which of the following Panchayat levels is responsible for district-level planning in India?","o":["Block Panchayat","Lok Sabha","Gram Panchayat","Zila Parishad"],"a":3,"x":"The Zila Parishad is the district-level tier of Panchayati Raj and coordinates district planning; Gram Panchayats and Block (Panchayat) Samitis sit below it.","e":"A District Planning Committee (Article 243ZD) consolidates the district plan.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1029","q":"According to the Constitution of India, which of the following pairs of urban bodies and their corresponding areas is CORRECTLY matched?","o":["Municipal Corporation – Transitional area moving from rural to urban","Municipal Board – Rural area with no urban characteristic","Nagar Panchayat – Fully developed urban metropolis","Municipal Council – Smaller urban area"],"a":3,"x":"Article 243Q: a Nagar Panchayat is for an area in transition from rural to urban, a Municipal Council for a smaller urban area, and a Municipal Corporation for a larger urban area.","e":"Added by the 74th Amendment (1992), Part IXA.","src":["PRT 19 Feb 2026 S3"]},{"id":"q1081","q":"In whose name is the administration and governance of a state in India carried out?","o":["The Chief Minister","The State Cabinet Secretary","The Governor","The President"],"a":2,"x":"The state's executive power is vested in the Governor (Article 154), and all executive actions of a state government are taken in the Governor's name (Article 166).","e":"At the Union level, actions are in the President's name (Article 77).","src":["PRT 23 Feb 2026 S2"]},{"id":"q1099","q":"According to Article 243C, which statement about the composition of and elections to panchayats is correct?","o":["Panchayat constituencies are formed only on geographical boundaries, not population.","As far as practicable, the ratio between population and the number of seats should be the same throughout the panchayat area.","Only district-level panchayats are filled by direct election; other levels are appointed.","The Governor nominates all panchayat members from local administrative bodies."],"a":1,"x":"Article 243C: as far as practicable, the ratio of population to seats should be the same throughout a panchayat area; seats are filled by direct election from territorial constituencies.","e":"Chairpersons at the intermediate and district levels are elected indirectly.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1113","q":"Which statement correctly describes the constitutional provisions for the Governor?","o":["Parliament cannot confer any function on authorities subordinate to the Governor.","The Governor exercises the state's executive power only through the Chief Minister.","The executive power of the state is vested in the Governor and exercised by him directly or through subordinate officers.","The Governor is the supreme law-making authority in the state."],"a":2,"x":"Article 154: the state's executive power is vested in the Governor, exercised directly or through subordinate officers; Parliament or the state legislature may confer functions on authorities under the Governor.","e":"In practice the Governor acts on the advice of the Chief Minister-led council.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1146","q":"According to the Indian Constitution, the powers and functions of a Gram Sabha at the village level are determined by:","o":["The Election Commission of India","The Legislature of the respective State by law","The Governor, through public notification","The Union Parliament"],"a":1,"x":"Article 243A: a Gram Sabha exercises the powers and performs the functions that the State Legislature provides by law.","e":"The 73rd Amendment (1992) added Part IX (Panchayats).","src":["PRT 26 Mar 2026 S2"]},{"id":"q1151","q":"Which department maintains land use records in India?","o":["Ministry of Environment","Forest Survey of India","Planning Commission","Land Revenue Department"],"a":3,"x":"Land-use and land ownership records (such as khasra and khatauni) are kept by the state Land Revenue Department through patwaris and tehsildars.","e":"The Digital India Land Records Modernisation Programme digitises these records.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1200","q":"Which option correctly reflects the constitutional provision on dual membership of state legislatures?","o":["The Constitution permits permanent dual membership to strengthen federal unity.","A person may hold seats in two or more state legislatures with the President's consent.","A person elected to more than one state legislature must resign from all but one within the time set by rules made by the President.","The First Schedule permits dual membership if both assemblies approve."],"a":2,"x":"Article 190(2): if a person is elected to the legislatures of two or more states, he must resign from all but one within the time set by rules made by the President, or all his seats fall vacant.","e":"Article 101 covers the same situation for Parliament.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1247","q":"The reservation of seats for SCs and STs in every municipality is based on which criterion?","o":["The State Government's discretion on the basis of social justice","The recommendation of the State Finance Commission","The proportion of the SC/ST population in the total population of the municipal area","A fixed percentage set by the Election Commission"],"a":2,"x":"Article 243T: seats for SCs and STs in every municipality are reserved in proportion to their share of the total population of that municipal area.","e":"Not less than one-third of seats are reserved for women.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1260","q":"The salary and allowances of the Chief Minister of the state are ___________.","o":["Determined by the Pay Commission of the state","Determined by the Governor of the state","Determined by the Parliament","Determined by the State Legislature"],"a":3,"x":"The salaries and allowances of the Chief Minister and other ministers are decided by the State Legislature by law (Article 164(5)).","e":"The Governor's emoluments are fixed by Parliament.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1385","q":"Which Constitutional Amendment Act promoted the appointment of the same person as a Governor for two or more states?","o":["Ninth","Third","Fifth","Seventh"],"a":3,"x":"The 7th Amendment (1956) allowed the same person to be Governor of two or more states (Article 153).","e":"The same amendment allowed a common High Court for two or more states.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1409","q":"As of 2022, which of the following states has the highest number of assembly constituencies?","o":["Maharashtra","Gujarat","Uttar Pradesh","Tamil Nadu"],"a":2,"x":"Uttar Pradesh has the most assembly constituencies, 403, and also the most Lok Sabha seats (80).","e":"Next: West Bengal (294), Maharashtra (288).","src":["TGT 25 Jun 2023 S1"]},{"id":"q1410","q":"What is the minimum age requirement, as prescribed by the Constitution, to become a member of a Panchayat?","o":["18 years","28 years","36 years","21 years"],"a":3,"x":"Under Article 243F the minimum age for a panchayat member is 21 years.","e":"Minimum age for the state legislative assembly: 25 years.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1454","q":"The power of the governor to promulgate Ordinances during recess of the Legislature is defined in Article ______ of the Indian Constitution.","o":["221","217","209","213"],"a":3,"x":"Article 213 lets a Governor issue ordinances when the state legislature is not in session; the President has the same power under Article 123.","e":"An ordinance must be approved within six weeks of the legislature reassembling.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1535","q":"The Governor of a state addresses his resignation to __________.","o":["The President of India","The Prime Minister of India","The Union Home Minister","The Chief Minister of the state"],"a":0,"x":"A Governor resigns by writing to the President of India (Article 156).","e":"The President also appoints the Governor.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1536","q":"Under Article ______ of the Constitution, the Uttarakhand Assembly passed a proposal in 2010 making Hindi the official language and Sanskrit the second official language of the state.","o":["199","310","345","234"],"a":2,"x":"Article 345 lets a state legislature adopt one or more languages as official languages of the state; Uttarakhand used it in 2010 to make Sanskrit its second official language.","e":"Himachal Pradesh also made Sanskrit a second official language (2019).","src":["TGT 24 Aug 2025 S3"]},{"id":"q1557","q":"The Administrator of Dadra and Nagar Haveli is concurrently the Administrator of which Union Territory?","o":["Andaman and Nicobar Islands","Puducherry","Daman and Diu","Lakshadweep"],"a":2,"x":"The Administrator of Dadra and Nagar Haveli also served as Administrator of Daman and Diu; since 26 January 2020 the two are merged into one UT.","e":"Its capital is Daman.","src":["TGT 31 Aug 2025 S1"]},{"id":"q1665","q":"Which article of Indian Constitution is related with the Term of office of Governor?","o":["152","156","161","165"],"a":1,"x":"Article 156 deals with the Governor's term of office.","e":"","src":["TGT 10 Oct 2021 S1"]},{"id":"q5596","q":"Provisions for SC and ST in every panchayat are made under which Article of the Constitution?","o":["Article 243(F) of the Constitution of India","Article 243(D) of the Constitution of India","Article 243(A) of the Constitution of India","Article 243(S) of the Constitution of India"],"a":1,"x":"Article 243D provides for reservation of seats for SCs and STs in every panchayat.","e":"","src":["TGT 30 Nov 2021 S1"]},{"id":"q5989","q":"Who is the head of the Municipal corporation of most states in India?","o":["Chief Minister","Mayor","Governor","Prime minister"],"a":1,"x":"The Mayor is the head of a Municipal Corporation.","e":"","src":["TGT 8 Sep 2021 S1"]},{"id":"q7498","q":"Which of the following pair of article – contents of Indian constitution is correct? I. 239 – Administration of Union territories II. 241 – Special provisions with respect to Delhi","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Article 239 deals with administration of Union Territories; special provisions for Delhi are in Article 239AA, not 241.","e":"","src":["TGT 1 Aug 2021"]},{"id":"q7499","q":"Which article of Indian constitution is related to duration of Panchayats?","o":["243A","243E","243K","243O"],"a":1,"x":"Article 243E fixes the duration of panchayats (five years).","e":"","src":["TGT 1 Aug 2021"]},{"id":"q7586","q":"Which amendment of Indian constitution provided legislative assembly for Delhi?","o":["61","69","73","76"],"a":1,"x":"The 69th Amendment (1991) gave Delhi a Legislative Assembly (Article 239AA).","e":"","src":["TGT 8 Aug 2021"]},{"id":"q7587","q":"Which article of Indian constitution is related to the duration of state legislatures?","o":["168","172","179","187"],"a":1,"x":"Article 172 deals with the duration of state legislatures.","e":"","src":["TGT 8 Aug 2021"]},{"id":"q9813","q":"By which Constitutional Amendment Act were the territories of Goa, Daman, and Diu incorporated into the Indian Constitution?","o":["8th Amendment Act, 1959","10th Amendment Act, 1961","14th Amendment Act, 1962","12th Amendment Act, 1962"],"a":3,"x":"The 12th Amendment (1962) added Goa, Daman and Diu to India as a Union Territory.","e":"","src":["TGT 23 Aug 2025 S3"]},{"id":"q8818","q":"Which of the following states was formerly a Union Territory before attaining statehood?","o":["Meghalaya","Sikkim","Manipur","Nagaland"],"a":2,"x":"Manipur was a Union Territory from 1956 until it became a state in 1972.","e":"","src":["Special Educator 26 Jun 2025 S3"]},{"id":"q8850","q":"Which Schedule of the Indian Constitution contains the list of the States and Union Territories, including their names and territorial jurisdictions?","o":["Second Schedule","Fourth Schedule","Third Schedule","First Schedule"],"a":3,"x":"The First Schedule lists the States and Union Territories and their territories.","e":"","src":["Special Educator 14 Mar 2026"]},{"id":"q0784","q":"The first municipal corporation in Madras, India, was established in the year _____.","o":["1688","1702","1704","1726"],"a":0,"x":"The Madras Municipal Corporation, set up in 1688, is the oldest municipal body in India and among the oldest in the Commonwealth outside Britain.","e":"Lord Ripon's 1882 resolution is called the Magna Carta of local self-government.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0789","q":"Which of the following does Article 243D of the Indian Constitution mandate regarding women's representation in the Panchayati Raj Institutions (PRIs)?","o":["Reservation of at least 25% of seats for women","Reservation of at least 50% of seats for women","Reservation of at least one-third (33%) of seats for women","No reservation for women"],"a":2,"x":"Article 243D reserves at least one-third of seats (and of chairperson posts) in Panchayati Raj institutions for women.","e":"Many states, such as Bihar, have raised this to 50%.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0817","q":"According to the Constitution of India, in which of the following areas can a Nagar Panchayat be set up in India?","o":["Entirely rural","Transitional area","Metropolitan city","Industrial region"],"a":1,"x":"Article 243Q provides a Nagar Panchayat for a transitional area (changing from rural to urban), a Municipal Council for a smaller urban area, and a Municipal Corporation for a larger urban area.","e":"The 74th Amendment (1992) added Part IXA on municipalities.","src":["PGT 22 Sep 2025"]},{"id":"q0866","q":"Article 371 of the Indian Constitution provides special provisions for which of the following states?","o":["Maharashtra and Madhya Pradesh","Maharashtra and Karnataka","Gujarat and Rajasthan","Maharashtra and Gujarat"],"a":3,"x":"Article 371 allows special provisions for Maharashtra (Vidarbha, Marathwada) and Gujarat (Saurashtra, Kutch), such as separate development boards.","e":"371A Nagaland, 371B Assam, 371C Manipur, and so on.","src":["PGT 24 Sep 2025"]},{"id":"q6602","q":"A person should be at least _____ years old to qualify to fill a seat in a Panchayat at any level.","o":["35","30","21","25"],"a":2,"x":"The minimum age to contest a panchayat seat is 21 years (Article 243F).","e":"","src":["PGT 3 Jul 2021 S2"]},{"id":"q6671","q":"A person must be at least ______ years old to become a member of Vidhan Sabha.","o":["25","35","30","40"],"a":0,"x":"The minimum age to become a member of a Vidhan Sabha is 25 years.","e":"","src":["PGT 10 Jul 2021 S2"]},{"id":"q7329","q":"The state of Sikkim was formed under which of the following Amendment Act?","o":["36th Constitutional Amendment Act 1975","22nd Constitutional Amendment Act 1962","29th Constitutional Amendment Act 1970","42nd Constitutional Amendment Act 1987"],"a":0,"x":"The 36th Amendment (1975) made Sikkim a full state of India.","e":"","src":["PGT 31 Jul 2021"]},{"id":"q7674","q":"The executive power of states in India is vested in which of the following posts?","o":["Chief Minister","Prime Minister","Governor","President"],"a":2,"x":"The executive power of a state is vested in the Governor (Article 154).","e":"","src":["PGT 29 Jul 2021"]},{"id":"q8509","q":"Which of the following statements about the process of the Parliament to make new states is NOT correct?","o":["The Parliament may by law form a new state and alter the boundaries or names of existing States.","A Bill to this effect cannot be introduced in the Parliament except on the recommendation of the President.","A Bill to this effect may be referred by the President to the Legislature of the affected State","Such a law will fall under the purview of Article 368."],"a":3,"x":"A law forming new states (Articles 2–4) is not treated as a constitutional amendment under Article 368.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q9575","q":"Article 371 B deals with the special provisions with respect to which of the following states?","o":["Assam","Manipur","Andhra Pradesh","Sikkim"],"a":0,"x":"Article 371B makes special provisions for Assam.","e":"","src":["PGT 28 Jun 2021 S1"]},{"id":"q9678","q":"The Panchayati Raj was introduced by the ________ Constitutional Amendment Act of 1992.","o":["68th","73rd","82nd","56th"],"a":1,"x":"The 73rd Amendment (1992) gave Panchayati Raj constitutional status.","e":"","src":["PGT 29 Jun 2021"]},{"id":"q9867","q":"Who among the following was the Prime Minister of India during the 73rd Constitutional Amendment?","o":["Rajiv Gandhi","PV Narasimha Rao","Indira Gandhi","Charan Singh"],"a":1,"x":"P.V. Narasimha Rao was Prime Minister when the 73rd Amendment was passed (1992).","e":"","src":["PGT 25 Sep 2025"]},{"id":"q3076","q":"Given are the states that underwent an alteration of names in the constitutional history. Match them with their correct years, respectively. States and their new names Year 1 Orissa/Odisha i 2007 2 Mysuru /Karnataka ii 1969 3 Uttaranchal/Uttarakhand iii 2011 4 Chennai /Tamil Nadu iv 1973","o":["1- ii, 2- iv, 3- i, 4- iii","1- iii, 2- i, 3- iv, 4- ii","1- iv, 2- i, 3- ii, 4- iii","1- iii, 2- iv, 3- i, 4- ii"],"a":3,"x":"Orissa became Odisha (2011), Mysore became Karnataka (1973), Uttaranchal became Uttarakhand (2007) and Madras State became Tamil Nadu (1969).","e":"","src":["Draftsman 17 Oct 2021 S1"]},{"id":"q4149","q":"Who founded the All India Anna Dravida Munnetra Kazhagam (AIADMK) party?","o":["M. G. Ramachandran","J. Jayalalithaa","Janaki Ramachandran","M. Karunanidhi"],"a":0,"x":"M.G. Ramachandran founded the AIADMK in 1972.","e":"","src":["Manager (Public Relations) 23 Oct 2021 S2"]},{"id":"q4662","q":"Identify the mismatch pair from following -","o":["Article 76 - Attorney General of India","Article 340 - Backward Classes Commission","Article 163 - Advocate General of State","Article 339 - Scheduled Area and Scheduled Tribes Commission"],"a":2,"x":"The Advocate General of a state is under Article 165; Article 163 deals with the Council of Ministers aiding the Governor.","e":"","src":["Librarian 25 Nov 2021 S3"]},{"id":"q4818","q":"Under which article of the Constitution of India does the Governor of a State have the Power to grant Pardon?","o":["Article 72","Article 75","Article 161","Article 165"],"a":2,"x":"A Governor's power to pardon is under Article 161.","e":"","src":["Scientific Assistant (Chemistry) 25 Sep 2021 S3"]},{"id":"q4839","q":"Which among the following Constitutional Amendments led to creation of Legislative Assemblies for Himachal Pradesh, Tripura, Manipur, Goa, Daman & Diu and Pondicherry?","o":["18th","14th","26th","20th"],"a":1,"x":"The 14th Amendment (1962) allowed legislatures for Union Territories such as Himachal Pradesh, Tripura, Manipur, Goa and Pondicherry.","e":"","src":["Technical Assistant (Architecture) 26 Jul 2021"]},{"id":"q5130","q":"Which among the following constitutional amendments is associated with the formation of Arunachal Pradesh legislative assembly?","o":["25th","37th","28th","32nd"],"a":1,"x":"The 37th Amendment (1975) gave Arunachal Pradesh a legislative assembly.","e":"","src":["Assistant Engineer (Civil) 26 Sep 2021 S3"]},{"id":"q5258","q":"Which among the following Schedule in the Indian Constitution is associated with Panchayat Raj?","o":["Eighth","Ninth","Eleventh","Tenth"],"a":2,"x":"The Eleventh Schedule lists the powers of Panchayats.","e":"","src":["Assistant Engineer (Civil) 27 Sep 2021 S2"]},{"id":"q5259","q":"49th Constitutional Amendment Act gave a constitutional sanctity to the Autonomous District Council in __________.","o":["Tripura","Sikkim","Arunachal Pradesh","Meghalaya"],"a":0,"x":"The 49th Amendment (1984) gave constitutional status to Tripura's Autonomous District Council.","e":"","src":["Assistant Engineer (Civil) 27 Sep 2021 S2"]},{"id":"q5665","q":"An assembly of elected representatives at the ______ level is known as the Legislative Assembly.","o":["Village","District","State","National"],"a":2,"x":"The Legislative Assembly (Vidhan Sabha) is the assembly of elected representatives at the state level.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q5668","q":"Tenure of urban local self-governing bodies is fixed at five years and in case of earlier dissolution fresh elections are held within ______ months","o":["Two","Three","Four","Six"],"a":3,"x":"Municipalities have a five-year term; if one is dissolved early, elections must be held within six months (Article 243U).","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q5669","q":"Gram Sabha consists of all ______ residents within a village or group of villages.","o":["Minor","Male","Female","Adult"],"a":3,"x":"The Gram Sabha is made up of all adult voters living in the area of a village panchayat.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q6013","q":"Which among the following Constitutional Amendment deals with reorganisation of Mizoram into a Union Territory with a legislature and council of ministers?","o":["14th","32nd","41st","27th"],"a":3,"x":"The 27th Amendment (1971) provided for Mizoram as a Union Territory with a legislature and council of ministers.","e":"","src":["Technical Assistant (Electronic & Communication) 8 Sep 2021 S2"]},{"id":"q6418","q":"Harekrushna Mahatab was the first Chief Minister of which of the following states?","o":["Tripura","Assam","West Bengal","Odisha"],"a":3,"x":"Harekrushna Mahatab was the first Chief Minister of Odisha.","e":"","src":["Technical Assistant (Commercial Art) 14 Aug 2021 S2"]},{"id":"q6439","q":"Who among the following is the first lady Chief Minister of a state in India?","o":["Anwara Taimur","Shashikala Kakodkar","Nandini Satpathy","Sucheta Kripalani"],"a":3,"x":"Sucheta Kripalani (Uttar Pradesh, 1963) was India's first woman Chief Minister.","e":"","src":["Technical Assistant (Digital Electronics) 7 Aug 2021"]},{"id":"q7388","q":"Which of the following pair of part – contents of Indian constitution is correct? I. Part VI – The states II. Part VIII – The union territories","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Part VI deals with the States and Part VIII with the Union Territories.","e":"","src":["Physical Education Teacher 2 Aug 2021"]},{"id":"q7411","q":"Which of the following pair of article – contents of Indian constitution is correct? I. 153 – governors of state II. 156 – appointment of governor","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Article 153 provides for Governors of states; appointment is Article 155, while Article 156 is the term of office.","e":"","src":["Physical Education Teacher 2 Aug 2021"]},{"id":"q7452","q":"90th Constitutional Amendment provided for maintaining the erstwhile representation of the Scheduled Tribes and Non-Scheduled Tribes in the _________ legislative assembly.","o":["West Bengal","Assam","Tripura","Odisha"],"a":1,"x":"The 90th Amendment (2003) kept the existing ST and non-ST representation in the Assam assembly for the Bodoland area.","e":"","src":["Technical Assistant (Library Science) 7 Aug 2021"]}]},{"id":"federal","n":"Centre–State Relations and Emergency","qs":[{"id":"q0184","q":"How does the Indian Constitution ensure that the Union Government maintains control over national security and defence?","o":["By providing each state with its own military forces","By empowering states to sign international treaties","By placing defence and external affairs under the Union List","By allowing states to manage their defence forces"],"a":2,"x":"Defence, armed forces and external affairs are on the Union List of the Seventh Schedule, so only Parliament can make laws on them.","e":"Police and public order are on the State List.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0269","q":"What mechanism allows the Central Government to issue directives to states to ensure compliance with union laws?","o":["Finance Commission directives","Emergency proclamations","Constitutional provisions under Article 256","Constitutional provisions under Article 236"],"a":2,"x":"Article 256 obliges states to follow Union laws, and lets the Union give states directions to ensure that.","e":"Under Article 365, if a state ignores Union directions, the President may hold that its government cannot be carried on constitutionally.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0307","q":"Which Article of the Constitution gives the Central Government the duty to protect states against external aggression and internal disturbance?","o":["Article 356","Article 352","Article 355","Article 256"],"a":2,"x":"Article 355 makes it the Union's duty to protect every state against external aggression and internal disturbance, and to ensure it runs by the Constitution.","e":"Article 352: national emergency. Article 356: President's Rule.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0317","q":"What is the relationship between the Union Government and the States when a national emergency is declared?","o":["The State governments lose all their legislative powers.","The Union Government gains the power to legislate on State subjects.","The President's powers are limited to defence and foreign affairs.","The States retain full autonomy and only national matters are affected."],"a":1,"x":"During a national emergency (Article 352), Parliament can make laws on State List subjects (Article 250) and the Union can direct states. States keep their governments but lose autonomy.","e":"Such laws stop working six months after the emergency ends.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0594","q":"Which among the following Schedules in the Indian Constitution is associated with the central government, state, and concurrent lists of responsibilities?","o":["Sixth","Ninth","Eighth","Seventh"],"a":3,"x":"The Seventh Schedule sets out the Union List, State List and Concurrent List.","e":"Originally 97, 66 and 47 subjects.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q1771","q":"Which of the following subjects are mentioned in the concurrent list of the Indian constitution? I. Trust and Trustees II. Actionable Wrongs III. Forests","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Trusts and trustees, actionable wrongs, and forests (moved there by the 42nd Amendment) are all in the Concurrent List.","e":"42nd Amendment moved education, forests, weights and measures, wildlife and justice administration to the Concurrent List.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1854","q":"Which of the following subjects are mentioned in the Union list of the Indian constitution? I. War and Peace II. Extradition III. Railways","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"War and peace, extradition and railways are all Union List subjects (List I of the Seventh Schedule).","e":"Union List ~100 subjects; State List ~61; Concurrent ~52.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1857","q":"Article ______ of the Indian constitution deals with Proclamation of Emergency.","o":["354","352","357","356"],"a":1,"x":"Article 352 deals with a Proclamation of (National) Emergency; Article 356 with President's Rule in states and Article 360 with Financial Emergency.","e":"352 national, 356 state, 360 financial.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1966","q":"Which of the following statement(s) regarding Residuary powers of legislation is/are correct? I. Parliament has exclusive power to make any law with respect to any matter not enumerated in the concurrent list or state list. II. Such power shall include the power of making any law imposing a tax not mentioned in either of concurrent or state list.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 248: Parliament has exclusive power over any matter not listed in the Concurrent or State List (residuary powers), including taxes not mentioned in either list.","e":"Residuary powers lie with the Union (Canadian model).","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q2463","q":"Under which of the following of the Constitution is ‘Police’ under the State list?","o":["Article 132","5th Schedule","7th Schedule","Article 330"],"a":2,"x":"'Police' and 'public order' are State List subjects in the Seventh Schedule.","e":"Seventh Schedule = three lists.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2620","q":"Which of the following subject(s) is/are mentioned in the Union list? I. Central Bureau of Intelligence and Investigation II. Extradition III. Insurance","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"The Central Bureau of Intelligence and Investigation, extradition and insurance are all Union List subjects.","e":"Banking and insurance are central subjects.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2691","q":"How many subjects are included in the union list?","o":["102","66","47","97"],"a":3,"x":"The Union List originally had 97 subjects; after amendments it now has about 100.","e":"State List: originally 66; Concurrent: originally 47.","src":["Junior Clerk 16 Nov 2021 S2"],"k":"The count of 97 is the original number; current texts give about 100 Union List subjects."},{"id":"q2890","q":"Which of the following subject(s) is/are mentioned in the state list? I. Intoxicating liquors II. Relief of the disable and unemployable III. Agriculture","o":["I and II","I and III","II and III","I, II and III"],"a":3,"x":"Intoxicating liquors, relief of the disabled and unemployable, and agriculture are all State List subjects.","e":"","src":["Junior Clerk 17 Nov 2021 S1"]},{"id":"q6170","q":"Which of the following subjects are mentioned in the state list of the Indian constitution? I. Markets and fairs II. Betting and Gambling III. Treasure Trove","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Markets and fairs, betting and gambling, and treasure trove are all State List subjects.","e":"","src":["Junior Clerk 9 Nov 2021 S2"]},{"id":"q1358","q":"The 48th Constitutional Amendment facilitated the extension of President’s rule in ___________ beyond one year without meeting the two special conditions for such extension.","o":["Assam","Sikkim","Mizoram","Punjab"],"a":3,"x":"The 48th Amendment (1984) allowed President's Rule in Punjab to be extended beyond one year without the usual conditions (national emergency and Election Commission certification).","e":"Article 356 normally allows President's Rule for at most three years.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q6882","q":"The concept of 'Concurrent List' of the Indian Constitution is borrowed from the constitution of _________.","o":["France","Australia","Germany","United States of America"],"a":1,"x":"The idea of a Concurrent List was borrowed from the Australian Constitution.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q6974","q":"Which among the following part of the Indian Constitution deals with Emergency Provisions?","o":["XIX","XIII","XV","XVIII"],"a":3,"x":"Part XVIII (Articles 352–360) deals with emergency provisions.","e":"","src":["Stenographer 8 Aug 2021"]},{"id":"q3484","q":"Which of the following subjects are mentioned in the Union list of the Indian constitution? I. Treasure Trove II. War and Peace III. Insurance","o":["I and II","II and III","I and III","I, II and III"],"a":1,"x":"War and peace and insurance are Union List subjects; treasure trove is a State List subject.","e":"","src":["Store Keeper 19 Apr 2021 S3"]},{"id":"q3853","q":"Which of the following statement(s) regarding Emergency is/are correct? I. Article 352 of the Indian constitution deals with Proclamation of Emergency. II. Article 353 of the Indian constitution deals with effect of proclamation of Emergency.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Article 352 deals with the proclamation of emergency and Article 353 with its effects, so both are correct.","e":"","src":["Store Keeper 22 Apr 2021 S2"]},{"id":"q2777","q":"Which among the following Articles of Indian Constitution deals with \"Financial Emergency\"?","o":["330","350","360","352"],"a":2,"x":"Article 360 deals with Financial Emergency; it has never been declared.","e":"352 national, 356 state, 360 financial.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q4565","q":"Which part of the constitution deals with the relationship between the Union and the states?","o":["Part XI","Part XIII","Part IX A","Part XIV"],"a":0,"x":"Part XI (Articles 245–263) deals with relations between the Union and the states.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S1"]},{"id":"q4424","q":"Which of the following Constitutional Body has been constituted under Article 280 of the Constitution of India?","o":["Goods and Service Tax Council","UPSC and State Public Service Commission","Finance Commission","Election Commission of India"],"a":2,"x":"The Finance Commission is set up under Article 280.","e":"","src":["Hindi Translator-cum-Assisstant 24 Nov 2021 S2"]},{"id":"q4426","q":"Articles ______ in Part XI of the Constitution of India deal with the Legislative relations between Central and State.","o":["228 to 239","212 to 227","268 to 293","245 to 255"],"a":3,"x":"Articles 245 to 255 in Part XI cover legislative relations between the Union and the States.","e":"","src":["Hindi Translator-cum-Assisstant 24 Nov 2021 S2"]},{"id":"q0984","q":"Article 359A of the Indian Constitution is related to which of the following states?","o":["Meghalaya","Punjab","Jammu & Kashmir","Assam"],"a":1,"x":"Article 359A (added by the 59th Amendment, 1988) allowed extra emergency powers for Punjab; it lapsed after two years and was later repealed.","e":"The 63rd Amendment (1989) omitted it.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1016","q":"Under which of the following circumstances can the Parliament legislate on a matter in the State List?","o":["When the Governor of a State requests intervention by the Union Government","When the Rajya Sabha passes a resolution by a two-thirds majority in the national interest","When the Lok Sabha passes a resolution by a simple majority in the national interest","When the President gives assent without recommendation"],"a":1,"x":"Under Article 249, Parliament can make law on a State List subject if the Rajya Sabha passes a resolution by a two-thirds majority of members present and voting, saying it is in the national interest.","e":"Such a resolution lasts one year and can be renewed.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1028","q":"Which of the following statements regarding the Inter-State Council under Article 263 is CORRECT?","o":["It can be established by the President if deemed necessary in the public interest.","It is a permanent constitutional body.","It can be established by the Chief Justice of India if deemed necessary in the public interest.","It has adjudicatory powers to resolve interstate river water disputes."],"a":0,"x":"Article 263 lets the President set up an Inter-State Council if public interest needs it; it is not permanent, advisory only, and does not decide river water disputes (Article 262 covers those). One was set up in 1990 on the Sarkaria Commission's advice.","e":"The Prime Minister chairs it.","src":["PRT 19 Feb 2026 S3"]},{"id":"q1103","q":"According to Article 352 of the Indian Constitution, the proclamation of emergency is the responsibility of whom, if satisfied that a grave emergency exists whereby the security of India or any part of its territory is threatened by war, external aggression or armed rebellion?","o":["Defence Minister of India","Defence Secretary of India","Vice President of India","President of India"],"a":3,"x":"Under Article 352 the President proclaims a National Emergency when satisfied that India's security is threatened by war, external aggression or armed rebellion, but only on the Cabinet's written advice (44th Amendment).","e":"'Armed rebellion' replaced 'internal disturbance' in 1978.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1117","q":"According to which Article of the Indian Constitution 'shall it be the duty of the Union to protect every State against external aggression and internal disturbance and to ensure that the government of every State is carried on in accordance with the provisions of this Constitution'?","o":["Article 455","Article 555","Article 355","Article 255"],"a":2,"x":"Article 355 makes it the Union's duty to protect every state against external aggression and internal disturbance, and to ensure each state is governed according to the Constitution.","e":"Article 356: President's Rule if that fails.","src":["PRT 26 Mar 2026 S1"]},{"id":"q1168","q":"Article 254(2) permits a State law on a Concurrent List subject to prevail over a Parliamentary law only if:","o":["The law is approved by two or more States","The State law is passed by a special majority","The law receives the President’s assent after being reserved","The law is certified by the Chief Justice of the State"],"a":2,"x":"Article 254(2): if a State law on a Concurrent List subject conflicts with a central law, the State law prevails in that State if it was reserved for the President and received his assent.","e":"Parliament can still override it later.","src":["PRT 26 Mar 2026 S3"]},{"id":"q3780","q":"The first ever national emergency was declared during the Sino-Indian war on October 26, 1962 which lasted till January 10, ______.","o":["1964","1966","1968","1970"],"a":2,"x":"India's first national emergency, declared on 26 October 1962 during the war with China, lasted until 10 January 1968.","e":"","src":["Nursery Teacher 21 Oct 2021 S2"]},{"id":"q1429","q":"The grants-in-aid by the Union government to certain states, charged on the Consolidated Fund of India, are described in Article ______ of the Constitution.","o":["475","175","275","375"],"a":2,"x":"Article 275 provides statutory grants-in-aid to states in need, charged on the Consolidated Fund of India.","e":"Article 282 allows discretionary grants for any public purpose.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1722","q":"In which of the following Schedule of the Constitution, the 'State List' is given?","o":["5th","6th","7th","8th"],"a":2,"x":"The Union, State and Concurrent Lists are in the Seventh Schedule.","e":"","src":["TGT 10 Sep 2021 S3"]},{"id":"q5851","q":"Which of the following Articles deals with the imposition of Presidents Rule or Emergency in India?","o":["Article 356","Article 105","Article 123","Article 93"],"a":0,"x":"Article 356 deals with President's Rule (emergency due to failure of constitutional machinery in a state).","e":"","src":["TGT 5 Sep 2021 S3"]},{"id":"q5890","q":"From which country the idea of including the emergency provisions in the constitution of India has been borrowed?","o":["Canada","South Africa","Ireland","Germany"],"a":3,"x":"India's emergency provisions were borrowed from the Weimar Constitution of Germany.","e":"","src":["TGT 6 Sep 2021 S2"]},{"id":"q5955","q":"In case of Emergency in the country, who among the following can suspend the fundamental rights?","o":["Prime Minister","High Court","President","Supreme Court"],"a":2,"x":"During a national emergency the President can suspend the enforcement of Fundamental Rights (Articles 358–359).","e":"","src":["TGT 7 Sep 2021 S2"]},{"id":"q5995","q":"The Union List includes subjects such as ______.","o":["Police, trade,agriculture and irrigation.","Residuary subjects like computer software.","Defence, foreign affairs, banking, currency, communication.","Education, forests,trade unions, and succession"],"a":2,"x":"The Union List includes defence, foreign affairs, banking, currency and communications.","e":"","src":["TGT 8 Sep 2021 S1"]},{"id":"q0859","q":"Which of the following schedules deals with the division of powers between the Union and the States?","o":["Fifth Schedule","Second Schedule","Seventh Schedule","First Schedule"],"a":2,"x":"The Seventh Schedule divides powers between the Union and states through the Union, State and Concurrent Lists.","e":"Residuary powers rest with Parliament (Article 248).","src":["PGT 14 Jul 2025"]},{"id":"q6580","q":"Which among the following Parts of the Indian Constitution deals with 'Trade, Commerce and Intercourse within the Territory of India'?","o":["Part XIII","Part X","Part VI","Part VIII"],"a":0,"x":"Part XIII (Articles 301–307) deals with trade, commerce and intercourse within India.","e":"","src":["PGT 3 Jul 2021 S1"]},{"id":"q6603","q":"Under Article __________, the President enjoys the power to proclaim the Financial Emergency.","o":["365","360","370","355"],"a":1,"x":"Article 360 empowers the President to proclaim a Financial Emergency.","e":"","src":["PGT 3 Jul 2021 S2"]},{"id":"q7262","q":"The Home Minister of Central Government of India is the common chairman of ____ zonal councils.","o":["ten","two","five","seven"],"a":2,"x":"The Union Home Minister chairs all five Zonal Councils.","e":"","src":["PGT 29 Jul 2021 S1"]},{"id":"q7263","q":"Article ____ of the Indian Constitution deals with the suspension of the Fundamental Rights guaranteed by Article 19.","o":["352","346","351","358"],"a":3,"x":"Article 358 suspends the Article 19 freedoms during a national emergency.","e":"","src":["PGT 29 Jul 2021 S1"]},{"id":"q7280","q":"Which of the following commission was appointed by the Central Government on Union-State relations in 1983?","o":["Dutt Commission","Sarkaria Commission","Setalvad Commission","Kalelkar Commission"],"a":1,"x":"The Sarkaria Commission on Centre–State relations was appointed in 1983.","e":"","src":["PGT 10 Jul 2021"]},{"id":"q8410","q":"Population census comes under Article _________.","o":["246","233","179","128"],"a":0,"x":"Census is a Union List subject (Entry 69), made under Article 246 and the Seventh Schedule.","e":"","src":["PGT 21 Jun 2023 S2"]},{"id":"q9656","q":"How many entries are there in the Union List provided in Seventh Schedule of the Indian Constitution, when Indian constitution was formed?","o":["66","69","99","97"],"a":3,"x":"The original Constitution's Union List had 97 entries.","e":"","src":["PGT 29 Jun 2021"]},{"id":"q1685","q":"Which among the following Constitutional Amendment made a provision for service tax?","o":["88th","76th","91st","79th"],"a":0,"x":"The 88th Amendment (2003) added Article 268A on service tax.","e":"","src":["Technical Assistant (Computer) 10 Sep 2021 S1"]},{"id":"q2791","q":"Which of the following subjects come under the purview of the Concurrent List given in the Constitution of India?","o":["Newspapers, books and printing presses","Gas and gas-works","Inter-State migration; inter-State quarantine","Census"],"a":0,"x":"Newspapers, books and printing presses are a Concurrent List subject; census and inter-state quarantine are Union subjects.","e":"","src":["Inspecting Officer 16 Oct 2021 S1"]},{"id":"q3993","q":"Which Articles of the Indian Constitution deal with the Administrative relations between the Union and State Governments?","o":["212 to 223","221 to 231","256 to 263","251 to 254"],"a":2,"x":"Articles 256 to 263 deal with administrative relations between the Union and the States.","e":"","src":["Technical Assistant (Printing) 22 Nov 2021 S3"]},{"id":"q4663","q":"Which of the following subjects is not included in the Union List?","o":["Post Office Savings Bank","Insurance","Public health and sanitation","Cultivation of opium"],"a":2,"x":"Public health and sanitation is a State List subject; post office savings banks, insurance and opium cultivation are Union List subjects.","e":"","src":["Librarian 25 Nov 2021 S3"]},{"id":"q4915","q":"According to which of the following Schedules of the Constitution of India were the legislative powers divided between the Union and the States?","o":["7th Schedule","6th Schedule","3rd Schedule","4th Schedule"],"a":0,"x":"The Seventh Schedule divides legislative powers between the Union and the States.","e":"","src":["Assistant Bacteriologist 26 Nov 2021 S2"]},{"id":"q5357","q":"Which of the following set-up of governance, the Indian Government has?","o":["Federal","Unitary","Quasi-Federal","Fully Independent"],"a":2,"x":"India's system is described as quasi-federal.","e":"","src":["Laboratory Assistant (Physics) 28 Aug 2021"]},{"id":"q5662","q":"Which feature of the Indian constitution refers to the existence of more than one level of government in the country?","o":["Secularism","Federalism","Separation of Powers","Fundamental Rights"],"a":1,"x":"Federalism means more than one level of government, e.g. the Union and the states.","e":"","src":["Driver 30 Nov 2021 S3"]},{"id":"q8224","q":"Which article of the constitution mentions about “Goods and Service Tax Council”?","o":["268A","279A","278","273"],"a":1,"x":"Article 279A provides for the GST Council.","e":"","src":["Legal Assistant or Assistant Law Officer 20 Jun 2022 S2"]}]},{"id":"bodies","n":"Constitutional Bodies, Acts and Elections","qs":[{"id":"q0064","q":"How many national parties were recognised at the time of the first Lok Sabha elections 1951-52?","o":["5","10","14","8"],"a":2,"x":"14 parties were recognised as national parties in the first general elections of 1951–52.","e":"Congress won 364 of 489 seats.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0115","q":"Who among the following was the Prime Minister of India when the Right to Information Bill was passed in Parliament?","o":["Rajiv Gandhi","Narendra Modi","Atal Bihari Vajpayee","Dr. Manmohan Singh"],"a":3,"x":"The Right to Information Act was passed in 2005, when Dr Manmohan Singh was Prime Minister; it came fully into force on 12 October 2005.","e":"The President at the time was Dr A. P. J. Abdul Kalam.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0196","q":"Who among the following was the President of India when the Right to Information Bill was passed in the Parliament?","o":["KR Narayan","Dr. APJ Abdul Kalam","Dr. Shankar Dayal Sharma","Ramnath Kovind"],"a":1,"x":"When Parliament passed the RTI Bill in 2005 the President was Dr A. P. J. Abdul Kalam, who gave assent on 15 June 2005.","e":"The Prime Minister then was Dr Manmohan Singh.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0271","q":"Which of the following is an independent statutory body established under an Act of 2013 of the Parliament of India?","o":["Attorney General of India","Election Commission","Lokpal and Lokayuktas","Comptroller and Auditor General of India"],"a":2,"x":"The Lokpal and Lokayuktas Act, 2013 set up the Lokpal as an independent statutory anti-corruption body. The other options are constitutional posts.","e":"The first Lokpal, Justice Pinaki Chandra Ghose, took office in 2019.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0432","q":"Who was the first Indian Chairman of the Union Public Service Commission after Independence?","o":["V. S. Hejmadi","R. N. Banerjee","N. Govindarajan","H. K. Kripalani"],"a":3,"x":"H. K. Kripalani was the first Indian chairman of the (Federal) Public Service Commission after Independence (1947–49); R. N. Banerjee chaired it when it became the UPSC in 1950.","e":"The UPSC works under Articles 315–323; it was first set up in 1926 (Lee Commission).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0437","q":"UPSC is a constitutional body that discharges the duties and functions assigned to it under Article __________.","o":["317","320","323","313"],"a":1,"x":"Article 320 lists the functions of the UPSC and the State PSCs: conducting examinations and advising on recruitment, promotions and disciplinary matters.","e":"Article 315: PSCs for the Union and states. Article 317: removal of members.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0439","q":"Which commission is mainly constituted to recommend the distribution of tax revenue between the Union and the states, and among the states?","o":["Law Commission","Competition Commission of India","Finance Commission","Planning Commission"],"a":2,"x":"The Finance Commission (Article 280) recommends how tax revenue is shared between the Union and states and among states; it is set up every five years.","e":"The first Finance Commission was chaired by K. C. Neogy (1951).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0475","q":"In which Article of the Constitution of India is the Goods and Services Tax Council defined?","o":["Article 324","Article 315","Article 279A","Article 338A"],"a":2,"x":"Article 279A (added by the 101st Amendment, 2016) creates the GST Council, chaired by the Union Finance Minister with state finance ministers as members.","e":"GST came into force on 1 July 2017.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1573","q":"In which Lok Sabha election was the highest voter turnout recorded?","o":["17th","1st","16th","4th"],"a":0,"x":"The 17th Lok Sabha election (2019) recorded the highest voter turnout of any general election, about 67.4%.","e":"The 2024 (18th) election recorded about 65.8%.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1588","q":"The National Commission for Scheduled Tribes (NCST) was established by amending ______.","o":["Article 245","Article 166","Article 338","Article 344"],"a":2,"x":"The National Commission for Scheduled Tribes was created in 2004 when the 89th Amendment (2003) split the old Article 338 commission, adding Article 338A for STs.","e":"Article 338 now covers the National Commission for SCs.","src":["Patwari 20 Aug 2022 S2"],"k":"Strictly, the NCST sits in Article 338A, inserted by amending Article 338."},{"id":"q1589","q":"Who is the chairman of the Fifteenth Finance Commission?","o":["N. K. Singh","A. N. Jha","Anoop Singh","Ramesh Chand"],"a":0,"x":"N. K. Singh chaired the Fifteenth Finance Commission (2021-26 award period).","e":"The Sixteenth Finance Commission (2026-31) is chaired by Arvind Panagariya.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q1596","q":"The Right to Information Act was enforced in ______.","o":["2007","2004","2006","2005"],"a":3,"x":"The Right to Information Act, 2005 came fully into force on 12 October 2005.","e":"It set up the Central and State Information Commissions.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q6801","q":"Which among the following Constitutional Amendments made provision to form autonomous states within the state of Assam?","o":["20th","22nd","24th","26th"],"a":1,"x":"The 22nd Amendment (1969) added Article 244A to allow an autonomous state within Assam (it led to Meghalaya).","e":"","src":["Junior Assistant 25 Aug 2021"]},{"id":"q1746","q":"The National Human Rights Commission (NHRC) of India was established on:","o":["2 October","15 August","26 January","12 October"],"a":3,"x":"The National Human Rights Commission was set up on 12 October 1993 under the Protection of Human Rights Act, 1993.","e":"It is a statutory body, not a constitutional one.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1813","q":"Which of the following language is mentioned in the Eighth Schedule of the Indian constitution? I. Dogri II. Bodo","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Dogri and Bodo, along with Maithili and Santhali, were added to the Eighth Schedule by the 92nd Amendment (2003), which now lists 22 languages.","e":"92nd Amendment = 4 languages added in 2003.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1814","q":"In which year did the sixty first amendment of the Indian constitution take place?","o":["1990","2002","1982","1988"],"a":3,"x":"The 61st Amendment Act, 1988 lowered the voting age from 21 to 18 for Lok Sabha and Assembly elections (in force from 1989).","e":"Article 326 governs adult suffrage.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q2008","q":"In which year did the Twentieth amendment of the Indian constitution took place?","o":["1962","1964","1968","1966"],"a":3,"x":"The 20th Amendment (1966) validated appointments of district judges in Uttar Pradesh that a Supreme Court ruling had put in doubt.","e":"19th (1966) abolished election tribunals.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2094","q":"Which of the following languages are mentioned in the Eighth Schedule of the Indian constitution? I. Bengali II. Assamese II. Nepali","o":["I and II","II and III","I and III","I, II and III"],"a":3,"x":"Bengali and Assamese were among the original Eighth Schedule languages, and Nepali was added by the 71st Amendment (1992), so all three are listed.","e":"22 languages in the Eighth Schedule now.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2127","q":"Who has been appointed as the first Lokpal of India?","o":["Pinaki Chandra Ghose","Abhilasha Kumari","P K Mohanty","Aditya Mishra"],"a":0,"x":"Justice Pinaki Chandra Ghose became India's first Lokpal in March 2019 under the Lokpal and Lokayuktas Act, 2013.","e":"Lokpal = anti-corruption ombudsman.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2131","q":"Which part of the Indian constitution deals with elections?","o":["XVII","XVIII","XIV","XV"],"a":3,"x":"Part XV (Articles 324–329) of the Constitution deals with elections and the Election Commission.","e":"Article 324: Election Commission.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2176","q":"Which of the following is a constitutional body?","o":["National Human Rights Commission","National Commission for Women","National Consumer Disputes Redressal Commission","National Commission for Scheduled Castes"],"a":3,"x":"The National Commission for Scheduled Castes is a constitutional body (Article 338). The NHRC, NCW and NCDRC are statutory bodies set up by Acts.","e":"Constitutional = named in the Constitution; statutory = created by an Act.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2422","q":"Which of the following is the tenure of the election commissioners of India?","o":["Six years or until they reach the age of sixty-five","Six years or until they reach the age of sixty-three","Five years or until they reach the age of sixty-three","Five years or until they reach the age of sixty-five"],"a":0,"x":"The Chief Election Commissioner and Election Commissioners hold office for six years or until age 65, whichever comes first.","e":"The CEC is removed like a Supreme Court judge.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2465","q":"Which was the first tribal language to be included in the eighth schedule of the Indian Constitution?","o":["Shompen","Nepali","Tulu","Bodo"],"a":3,"x":"Bodo, a tribal language of Assam, was added to the Eighth Schedule by the 92nd Amendment (2003), with Dogri, Maithili and Santhali.","e":"Santhali, another tribal language, was added in the same amendment.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2547","q":"Which of the following constitutional amendments brought down the minimum age for voting from 21 years to 18 years?","o":["52nd","61st","73rd","74th"],"a":1,"x":"The 61st Amendment Act (1988) lowered the voting age from 21 to 18 years.","e":"Article 326: adult suffrage.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2551","q":"Which of the following is the Article 324 of the Indian Constitution related to?","o":["Supreme Court","Election Commission","Governor","Central Vigilance Commission"],"a":1,"x":"Article 324 vests the superintendence, direction and control of elections in the Election Commission.","e":"Part XV: Articles 324–329.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q6171","q":"Through which constitutional amendment ‘Privy Purses’ were abolished from Indian constitution?","o":["Twenty first","First","Forty second","Twenty sixth"],"a":3,"x":"The 26th Amendment (1971) abolished the privy purses of former princely rulers.","e":"","src":["Junior Clerk 9 Nov 2021 S2"]},{"id":"q6225","q":"Through which constitutional amendment voting age was reduced from 21 to 18 in the Indian constitution?","o":["Sixty first","Forty fourth","Forty second","Twenty seventh"],"a":0,"x":"The 61st Amendment (1988) lowered the voting age from 21 to 18.","e":"","src":["Junior Clerk 9 Nov 2021 S3"]},{"id":"q4064","q":"The concept of 'Procedure for Amendment of the Constitution' in the Indian Constitution has been borrowed from the constitution of which of the following countries?","o":["Japan","Australia","South Africa","United States of America"],"a":2,"x":"India borrowed the procedure for amending the Constitution (and election of Rajya Sabha members) from South Africa.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q4068","q":"Which among the following languages was added in the Eighth Schedule by 92nd Constitutional Amendment?","o":["Konkani","Manipuri","Sindhi","Bodo"],"a":3,"x":"The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali to the Eighth Schedule.","e":"","src":["Stenographer 23 Apr 2021 S1"]},{"id":"q4863","q":"When was National Commission for Women established?","o":["1991","1992","1993","1994"],"a":1,"x":"The National Commission for Women was set up on 31 January 1992 under an Act of 1990.","e":"","src":["Stenographer 26 Nov 2021 S1"]},{"id":"q4897","q":"Who was the first Comptroller and Auditor General of independent India?","o":["Vinod Rai","AK Chanda","CG Somiah","V. Narahari Rao"],"a":3,"x":"V. Narahari Rao was the first Comptroller and Auditor General of independent India (1948–54).","e":"","src":["Stenographer 26 Nov 2021 S1"]},{"id":"q5022","q":"In the Constitution of India, by which amendment act is Article 48A inserted that is related to the protection and improvement of environment and safeguarding of forests and wildlife?","o":["Constitution (Eighty-seventh Amendment) Act, 2003","Constitution (Seventh Amendment) Act, 1956,","Constitution (Forty-second Amendment) Act, 1976","Constitution (Forty-fourth Amendment) Act, 1978"],"a":2,"x":"Article 48A (protection of environment, forests and wildlife) was added by the 42nd Amendment, 1976.","e":"","src":["Stenographer 26 Nov 2021 S2"]},{"id":"q7019","q":"Goods and Services Tax (GST) has commenced with the enactment of the ________ Constitution Amendment Act.","o":["98th","99th","100th","101st"],"a":3,"x":"GST was introduced by the 101st Amendment Act, 2016; it took effect on 1 July 2017.","e":"","src":["Stenographer 14 Aug 2021"]},{"id":"q5409","q":"Who among the following has never held a position of The Solicitor General of India?","o":["Rohinton Nariman","Ranjit Kumar","Tushar Mehta","Ram Jethmalani"],"a":3,"x":"Rohinton Nariman, Ranjit Kumar and Tushar Mehta have all been Solicitor General; Ram Jethmalani never held the post.","e":"","src":["Personal Assistant 29 Nov 2021 S1"]},{"id":"q5448","q":"The Comptroller and Auditor General of India submits his reports to the _____ of India.","o":["President","Prime Minister","Finance Minister","Chief Justice"],"a":0,"x":"The CAG submits reports on Union accounts to the President, who lays them before Parliament (Article 151).","e":"","src":["Personal Assistant 29 Nov 2021 S2"]},{"id":"q10064","q":"The Comptroller and Auditor-General of India shall hold offi ce for a term of ______ from the date on which he assumes such offi ce.","o":["Seven years","Six years","Five years","Four years"],"a":1,"x":"The CAG holds office for six years or until the age of 65, whichever is earlier.","e":"","src":["Assistant Superintendent 20 Jul 2024 S1"]},{"id":"q10073","q":"The expenses of the Union Public Service commission including any salaries, allowances and pensions payable to or in respect of the members or employees of the Commission shall be charged on which of the following? I Consolidated Fund of India II. Contingency Funds of India","o":["Only I","Both I and II","Only II","Neither I nor II"],"a":0,"x":"UPSC's expenses, including salaries and pensions of its members and staff, are charged on the Consolidated Fund of India (Article 322).","e":"","src":["Assistant Superintendent 20 Jul 2024 S1"]},{"id":"q4492","q":"According to the national parties and their foundation year in India, which of the following pairs is NOT correct?","o":["Bharatiya Janata Party- 1980","Indian National Congress- 1890","Bahujan Samaj Party- 1984","All India Trinamool Congress- 1998"],"a":1,"x":"The Indian National Congress was founded in 1885, not 1890; BJP 1980, BSP 1984 and TMC 1998 are correct.","e":"","src":["Office Superintendent 24 Oct 2021 S2"]},{"id":"q9045","q":"Which Constitutional Amendment mentioned the term 'Cabinet' for the first time?","o":["44th","73rd","42nd","52nd"],"a":0,"x":"The 44th Amendment (1978) first used the word 'Cabinet' in the Constitution, in Article 352.","e":"","src":["MTS 5 Mar 2026 S2"]},{"id":"q9229","q":"Which of the following Constitutional Amendment is INCORRECTLY paired regarding the Eighth Schedule of the Indian Constitution?","o":["Konkani - 71st Amendment Act of 1992","Assamese – 25th Amendment Act of 1971","Sindhi - 21st Amendment Act of 1967","Bodo - 92nd Amendment Act of 2003"],"a":1,"x":"Assamese was in the original Eighth Schedule; Sindhi (21st, 1967), Konkani (71st, 1992) and Bodo (92nd, 2003) were added by amendment.","e":"","src":["MTS 8 Mar 2026 S2"]},{"id":"q9316","q":"Who acts as the chief legal advisor to the Government of India?","o":["Attorney General of India","Law Minister","Chief Justice of India","Solicitor General"],"a":0,"x":"The Attorney General is the Government of India's chief legal adviser (Article 76).","e":"","src":["MTS 24 Feb 2026 S3"]},{"id":"q3442","q":"Which of the following language(s) is/are mentioned in the Indian constitution? I. Punjabi II. Bengali","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Punjabi and Bengali are both among the 22 languages in the Eighth Schedule of the Constitution.","e":"","src":["Store Keeper 19 Apr 2021 S2"]},{"id":"q3444","q":"In which year did the Tenth constitutional amendment of the Indian constitution take place?","o":["1961","1960","1956","1952"],"a":0,"x":"The 10th Amendment Act (1961) made Dadra and Nagar Haveli a Union Territory.","e":"","src":["Store Keeper 19 Apr 2021 S2"]},{"id":"q3889","q":"Which among the following Constitutional Amendment provided for an authoritative text of the Constitution in Hindi language and gave the same legal sanctity to the Hindi version of the Constitution?","o":["58th","36th","72nd","81st"],"a":0,"x":"The 58th Amendment (1987) provided for an authoritative Hindi text of the Constitution, with the same legal sanctity as the English version (Article 394A).","e":"","src":["Store Keeper 22 Apr 2021 S3"]},{"id":"q2996","q":"Which of the following articles of the Indian Constitution empowers Parliament to provide by law for continued use of English for official purposes?","o":["343(1)","340(2)","343(3)","345(4)"],"a":2,"x":"Article 343(3) lets Parliament provide by law for continued use of English for official purposes after 15 years; the Official Languages Act, 1963 did so.","e":"Article 343(1): Hindi in Devanagari is the official language of the Union.","src":["Fee Collector Sub Inspector Auction Recorder 17 Nov 2021 S3"]},{"id":"q2999","q":"Which of the following is a Non-Constitutional body?","o":["NITI Aayog","Special Officer for Linguistic Minorities","Election Commission","Attorney General of India"],"a":0,"x":"NITI Aayog is a non-constitutional (executive) body created by a Cabinet resolution in 2015. The Election Commission, Attorney General and Special Officer for Linguistic Minorities are constitutional.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 17 Nov 2021 S3"]},{"id":"q3274","q":"In which year was the first time 2 election commisioners were appointed in election commission in India?","o":["1989","1994","1991","1992"],"a":0,"x":"In October 1989 two additional Election Commissioners were appointed for the first time; the posts were abolished in 1990 and the Commission became permanently multi-member in 1993.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 18 Nov 2021 S3"]},{"id":"q3933","q":"Who is responsible for the final assent of the amendment bill?","o":["Prime Minister","President","Finance minister","Chief ministers of States"],"a":1,"x":"Under Article 368 a constitutional amendment bill passed by Parliament must be given assent by the President; he cannot withhold it.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S1"]},{"id":"q4030","q":"Which amendment extended the deadline for the cessation for the reservation of seats in the Lok Sabha and state legislatures for members of Scheduled Castes and Scheduled Tribes?","o":["The Constitution (100th Amendment Act), 2015","The Constitution (103rd Amendment Act), 2019","The Constitution (104th Amendment Act), 2020","The Constitution (102nd Amendment Act), 2018"],"a":2,"x":"The 104th Amendment (2019, in force January 2020) extended SC/ST seat reservation in Lok Sabha and state assemblies to 2030 and ended nominated Anglo-Indian seats.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 22 Nov 2021 S3"]},{"id":"q4403","q":"In which year did the first constitutional amendment take place, in India?","o":["1961","1949","1950","1951"],"a":3,"x":"The First Amendment was made in 1951; it added the Ninth Schedule and allowed reasonable restrictions on free speech.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 24 Nov 2021 S1"]},{"id":"q4641","q":"The Representation of People Act, 1951 deals with:","o":["Process of selection for public services","Procedure of elections held in the country","Procedure of bills being raised in the parliament","Eligibility criteria for qualifying scheduled cast or scheduled tribe status"],"a":1,"x":"The Representation of the People Act, 1951 governs the conduct of elections, disqualifications and election disputes.","e":"","src":["Fee Collector Sub Inspector Auction Recorder 25 Nov 2021 S2"]},{"id":"q4089","q":"Part ______ of the Indian Constitution deals with Amendments of the Constitution.","o":["XVI","XIV","XX","XXII"],"a":2,"x":"Part XX (Article 368) deals with amendment of the Constitution.","e":"","src":["Jr. Telephone Operator 23 Apr 2021 S2"]},{"id":"q5480","q":"In which year was the Election Commission of India formed?","o":["1945","1954","1957","1950"],"a":3,"x":"The Election Commission of India was formed on 25 January 1950.","e":"","src":["Accountant 29 Nov 2021 S3"]},{"id":"q1156","q":"What is a key feature of the multi-member Election Commission?","o":["The Commission handles local body elections.","All members share equal decision-making power.","The Chief Election Commissioner has more power.","Only one Commissioner is appointed at a time."],"a":1,"x":"In the multi-member Election Commission (since 1993), the CEC and Election Commissioners have equal powers and salary, and differences are decided by majority.","e":"The CEC can be removed only like a Supreme Court judge.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1210","q":"In which year was the 'Food Safety and Standards Act' enacted to consolidate laws relating to food and lay down science-based standards?","o":["2006","2009","2000","2004"],"a":0,"x":"The Food Safety and Standards Act, 2006 merged earlier food laws and set up FSSAI (2008) to lay down science-based standards for food.","e":"FSSAI works under the Ministry of Health and Family Welfare.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1232","q":"Which of the following accurately reflects the constitutional impact of the 71st Amendment Act?","o":["The legal voting age was reduced and electoral participation expanded.","Rural self-government was constitutionalised through institutional reforms.","The National Capital Territory was given legislative and executive autonomy.","The Eighth Schedule was expanded by recognising three additional regional languages."],"a":3,"x":"The 71st Amendment (1992) added Konkani, Manipuri and Nepali to the Eighth Schedule of languages.","e":"The 92nd Amendment (2003) added Bodo, Dogri, Maithili and Santhali.","src":["PRT 31 Mar 2026 S3"]},{"id":"q3754","q":"In which year did the first election of free India end?","o":["1950","1952","1953","1955"],"a":1,"x":"India's first general election ran from October 1951 to February 1952.","e":"","src":["Nursery Teacher 21 Oct 2021 S1"]},{"id":"q7835","q":"Registration of Births & Deaths Act was enacted in which of the following years?","o":["1960","1965","1969","1971"],"a":2,"x":"The Registration of Births and Deaths Act was enacted in 1969.","e":"","src":["Nursery Teacher 24 Jun 2023 S1"]},{"id":"q1469","q":"Article 315 of the Indian Constitution is related to which of the following?","o":["Finance Commission","Public Service Commissions for the Union and for the States","Administrative tribunals","Election Commission"],"a":1,"x":"Article 315 provides Public Service Commissions for the Union and the states; the functions come under Article 320.","e":"The Finance Commission is Article 280; the Election Commission is Article 324.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1504","q":"The National Commission for Backward Classes consists of a Chairman, Vice-Chairman and _____ members.","o":["3","5","4","6"],"a":0,"x":"The National Commission for Backward Classes, made constitutional by the 102nd Amendment (2018, Article 338B), has a Chairperson, a Vice-Chairperson and three other members.","e":"NCSC = Article 338, NCST = Article 338A.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1525","q":"The National Commission for Scheduled Castes has 1 Chairperson, ______ Vice-Chairperson and ______ members.","o":["1; 3","1; 5","2; 4","2; 3"],"a":0,"x":"The National Commission for Scheduled Castes (Article 338) has a Chairperson, a Vice-Chairperson and three other members, appointed by the President.","e":"The separate National Commission for STs (Article 338A) came with the 89th Amendment (2003).","src":["TGT 24 Aug 2025 S3"]},{"id":"q2315","q":"Which of the following pair of article of Indian constitution is correct? I. Bar to interference by court in electoral matters – Article 329 II. Supreme court of India – Article 318","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Article 329 bars courts from interfering in electoral matters; the Supreme Court is under Article 124, not 318.","e":"","src":["TGT 13 Sep 2021 S3"]},{"id":"q4699","q":"______ allots symbols to political parties in India.","o":["The President","The Party leaders","The Election Commission","The Judiciary"],"a":2,"x":"The Election Commission of India allots symbols to political parties.","e":"","src":["TGT 25 Sep 2021 S1"]},{"id":"q5595","q":"According to which Amendment in the Constitution, reservation for economically weaker sections of the society was implemented?","o":["One Hundred and Fifth Amendment Act, 2020","One Hundred and Third Amendment Act, 2019","One Hundred and First Amendment Act, 2018","One Hundreth Amendment Act, 2019"],"a":1,"x":"The 103rd Amendment (2019) introduced 10% reservation for economically weaker sections.","e":"","src":["TGT 30 Nov 2021 S1"]},{"id":"q6090","q":"The 19th Amendment to the Constitution in 1966:","o":["incorporated Pondicherry into the Indian Union.","added the 9th Schedule to the Constitution.","readjusted the scale of representation in the Lok Sabha.","abolished the system of Election Tribunals and gave High Courts power to hear election petitions."],"a":3,"x":"The 19th Amendment (1966) abolished Election Tribunals and gave High Courts the power to hear election petitions.","e":"","src":["TGT 8 Sep 2021 S3"]},{"id":"q7541","q":"51st amendment of Indian constitution happened in which year?","o":["1973","1989","1984","1969"],"a":2,"x":"The 51st Amendment was passed in 1984.","e":"","src":["TGT 7 Aug 2021"]},{"id":"q7565","q":"Which article of Indian constitution is related with the borrowing by the government of India?","o":["218","326","246","292"],"a":3,"x":"Article 292 deals with borrowing by the Government of India.","e":"","src":["TGT 7 Aug 2021"]},{"id":"q9809","q":"The National Commission for Scheduled Castes consists of 1 Chairman, ______ Vice Chairman/Chairmen, and ______ members.","o":["2; 3","1; 5","1; 3","2; 4"],"a":2,"x":"The National Commission for Scheduled Castes has a Chairperson, a Vice-Chairperson and three other members.","e":"","src":["TGT 24 Aug 2025"]},{"id":"q3040","q":"What is the 127th Constitutional Amendment related to?","o":["Extension for the deadline for cessation for the reservation of seats for members from Schedule castes and Schedule tribes in Lok Sabha.","To restore the power of the states to identify the backward classes.","To amend the provisions of the finance commission.","To amend the village and municipal laws."],"a":1,"x":"The 127th Amendment Bill (2021), passed as the 105th Amendment Act, restored the states' power to prepare their own lists of backward classes.","e":"","src":["Special Educator 17 Oct 2021 S1"]},{"id":"q8800","q":"Which legislation replaced the Major Port Trusts Act, 1963?","o":["Major Port Authorities Act, 2020","Indian Ports Modernisation Act, 2019","Major Port Authorities Act, 2021","Ports Regulation Act, 2018"],"a":2,"x":"The Major Port Authorities Act, 2021 replaced the Major Port Trusts Act, 1963.","e":"","src":["Special Educator 24 Jun 2025 S3"]},{"id":"q0765","q":"Under which Act was the Central Information Commission (CIC) established?","o":["Indian Evidence Act, 1872","Right to Information Act, 2005","Information Technology Act, 2000","Public Records Act, 1993"],"a":1,"x":"The Central Information Commission was set up in 2005 under the Right to Information Act, 2005; it is a statutory body.","e":"It hears appeals when public authorities deny information.","src":["PGT 25 Sep 2025"]},{"id":"q0778","q":"In which year was India's first Armed Forces Tribunal set up?","o":["2011","2009","2012","2010"],"a":1,"x":"The Armed Forces Tribunal was set up under the Armed Forces Tribunal Act, 2007, and started working in August 2009, with its principal bench in New Delhi.","e":"It hears service and court-martial matters of the Army, Navy and Air Force.","src":["PGT 25 Sep 2025"]},{"id":"q0783","q":"Match the Finance Commission with its Chairman: A) Eighth, B) Sixth, C) Eleventh, D) Third — I) A. K. Chanda, II) K. Brahmananda Reddy, III) A. M. Khusro, IV) Y. B. Chavan.","o":["A-I, B-II, C-IV, D-III","A-IV, B-III, C-II, D-I","A-IV, B-II, C-III, D-I","A-I, B-II, C-III, D-IV"],"a":2,"x":"Chairmen: Eighth Finance Commission — Y. B. Chavan; Sixth — K. Brahmananda Reddy; Eleventh — A. M. Khusro; Third — A. K. Chanda.","e":"First Finance Commission: K. C. Neogy. Fifteenth: N. K. Singh. Sixteenth: Arvind Panagariya.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0791","q":"In which of the following years was the Dowry Prohibition Act brought into effect?","o":["1986","2013","2005","1961"],"a":3,"x":"The Dowry Prohibition Act, 1961 makes giving or taking dowry an offence.","e":"Section 80 of the Bharatiya Nyaya Sanhita (earlier IPC 304B) deals with dowry death.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0813","q":"Which of the following is an example of a Constitutional Body in India?","o":["National Human Rights Commission","Central Bureau of Investigation","Election Commission of India","NITI Aayog"],"a":2,"x":"The Election Commission of India is a constitutional body under Article 324. NHRC is statutory; the CBI and NITI Aayog are neither constitutional nor statutory.","e":"Other constitutional bodies: UPSC, Finance Commission, CAG.","src":["PGT 22 Sep 2025"]},{"id":"q0825","q":"In which of the following years was the Family Courts Act introduced in India to promote conciliation in family and marriage-related disputes?","o":["1984","1975","1989","1992"],"a":0,"x":"The Family Courts Act, 1984 set up family courts to settle marriage and family disputes through conciliation.","e":"A state must set up a family court in cities with over 10 lakh population.","src":["PGT 26 Sep 2025"]},{"id":"q0849","q":"Which of the following bodies is responsible for the recruitment of personnel for All India Services?","o":["National Recruitment Agency","Union Public Service Commission","Staff Selection Commission","State Public Service Commission"],"a":1,"x":"The UPSC recruits for the All India Services (IAS, IPS, IFoS) through the Civil Services Examination; the Union government then appoints them.","e":"Article 312 lets Parliament create new All India Services.","src":["PGT 14 Jul 2025"]},{"id":"q0862","q":"Which of the following languages is NOT included in the Eighth Schedule of the Indian Constitution?","o":["Konkani","Magahi","Santhali","Odia"],"a":1,"x":"The 8th Schedule lists 22 languages; Konkani, Manipuri and Nepali were added in 1992 and Santhali, Maithili, Bodo and Dogri in 2003. Magahi is not included.","e":"Odia is among the original 14 languages.","src":["PGT 24 Sep 2025"]},{"id":"q7137","q":"Who was the first Chief Election Commissioner of India?","o":["KV Sundaram","Sukumar Sen","SP Sen Verma","OP Rawat"],"a":1,"x":"Sukumar Sen was India's first Chief Election Commissioner.","e":"","src":["PGT 31 Jul 2021"]},{"id":"q7201","q":"Which among the following Constitutional Amendments included Konkani, Manipuri and Nepali as official languages?","o":["51st","83rd","71st","62nd"],"a":2,"x":"The 71st Amendment (1992) added Konkani, Manipuri and Nepali to the Eighth Schedule.","e":"","src":["PGT 16 Jul 2021 S2"]},{"id":"q7272","q":"Who is the Ex-Officio Chairperson of the NITI Aayog?","o":["Vice President","Home Minister","Prime Minister","President"],"a":2,"x":"The Prime Minister is the ex-officio chairperson of NITI Aayog.","e":"","src":["PGT 10 Jul 2021"]},{"id":"q8127","q":"Under which Article has the National Commission for Backward Classes been given a Constitutional status?","o":["338 B","330","333","361 A"],"a":0,"x":"Article 338B, added by the 102nd Amendment (2018), gave the National Commission for Backward Classes constitutional status.","e":"","src":["PGT 21 Jun 2023 S1"]},{"id":"q8508","q":"Who among the following has never been Chief Election Commissioner of India?","o":["Sukumar Sen","KVK Sundaram","SP Sen Verma","VN Gadgil"],"a":3,"x":"V.N. Gadgil was never Chief Election Commissioner; Sukumar Sen, K.V.K. Sundaram and S.P. Sen Verma were.","e":"","src":["PGT 22 Jun 2023 S2"]},{"id":"q9875","q":"Who has the authority to appoint the Chairperson, Vice-Chairperson, and Members of the National Commission for Backward Classes?","o":["The Speaker of Lok Sabha","Supreme Court of India","The President of India","The Prime Minister of India"],"a":2,"x":"The President appoints the Chairperson, Vice-Chairperson and Members of the National Commission for Backward Classes.","e":"","src":["PGT 25 Sep 2025"]},{"id":"q2790","q":"Who among the following notifies the dates and schedules of elections in India?","o":["Municipal Commissioner","Election Commission","Lok Sabha","Chief Justice of the Supreme Court"],"a":1,"x":"The Election Commission notifies election dates and schedules.","e":"","src":["Inspecting Officer 16 Oct 2021 S1"]},{"id":"q3154","q":"Who among the following was the first chairperson of the Lokpal?","o":["Shri Justice Ranjan Gogoi","Shri Justice Pinaki Chandra Ghose","Sri Justice Arun Mishra","Sri Justice Vikram Nath ·"],"a":1,"x":"Justice Pinaki Chandra Ghose became the first Lokpal chairperson in 2019.","e":"","src":["Pharmacist 18 Nov 2021 S1"]},{"id":"q4263","q":"National Council for Senior Citizens is headed by the:","o":["Vice President","Minister for Social Justice and Empowerment","Prime Minister","Minister of Minority Affairs"],"a":1,"x":"The National Council for Senior Citizens is chaired by the Minister for Social Justice and Empowerment.","e":"","src":["Workshop Instructor 24 Nov 2021 S1"]},{"id":"q4819","q":"The Election Commission of India is a Constitutional Body under which of the following articles of the Constitution of India?","o":["Article 365","Article 370","Article 324","Article 360"],"a":2,"x":"The Election Commission is set up under Article 324.","e":"","src":["Scientific Assistant (Chemistry) 25 Sep 2021 S3"]},{"id":"q5109","q":"Right to Information (RTI) to the Citizens Act was passed in which of the following year?","o":["2002","2003","2004","2005"],"a":3,"x":"The Right to Information Act was passed in 2005.","e":"","src":["Laboratory Assistant (Photo) 26 Sep 2021 S2"]},{"id":"q5623","q":"In which year was ‘The National Human Rights Commission of India’ established?","o":["1995","1993","1998","1991"],"a":1,"x":"The National Human Rights Commission was set up in 1993.","e":"","src":["Labour Welfare Inspector 30 Nov 2021 S2"]},{"id":"q7364","q":"Which article of Indian constitution is related with tenure of office of persons serving the union or a state?","o":["310","323","288","146"],"a":0,"x":"Article 310 says civil servants of the Union or a state hold office during the pleasure of the President or Governor.","e":"","src":["Physical Education Teacher 2 Aug 2021"]},{"id":"q8200","q":"Which of these is NOT a constitutional body?","o":["National Commission for Scheduled Castes","National Commission for Backward Classes","National Commission for Scheduled Tribes","National Commission for Minorities"],"a":3,"x":"The National Commission for Minorities is statutory; the SC, ST and Backward Classes commissions are constitutional.","e":"","src":["Junior Engineer (Electrical) or Section Officer (Electrical) 22 Jun 2022 S1"]},{"id":"q8721","q":"Who among the following can appoint a special officer for linguistic minorities under Article 350 B of the Constitution?","o":["President","Vice President","Parliament","Prime Minister"],"a":0,"x":"Under Article 350B the President appoints a Special Officer for Linguistic Minorities.","e":"","src":["Tailor Master 25 Jun 2023 S3"]},{"id":"q9895","q":"Who amongst the following can be appointed as the Chairperson of the National Human Rights Commission?","o":["Retired Chief Justice of India","Any Legal Practitioner","Retired Judge of the High Court","Retired Chief Justice of the High Court"],"a":0,"x":"A retired Chief Justice of India (or, since 2019, a retired SC judge) can chair the NHRC.","e":"","src":["Scientific Assistant 27 Jul 2024 S2"]}]}]});
